-- A TéT Tudástár kezdő tartalma: a scripts/tudastar-tartalom.ts --sql írta, kézzel ne szerkeszd.
INSERT INTO `tudastar_kartya` (`id`, `kategoria`, `slug`, `tipus`, `nev`, `rovidites`, `osszefoglalo`, `honlap`, `sorrend`, `tartalom`) VALUES ('c30b8425-9905-0998-7d45-8d53755428bb', 'szakpolitika', 'ttm', 'intezmeny', 'Tudományos és Technológiai Minisztérium', 'TTM', 'A 2026-ban létrehozott minisztérium felel a kormányzati tudománypolitikáért és annak koordinációjáért, a KFI-ügyek finanszírozásáért, a mesterséges intelligenciáért, az űriparért, valamint az e-közigazgatásért és a kormányzati informatikáért. Irányítja az NKFI Hivatalt, szakmailag felügyeli a Nemzeti Innovációs Ügynökséget, és itt működik a TéT-attasé hálózatot koordináló főosztály.', 'https://kormany.hu/kormanyzat/tudomanyos-es-technologiai-miniszterium', 1, '{"profil":"A minisztérium angol neve Ministry of Science and Technology. Alapító okirata 2026. május 28-i; jogállását és feladatkörét a Magyarország minisztériumainak felsorolásáról szóló 2026. évi XIII. törvény, a Kormány tagjainak feladat- és hatásköréről szóló 90/2026. (V. 13.) Korm. rendelet (Statútum rendelet) és a 2/2026. (IX. 21.) TTM utasítással kiadott SZMSZ határozza meg.\n\nA Statútum rendelet szerint a tudományos és technológiai miniszter többek között a következőkért felelős:\n- kormányzati tudománypolitika és a tudománypolitika koordinációja,\n- nemzeti adatvagyon-gazdálkodás és mesterséges intelligencia (ezen belül az MI-vel kapcsolatos vállalkozásfejlesztés),\n- űriparfejlesztés és űrtechnológiák (HUNOR Magyar Űrhajós Program, ESA-kapcsolatok),\n- e-közigazgatás, informatika, kiberbiztonság, elektronikus hírközlés,\n- személyiadat- és lakcímnyilvántartás, külföldre utazás szabályozása, köziratkezelés.\n\nA kormányzati tudománypolitikát a miniszter a Magyar Tudományos Akadémia elnökének közreműködésével dolgozza ki. A tudománypolitika koordinációja keretében előkészíti a KFI-ökoszisztéma jogszabályait, felel a KFI-ügyek finanszírozásáért, kapcsolatot tart a HUN-REN Magyar Kutatási Hálózattal, és koordinálja a KFI-ösztönző programok kidolgozását.","tevekenyseg":"A KFI-ügyek a tudománypolitikai és innovációs államtitkárhoz tartoznak. Közvetlenül alá tartozik a Tudományos Nemzetközi Kapcsolatok Főosztály, valamint két helyettes államtitkár:\n- innovációs és technológiai helyettes államtitkár: Innovációs és Startup Főosztály, Technológiai Főosztály (MI-innováció, technológiai szabályozás, élettudományi és egészségipari technológiák, autonóm és intelligens rendszerek, feltörekvő technológiák), Űrpolitikai Főosztály;\n- tudománypolitikai helyettes államtitkár: Tudománypolitikai Főosztály, Kutatási Intézményrendszer Főosztály, Kutatói Kiválósági Főosztály.\n\nAz államtitkár a miniszter iránymutatása alapján rendelkezik a Nemzeti Kutatási, Fejlesztési és Innovációs Alap (NKFI Alap) felett, és felel annak szakpolitikai és stratégiai tervezéséért. Az NKFI Hivatal irányítását a minisztérium a tudománypolitikai és innovációs államtitkáron keresztül gyakorolja; a Nemzeti Innovációs Ügynökség felett ugyanő gyakorolja a szakmai felügyeletet.\n\nA digitalizációs államtitkár viszi az e-közigazgatást, a kormányzati informatikát és a kiberbiztonságot; a mesterséges intelligenciáért külön helyettes államtitkár felel.","kapcsolat":{"email":"ugyfelszolgalat@ttm.gov.hu","telefon":"","cim":"1011 Budapest, Vám utca 5–7."},"szakaszok":[{"cim":"KFI-stratégia","szoveg":"A KFI-törvény szerint a középtávú KFI-stratégiát a Kormány alkotja meg. A TTM SZMSZ-e szerint a tudománypolitikai és innovációs államtitkár az érintett szakterületekkel együttműködve meghatározza és végrehajtja Magyarország 2026–2034 közötti KFI-stratégiáját, és koordinálja az ehhez kapcsolódó kormányzati tevékenységet.\n\nA stratégia kidolgozásának keretei:\n- a kormányzati tudománypolitikát a miniszter az MTA elnökének közreműködésével dolgozza ki;\n- az államtitkár koordinálja az uniós és hazai KFI-források stratégiai felhasználását, és kidolgozza az uniós programozási időszakok KFI-vonatkozású programrészeinek koncepcióját;\n- a stratégiai célok egyik fő eszköze az NKFI Alap, amelynek éves programstratégiája határozza meg a meghirdetendő pályázatokat.\n\nAz NKFI Alap 2026. évi, még 2025 végén, a kormányváltás előtt elfogadott programstratégiája (mintegy 120 Mrd Ft) a Neumann János Program céljaihoz igazodik; az új KFI-stratégia elfogadott szövegét a tartalom összeállításakor nem találtuk."},{"cim":"Prioritások","szoveg":"Az SZMSZ-ben rögzített feladatok alapján a minisztérium KFI-prioritásai:\n- a KFI-t ösztönző szakpolitikai eszközök, köztük az adórendszeren belüli közvetett támogatások fejlesztése;\n- az alapkutatás, a kutatási kiválóság, a kutatási infrastruktúrák és a nemzetközi tudományos együttműködések ösztönzése;\n- szemléletváltó, misszió alapú stratégiai projektek indítása;\n- a nemzeti startup-ökoszisztéma fejlesztése, az innovatív vállalkozások finanszírozási ösztönzőrendszere és a nemzeti startupprogramok koordinálása (a Gazdasági és Energetikai Minisztériummal közösen);\n- a technológiatranszfer szabályozási és intézményi keretei, az egyetem–ipar–állam együttműködés;\n- az inkubációs és akcelerációs intézményrendszer, valamint a Tudományos és Innovációs Parkok (Science Park) kialakítása;\n- az innovációs és szellemitulajdon-védelmi tudatosság erősítése, innovációs képzések.\n\nA TTM 2026. augusztus 31-i közleménye szerint a kormány három év alatt megduplázná az NKFI Alap forrásait (így azok elérhetnék a 225 Mrd Ft-ot), egyszerűsítené a cégalapítást, a 2026/2027-es tanévtől a középiskolákban is elindítaná az innovációs oktatást, és a magyar uniós részvétel erősítésére tudományos és technológiai irodát nyitna Brüsszelben. Ezek a közleményben bejelentett tervek."},{"cim":"Kiemelt ágazatok","szoveg":"A minisztérium szervezete és feladatköre alapján kiemelt technológiai területek:\n- mesterséges intelligencia: nemzeti MI-stratégia, kormányzati MI-alkalmazások, nagy teljesítményű számítási (HPC) és szuverén számítási infrastruktúra, MI-piacfelügyelet;\n- űripar és űrtechnológiák: űripari stratégia, nemzetközi képviselet, az Európai Űrügynökséggel (ESA) kapcsolatos feladatok, HUNOR Magyar Űrhajós Program;\n- élettudományi és egészségipari technológiák;\n- autonóm és intelligens rendszerek, robotika;\n- félvezető-ökoszisztéma (stratégia és zászlóshajó projektek), valamint az 5G-, drón-, blokklánc- és Ipar 4.0-technológiák platformjai;\n- feltörekvő technológiák;\n- digitális állam, adatgazdaság és kiberbiztonság.\n\nAz ágazati innováció egy része más tárcáknál van: az egészségügyi innováció az Egészségügyi Minisztériumnál, az agrár-KFI az Agrár- és Élelmiszergazdaságért Felelős Minisztériumnál, a védelmi innováció a Honvédelmi Minisztériumnál, az iparügyek és az atomenergia-ipar innovációs feladatai a Gazdasági és Energetikai Minisztériumnál."},{"cim":"Kapcsolódás a TéT-attasé hálózathoz","szoveg":"A minisztériumban a nemzetközi és európai uniós helyettes államtitkár a digitalizációs államtitkárral és a tudománypolitikai és innovációs államtitkárral együttműködve koordinálja a tudományos és technológiai attasék munkáját.\n\nA Tudományos és Technológiai Attasé Hálózat Koordinációjáért Felelős Főosztály:\n- előkészíti a két- és többoldalú kormányközi TéT-egyezményeket és a kétoldalú TéT-munkaterveket, gondoskodik végrehajtásukról;\n- a kétoldalú kormányközi TéT-tárgyalásokon és a vegyes bizottsági üléseken ellátja a magyar képviseletet; a közös TéT-pályázatokat az NKFI Hivatal írja ki;\n- az NKFI Hivatallal együttműködve ellátja a Svájci Finanszírozási Mechanizmus kétoldalú kutatási együttműködéseivel kapcsolatos feladatokat;\n- a Külügyminisztérium útján tartja a kapcsolatot a külképviseletekkel, és a Külügyminisztériummal együttműködve részt vesz a hálózat szakmai irányításában;\n- az NKFI Hivatallal együttműködve látja el a szakdiplomata-hálózat kialakításával, működtetésével és szakmai irányításával kapcsolatos minisztériumi feladatokat.\n\nA nemzetközi tudományos és innovációs együttműködések szakmai gazdája a Tudományos Nemzetközi Kapcsolatok Főosztály."}],"programok":[],"linkek":[{"felirat":"A TTM Szervezeti és Működési Szabályzata (2/2026. (IX. 21.) TTM utasítás)","url":"https://njt.jog.gov.hu/jogszabaly/2026-2-B0-9N"},{"felirat":"A Kormány tagjainak feladat- és hatásköre (90/2026. (V. 13.) Korm. rendelet)","url":"https://njt.jog.gov.hu/jogszabaly/2026-90-20-22"},{"felirat":"A KFI-törvény (2014. évi LXXVI. törvény)","url":"https://njt.jog.gov.hu/jogszabaly/2014-76-00-00"},{"felirat":"Kormányzati elérhetőségek","url":"https://kormany.hu/kormanyzati-elerhetosegek"},{"felirat":"Új program a doktoranduszoknak – az államtitkár a tudományos és innovációs tervekről (TTM, 2026. augusztus 31.)","url":"https://kormany.hu/hirek/uj-program-a-doktoranduszoknak"}]}');
--> statement-breakpoint
INSERT INTO `tudastar_kartya` (`id`, `kategoria`, `slug`, `tipus`, `nev`, `rovidites`, `osszefoglalo`, `honlap`, `sorrend`, `tartalom`) VALUES ('33497a77-92ef-5a19-90ee-7bdad08677b2', 'szakpolitika', 'agazati-miniszteriumok', 'lista', 'Az innovációhoz kapcsolódó ágazati minisztériumok', NULL, 'A 90/2026. (V. 13.) Korm. rendelet szerint a KFI-hez kapcsolódó ágazati feladatok több tárcán oszlanak meg. A lista a minisztériumok KFI-szempontból fontos hatásköreit mutatja; a központi e-mail-címek és postacímek a kormányzati elérhetőségek oldalán találhatók.', NULL, 2, '{"sorok":[{"nev":"Gazdasági és Energetikai Minisztérium (GEM)","url":"https://kormany.hu/kormanyzat/gazdasagi-es-energetikai-miniszterium","megjegyzes":"Gazdaságfejlesztés, iparügyek, vállalkozásfejlesztés, külgazdaság (a külgazdasági diplomata-hálózat is); az atomenergia-ipar innovációja. A startup-ökoszisztéma irányait a TTM-mel közösen alakítja."},{"nev":"Oktatási és Gyermekügyi Minisztérium (OGYM)","url":"https://kormany.hu/kormanyzat/oktatasi-es-gyermekugyi-miniszterium","megjegyzes":"Felsőoktatás; az egyetemekkel megvalósuló tudományos innovációs parkok, nemzeti laborok és kiválósági központok kormányzati koordinációja."},{"nev":"Külügyminisztérium (KÜM)","url":"https://kormany.hu/kormanyzat/kulugyminiszter","megjegyzes":"Az érintett miniszterrel együtt irányítja a tudománydiplomáciát, ellátja a Stipendium Hungaricum működtetési feladatait; a TéT-attasé hálózat szakmai irányításában a TTM-mel működik együtt."},{"nev":"Agrár- és Élelmiszergazdaságért Felelős Minisztérium (AEM)","url":"https://kormany.hu/kormanyzat/agrar-es-elelmiszergazdasagi-miniszterium","megjegyzes":"Az agrár-KFI feladatok koordinációja, a mezőgazdasági ismeret- és innovációs rendszer (AKIS) és az agrárdigitalizáció."},{"nev":"Egészségügyi Minisztérium (EüM)","url":"https://kormany.hu/kormanyzat/egeszsegugyi-miniszterium","megjegyzes":"Az egészségügyi innováció és az emberen végzett orvostudományi kutatások; a gyógyszerpolitika, a gyógyászati segédeszközök és az orvostechnikai eszközök."},{"nev":"Honvédelmi Minisztérium (HM)","url":"https://kormany.hu/kormanyzat/honvedelmi-miniszterium","megjegyzes":"A védelmi innováció stratégiai fejlesztési irányai, a védelmi és hadfelszerelési fejlesztések stratégiája."},{"nev":"Közlekedési és Beruházási Minisztérium (KBM)","url":"https://kormany.hu/kormanyzat/kozlekedesi-es-beruhazasi-miniszterium","megjegyzes":"Az európai uniós források hazahozatalának és felhasználásának koordinációja."},{"nev":"Vidék- és Településfejlesztési Minisztérium (VTM)","url":"https://kormany.hu/kormanyzat/videk-es-telepulesfejlesztesi-miniszterium","megjegyzes":"Az uniós források felhasználásáért felelős tárca: koordinálja a közvetlen uniós forrásokat, ösztönzi lehívásukat, és működteti az önerő- és előkészítésiköltség-támogatási mechanizmust."}],"linkek":[{"felirat":"Kormányzati elérhetőségek","url":"https://kormany.hu/kormanyzati-elerhetosegek"},{"felirat":"A Kormány tagjainak feladat- és hatásköre (90/2026. (V. 13.) Korm. rendelet)","url":"https://njt.jog.gov.hu/jogszabaly/2026-90-20-22"}]}');
--> statement-breakpoint
INSERT INTO `tudastar_kartya` (`id`, `kategoria`, `slug`, `tipus`, `nev`, `rovidites`, `osszefoglalo`, `honlap`, `sorrend`, `tartalom`) VALUES ('0b6b68eb-776a-a522-a6da-96de59d5fd09', 'szakpolitika', 'kfi-koordinacios-testuletek', 'lista', 'KFI-koordinációs és döntés-előkészítő testületek', NULL, 'A tudomány- és innovációpolitika kormányzati döntés-előkészítésének testületei. A Nemzeti Tudománypolitikai Tanácsot és a Kutatási Kiválósági Tanácsot a KFI-törvény hozza létre; a kormányzati döntés fóruma a Fejlesztési Kabinet.', NULL, 3, '{"sorok":[{"nev":"Nemzeti Tudománypolitikai Tanács (NTT)","url":"https://njt.jog.gov.hu/jogszabaly/2014-76-00-00","megjegyzes":"KFI tv. 10/A. §: 12 tagú véleményező testület, elnöke a TTM minisztere. A TTM SZMSZ-e Nemzeti Tudománypolitikai, Technológiai és Innovációs Tanácsként említi; titkársági feladatait a TTM látja el."},{"nev":"Kutatási Kiválósági Tanács (KKT)","url":"https://nkfih.gov.hu/hivatalrol/testuletek-bizottsagok/kutatasi-kivalosagi-tanacs","megjegyzes":"KFI tv. 10/D. §: héttagú, kutatókból álló testület; a kiválósági alapú kutatási támogatások döntés-előkészítője. Titkársága az NKFI Hivatal."},{"nev":"Fejlesztési Kabinet","url":"https://njt.jog.gov.hu/jogszabaly/2026-90-20-22","megjegyzes":"A Kormány ügydöntő fóruma többek között a kormányzati tudománypolitika, a tudománypolitika koordinációja és az űripar ügyeiben (90/2026. Korm. rendelet 197/A. §)."}],"linkek":[]}');
--> statement-breakpoint
INSERT INTO `tudastar_kartya` (`id`, `kategoria`, `slug`, `tipus`, `nev`, `rovidites`, `osszefoglalo`, `honlap`, `sorrend`, `tartalom`) VALUES ('03d75ffa-807e-5cb6-f5c0-163cc0713e66', 'szakpolitika', 'strategiai-tanacsado-szervezetek', 'lista', 'Stratégiai és tanácsadó szervezetek', NULL, 'A tudománypolitika kidolgozásában jogszabály vagy hagyomány alapján szerepet vállaló köztestületek és képviseleti szervezetek. Jó belépési pontok, ha a magyar tudományos közösség álláspontjára vagy partnerintézményekre van szükség.', NULL, 4, '{"sorok":[{"nev":"Magyar Tudományos Akadémia (MTA)","url":"https://mta.hu/","megjegyzes":"Elnöke közreműködik a kormányzati tudománypolitika kidolgozásában, és társjavaslattevő a KKT tagjainál. Itt működik az ERC nemzeti kapcsolattartó pontja."},{"nev":"HUN-REN Magyar Kutatási Hálózat","url":"https://hun-ren.hu/","megjegyzes":"A közfinanszírozott kutatóközpontokat és -intézeteket összefogó hálózat; a TTM tudománypolitikai ügyekben kapcsolatot tart vele, elnöke társjavaslattevő a KKT tagjainál. Bővebben: 4. kategória."},{"nev":"Magyar Rektori Konferencia (MRK)","url":"https://mrk.hu/","megjegyzes":"A felsőoktatási intézmények vezetőinek testülete; Nemzetközi Bizottsága a nemzetközi mobilitási és kutatási együttműködésekkel is foglalkozik."}],"linkek":[]}');
--> statement-breakpoint
INSERT INTO `tudastar_kartya` (`id`, `kategoria`, `slug`, `tipus`, `nev`, `rovidites`, `osszefoglalo`, `honlap`, `sorrend`, `tartalom`) VALUES ('bec69972-aca2-0bc3-138d-837c71cc12a5', 'finanszirozas', 'nkfih', 'intezmeny', 'Nemzeti Kutatási, Fejlesztési és Innovációs Hivatal', 'NKFIH', 'A KFI-törvény alapján 2015-ben létrehozott központi hivatal a Tudományos és Technológiai Minisztérium irányítása alatt működik, és a legjelentősebb állami KFI-finanszírozó: kezeli a Nemzeti Kutatási, Fejlesztési és Innovációs Alapot (NKFI Alap). Működteti a Horizont Európa nemzeti kapcsolattartói hálózatát, kiírja a nemzetközi együttműködéseket támogató hazai pályázatokat, és kezeli a Kormányzati Önerő Alapot.', 'https://nkfih.gov.hu/', 1, '{"profil":"Az NKFI Hivatalt a tudományos kutatásról, fejlesztésről és innovációról szóló 2014. évi LXXVI. törvény hozta létre, hogy a kutatás-fejlesztés és innováció kormányzati koordinációjának és kiszámítható finanszírozásának stabil intézményi rendszere legyen. A Statútum rendelet szerint a hivatalt a tudományos és technológiai miniszter irányítja; a minisztériumban ezt a tudománypolitikai és innovációs államtitkár gyakorolja.\n\nA hivatal saját bemutatása szerint több mint 200 munkatárssal a legjelentősebb állami közfinanszírozó a KFI területén. Az NKFI Alap forrásainak felhasználására többszintű pályázatértékelési rendszert működtet akadémiai és üzleti szakértőkkel, ellenőrzi a támogatások felhasználását, és méri a projektek hatását.\n\nAz NKFI Hivatal a Nemzeti Innovációs Ügynökség tulajdonosi joggyakorlója. A TTM SZMSZ-e szerint a minisztérium TéT-attasé hálózatot koordináló főosztálya az NKFI Hivatallal együttműködve látja el a tudományos és technológiai szakdiplomata-hálózattal kapcsolatos minisztériumi feladatokat.","tevekenyseg":"- Az NKFI Alap felhívásainak kiírása, értékelése, a szerződések és projektek követése.\n- A Horizont Európa nemzeti kapcsolattartói (NCP) hálózatának működtetése, a magyar álláspont képviselete a programbizottságokban.\n- A magyar részvétel koordinálása a társfinanszírozott nemzetközi programokban (EUREKA, Eurostars, európai partnerségek, ERA-NET-ek); a COST nemzeti koordinátora is a hivatalnál működik.\n- A Kutatási Kiválósági Tanács titkárságának ellátása.\n- Közreműködés a KFI-stratégiák összeállításában és megvalósításában, az innovációs ökoszisztéma fejlesztésében (pl. a GINOP Plusz „KFI ökoszisztéma fejlesztése” kiemelt projekt konzorciumvezetőjeként, a NIÜ-vel).\n- A Kormányzati Önerő Alap és a Horizont Jogsegély Hotline működtetése.","kapcsolat":{"email":"nkfihivatal@nkfih.gov.hu","telefon":"+36 1 795 9500","cim":"1077 Budapest, Kéthly Anna tér 1."},"szakaszok":[{"cim":"Feladat- és hatáskör","szoveg":"Az NKFI Hivatal elsődlegesen az NKFI Alapból finanszírozott versenypályázatok rendszerével támogatja a KFI-t. Kiemelt célterületei:\n- a piaci szereplők innovációs tevékenysége és az eredmények piaci hasznosítása;\n- a KFI-ökoszisztéma szereplőinek összekapcsolása szakmai együttműködésekkel;\n- a kutatói utánpótlás hosszú távú biztosítása;\n- a hazai kutatók bekapcsolása a nemzetközi tudományos vérkeringésbe.\n\nA pályázati rendszeren túl közreműködik a KFI-stratégiákban, az innovációs ökoszisztéma fejlesztésében és a KFI-fókuszú nemzetközi és európai együttműködések szakmai feladataiban. Pályázati ügyekben az ügyfélszolgálat elérhetősége: nkfialap@nkfih.gov.hu, +36 1 795 9500; hivatali ügyekben: nkfihivatal@nkfih.gov.hu."},{"cim":"Az NKFI Alap programstratégiája","szoveg":"Az NKFI Alap a KFI-törvény szerint három alaprészből áll:\n- Innovációs Alaprész: vállalati innováció és piacorientált, részben üzleti–tudományos együttműködésben megvalósuló K+F; itt jelennek meg a nemzetközi programok is;\n- Kutatási Alaprész: kiszámítható kutatásfinanszírozás, a kutatói pálya elején járók támogatása; a kiválósági alapú felhívásokra a Kutatási Kiválósági Tanács tesz javaslatot;\n- Missziók Alaprész (2025 óta): stratégiailag fontos területeken nagy társadalmi vagy gazdasági hatású K+F-programok; 2026-ban ebből hirdették meg a nemzeti laboratóriumok misszióvezérelt továbbfejlesztését és a HU-rizont programot.\n\nA nemzeti laboratóriumok 2022-ben még külön alaprészből indultak.\n\nAz NKFI Alap kezeléséért a tudománypolitika koordinációjáért felelős miniszter – ma a tudományos és technológiai miniszter – felel: ő hagyja jóvá az éves programstratégiát, és ő dönt az Innovációs és a Missziók Alaprész támogatásairól. A felhívásokban 2026. május 14. óta a Tudományos és Technológiai Minisztérium a Támogató.\n\nAz éves programstratégia határozza meg a meghirdetendő felhívásokat és kereteiket. A 2026. évi programstratégiát még 2025 novemberében, a kormányváltás előtt fogadták el; mintegy 120 Mrd Ft-tal számol, céljai a vállalatok és egyetemek együttműködése, a kutatói létszám növelése, a szabadalmi bejelentések megduplázása és az innovatív vállalkozások arányának emelése, harmadik nagy célterületként a missziókkal. Újdonságként a vissza nem térítendő támogatások mellett állami társfinanszírozású kockázatitőke-alapokat is tervez.\n\nA TTM 2026. augusztusi közleménye szerint a kormány három év alatt megduplázná az NKFI Alap forrásait; ez egyelőre bejelentés."},{"cim":"Aktuális hazai és nemzetközi pályázatok","szoveg":"Nyitott felhívások a 2026. november 2-i állapot szerint (NKFI Alap):\n- Európai kutatási-innovációs szakmai szervezetekben való részvétel (2026-1.2.3-NETWORKING): 2–6 MFt, felsőoktatási és kutatóintézményeknek, határidő 2026. november 20.;\n- szellemitulajdon-védelem (2025-1.1.1-IPARJOG): 0,01–7,5 MFt, határidő 2026. december 18.;\n- magyar részvétel az EUREKA-programban (2025-1.2.2-EUREKA): 20–70 MFt, negyedéves beadási határnapokkal 2027. október 15-ig.\n\nAz NKFI Hivatal az NCP_WIDERA.NET uniós projekt forrásából hirdeti a WIDERA Travel Grants támogatást: legfeljebb 1000 euró a Horizont Európa partnerkereső rendezvényeinek útiköltségére, 2027. január 31-ig.\n\nA Széchenyi Terv Plusz programjai közül az NKFI Hivatal felhívásai között szerepel a Korai fázisú kutatás-fejlesztési kockázati tőkeprogram (GINOP Plusz-2.5.1-25) és a Technológiaspecifikus Kockázati Tőkeprogram (GINOP Plusz-2.5.2-26).\n\nA 2026-ban meghirdetett, beadási határidejük szerint már lezárult pályázatok közül kiemelendő a HU-rizont nemzetközi kiválósági kutatási együttműködési program (8 Mrd Ft), a kétoldalú TéT-pályázat (kínai és francia reláció), a Misszióvezérelt Nemzeti Laboratóriumok továbbfejlesztése (2026. augusztus 27-i döntés: 14 projekt, összesen 20,92 Mrd Ft) és a technológiatranszfer-cégek hálózatának fejlesztése (6 Mrd Ft; eredményét még nem közölték).\n\nA Horizont Európa nyitott és várható felhívásait az NKFI Hivatal kereshető listában is közli."},{"cim":"A pályázatok célcsoportjai","szoveg":"Az NKFI Hivatal támogatásainak fő célcsoportjai:\n- innovatív vállalkozások (kkv-k és nagyvállalatok) a magasabb hozzáadott érték és a piaci hasznosítás érdekében;\n- egyetemek és más kutatóhelyek a KFI-kapacitás bővítésére;\n- kutatók és kutatói közösségek kiválósági alapon, köztük egyetemi és doktori hallgatók, posztdoktorok és fiatal kutatók.\n\nA felhívások pályázói körei: felsőoktatási intézmény, HUN-REN- és MTA-intézmény, egyéb költségvetési kutatóhely, vállalkozói kutatóhely, vállalkozás, nonprofit kutatóhely és szervezet, illetve magánszemély.\n\nKülföldi partner a felhívás feltételei szerint kapcsolódhat be: a HU-rizont programban például alvállalkozóként vagy megbízottként, a kétoldalú TéT-pályázatokban pedig úgy, hogy a közös projektet a külföldi fél a saját országa finanszírozójánál nyújtja be."},{"cim":"Nemzetközi partnerkeresés és társfinanszírozás","szoveg":"- Horizont Európa NCP-k: ingyenes információs napok, tanácsadás, közreműködés a projektpartnerek keresésében (ncp@nkfih.gov.hu), heti HorizontPéntek10 webinárium.\n- WIDERA Travel Grants: utófinanszírozás (legfeljebb 1000 euró) a II. pillér klasztereinek, a missziók és az európai partnerségek konzorciumépítő rendezvényein való részvételhez.\n- Partnerségi (társfinanszírozott) konstrukciók: a nemzetközi közös felhívásokon nyertes magyar partnerek a nemzeti részt az NKFI Alapból kapják (európai partnerségek, ERA-NET Cofund, EJP Cofund).\n- EUREKA és Eurostars: piacközeli nemzetközi K+F-együttműködés, különösen kkv-knak; az EUREKA-projektek magyar résztvevőit a 2025-1.2.2-EUREKA felhívás támogatja.\n- Kétoldalú TéT-pályázatok: a partnerek közös projektet dolgoznak ki, a magyar fél az NKFI Hivatalhoz, a külföldi a saját finanszírozójához nyújtja be; a támogatás a kutatói mobilitást és a szakembercserét fedezi.\n- HU-rizont: magyar felsőoktatási intézmény vezette, nemzetközi együttműködésben megvalósuló kutatási programok.\n\nA kétoldalú kormányközi TéT-egyezmények és munkatervek előkészítése, végrehajtása és a vegyes bizottsági képviselet a Tudományos és Technológiai Minisztérium TéT-attasé hálózatot koordináló főosztályáé; a közös pályázatokat az NKFI Hivatal írja ki."},{"cim":"Kormányzati Önerő Alap és más társfinanszírozási konstrukciók","szoveg":"A Kormányzati Önerő Alap (KÖA) az (EU) 2022/2506 tanácsi végrehajtási határozat hatálya alá tartozó szervezeteknek – a közérdekű vagyonkezelő alapítványoknak és az általuk fenntartott intézményeknek – nyújtott pályázati forrást helyettesítő támogatást a nyertes Horizont Európa-, Erasmus+ és más uniós KFI- vagy oktatási projektekben: a tervezett költség 100%-áig, egy összegben igényelhető előleggel. A 2026-1.2.1-KÖA felhívásra 2026. október 30-ig lehetett kérelmet benyújtani.\n\n2026. október 13-án az EU Általános Ügyek Tanácsa lezárta a Magyarország elleni feltételességi eljárást, a korlátozó határozat október 14-én hatályát vesztette. Az érintett intézmények azóta ismét kedvezményezettként és koordinátorként is részt vehetnek a közvetlen uniós programokban; a már aláírt támogatási szerződések módosítását a konzorciumnak kell kezdeményeznie, és a módosítás nem visszamenőleges. Az érintett szervezeteknek az NKFI Hivatal Horizont Jogsegély Hotline-ja ad szakmai támogatást. A 2026. október 14. előtt benyújtott pályázatokban társult partnerként részt vevő intézmények továbbra is a KÖA-ból kérhetnek támogatást; a TTM tervei szerint a konstrukció 2027-ben is elérhető lesz, de új felhívás csak a 2027. évi költségvetési törvény és az NKFI Alap 2027. évi programstratégiájának elfogadása után jelenhet meg.\n\nTovábbi társfinanszírozás: a Horizont Európa európai partnerségek és az ERA-NET Cofund programok nyertes magyar résztvevőinek nemzeti támogatása (2024-1.2.1-HE_PARTNERSÉG, 2024-1.2.2-ERA_NET) és a Digitális Kulcstechnológiák (KDT) partnerségbe való bekapcsolódás támogatása (2024-1.2.4-KDT) – e három felhívás beadási határideje 2026. október 30-án lejárt –, valamint az EUREKA-részvétel támogatása (2025-1.2.2-EUREKA, 2027. október 15-ig)."}],"programok":[{"nev":"Európai kutatási-innovációs szakmai szervezetekben való részvétel támogatása (2026-1.2.3-NETWORKING)","url":"https://nkfih.gov.hu/palyazoknak/nkfi-alap/europai-kutatasi-innovacios-szakmai-szervezetekben-valo-reszvetel-tamogatasa-2026-123-networking/palyazati-felhivas","leiras":"Felsőoktatási és kutatóintézmények aktív részvétele a keretprogramokat alakító európai KFI-szakmai szervezetek munkájában (önállóan tagdíj nem támogatható); 2–6 MFt, határidő 2026. november 20."},{"nev":"Az EUREKA programban való magyar részvétel támogatása (2025-1.2.2-EUREKA)","url":"https://nkfih.gov.hu/palyazoknak/nkfi-alap/eureka-programban-valo-magyar-reszvetel-tamogatasa-2025-122-eureka/palyazati-felhivas","leiras":"Nemzetközi EUREKA-projektek (alkalmazott kutatás, kísérleti fejlesztés) magyar résztvevőinek támogatása; 20–70 MFt, negyedéves határnapokkal, utoljára 2027. október 15-én."},{"nev":"Szellemi alkotások szellemitulajdon-védelmének támogatása (2025-1.1.1-IPARJOG)","url":"https://nkfih.gov.hu/palyazoknak/nkfi-alap/szellemi-alkotasok-szellemi-tulajdon-vedelme-2025-111-iparjog/palyazati-felhivas","leiras":"Hazai és nemzetközi szellemitulajdon-védelmi tevékenységek támogatása; 0,01–7,5 MFt, határidő 2026. december 18."},{"nev":"WIDERA Travel Grants","url":"https://nkfih.gov.hu/palyazoknak/egyeb-tamogatas/horizont-europa-2-piller-partnerkereso-rendezvenyen-reszvetel-widera-travel-grants/palyazati-felhivas","leiras":"Legfeljebb 1000 euró utófinanszírozás a Horizont Európa II. pillér partnerkereső rendezvényein való részvételhez, 2027. január 31-ig (forrása az NCP_WIDERA.NET uniós projekt)."}],"linkek":[{"felirat":"Aktuális pályázati felhívások","url":"https://nkfih.gov.hu/palyazoknak/palyazatok/aktualis-felhivasok"},{"felirat":"Az NKFI Alap 2026. évi programstratégiája","url":"https://nkfih.gov.hu/hivatalrol/kfi-szakpolitika/programstrategia-2026"},{"felirat":"Az NKFI Alap felépítése","url":"https://nkfih.gov.hu/palyazoknak/kfi-palyazatok/nkfi-alap-felepitese"},{"felirat":"Kormányzati Önerő Alap","url":"https://nkfih.gov.hu/palyazoknak/kormanyzati-onero-alap"},{"felirat":"A korlátozás megszűnése (2026. október)","url":"https://nkfih.gov.hu/hivatalrol/hivatal-hirei/megszunt-korlatozas"},{"felirat":"Európai partnerségek – gyakorlati útmutató (NKFIH)","url":"https://horizonteuropa.nkfih.gov.hu/horizont-europa-program/partnersegek/partnerseg-attekintes"},{"felirat":"Ügyfélszolgálat, kapcsolat","url":"https://nkfih.gov.hu/palyazoknak/ugyfelszolgalat/kapcsolat"}]}');
--> statement-breakpoint
INSERT INTO `tudastar_kartya` (`id`, `kategoria`, `slug`, `tipus`, `nev`, `rovidites`, `osszefoglalo`, `honlap`, `sorrend`, `tartalom`) VALUES ('d393ce75-a6f7-ee4a-f2bb-7b1ca4e80e74', 'finanszirozas', 'hazai-tamogataskezelok', 'lista', 'Hazai KFI-támogatások kezelői', NULL, 'A hazai forrásból finanszírozott KFI-támogatások gazdái: ki dönt a keretekről, és ki írja ki a pályázatokat. A legnagyobb tétel az NKFI Alap; a vállalkozásfinanszírozás állami hitel-, tőke- és garanciaprogramjai a gazdaságfejlesztési tárcához tartoznak.', NULL, 2, '{"sorok":[{"nev":"Nemzeti Kutatási, Fejlesztési és Innovációs Hivatal (NKFIH)","url":"https://nkfih.gov.hu/palyazoknak/palyazatok/aktualis-felhivasok","megjegyzes":"Az NKFI Alap felhívásainak kiírója és kezelője. Pályázati ügyfélszolgálat: nkfialap@nkfih.gov.hu, +36 1 795 9500."},{"nev":"Tudományos és Technológiai Minisztérium (TTM)","url":"https://kormany.hu/kormanyzat/tudomanyos-es-technologiai-miniszterium","megjegyzes":"Felel az NKFI Alap kezeléséért: a miniszter hagyja jóvá az éves programstratégiát, és ő dönt az Innovációs és a Missziók Alaprész támogatásairól."},{"nev":"Gazdasági és Energetikai Minisztérium (GEM)","url":"https://kormany.hu/kormanyzat/gazdasagi-es-energetikai-miniszterium","megjegyzes":"Vállalkozásfejlesztés; javaslatok a kkv-k finanszírozására (kamattámogatott hitel-, tőke- és garanciaprogramok); előterjeszti az állami pénzintézetek stratégiáját, és felügyeli végrehajtását."},{"nev":"Nemzeti Innovációs Ügynökség (NIÜ)","url":"https://niu.hu/services","megjegyzes":"Innovációs szolgáltatások és támogatások: Innovációs Voucher Program, mentorálás; évente kiírt pályázatok (HSUP Growth Fund, startup-rendezvények; a 2026-os körök lezárultak). Lásd 3. kategória."}],"linkek":[]}');
--> statement-breakpoint
INSERT INTO `tudastar_kartya` (`id`, `kategoria`, `slug`, `tipus`, `nev`, `rovidites`, `osszefoglalo`, `honlap`, `sorrend`, `tartalom`) VALUES ('3db9a55a-ad33-ec82-807c-89c7c6a1ce92', 'finanszirozas', 'unios-tamogataskezelok', 'lista', 'Uniós KFI-támogatások kezelői és belépési pontjai', NULL, 'A közvetlen uniós programokat (Horizont Európa, EIC) az Európai Bizottság és végrehajtó ügynökségei kezelik; a magyar pályázókat az NKFI Hivatal kapcsolattartói segítik. Az uniós kohéziós források (Széchenyi Terv Plusz) felhívásai hazai kezelésben, a pályázati portálon jelennek meg.', NULL, 3, '{"sorok":[{"nev":"Európai Bizottság – Funding & Tenders Portal","url":"https://ec.europa.eu/info/funding-tenders/opportunities/portal/screen/home","megjegyzes":"A Bizottság által kezelt programok (köztük a Horizont Európa) felhívásainak, partnerkeresésének és pályázatbenyújtásának egységes belépési pontja."},{"nev":"Horizont Európa (Európai Bizottság)","url":"https://research-and-innovation.ec.europa.eu/funding/funding-opportunities/funding-programmes-and-open-calls/horizon-europe_en","megjegyzes":"Az EU 2021–2027-es kutatási és innovációs keretprogramja, 95,5 Mrd euró keretösszeggel."},{"nev":"Európai Innovációs Tanács (EIC)","url":"https://eic.ec.europa.eu/index_en","megjegyzes":"A Horizont Európa III. pillérének innovációfinanszírozója (mintegy 10,1 Mrd euró); magyar NCP-je az NKFI Hivatalnál működik."},{"nev":"Európai Innovációs Tanács és Kkv-k Végrehajtó Ügynöksége (EISMEA)","url":"https://eismea.ec.europa.eu/index_en","megjegyzes":"Az EIC és a kkv-programok végrehajtó ügynöksége."},{"nev":"NKFI Hivatal – Horizont Európa nemzeti koordináció","url":"https://horizonteuropa.nkfih.gov.hu/","megjegyzes":"NCP-hálózat, hírlevél és rendezvények, Kormányzati Önerő Alap, WIDERA Travel Grants, Horizont Jogsegély Hotline."},{"nev":"Széchenyi Terv Plusz pályázati portál","url":"https://www.palyazat.gov.hu/","megjegyzes":"Az uniós és hazai fejlesztési felhívások közzétételi és e-ügyintézési felülete; több NKFI Alap-pályázat is itt nyújtható be. 2026 októbere óta az uniós projektek is kereshetők rajta."},{"nev":"Közlekedési és Beruházási Minisztérium (KBM)","url":"https://kormany.hu/kormanyzat/kozlekedesi-es-beruhazasi-miniszterium","megjegyzes":"Az uniós források hazahozatalának és felhasználásának kormányzati koordinációja."},{"nev":"Vidék- és Településfejlesztési Minisztérium (VTM)","url":"https://kormany.hu/kormanyzat/videk-es-telepulesfejlesztesi-miniszterium","megjegyzes":"Az uniós források felhasználásáért felelős tárca: ösztönzi a közvetlen uniós források lehívását, és működteti önerő- és előkészítésiköltség-támogatási mechanizmusukat."}],"linkek":[]}');
--> statement-breakpoint
INSERT INTO `tudastar_kartya` (`id`, `kategoria`, `slug`, `tipus`, `nev`, `rovidites`, `osszefoglalo`, `honlap`, `sorrend`, `tartalom`) VALUES ('c3148054-d96f-a274-33b3-fffcbe49d572', 'finanszirozas', 'horizont-europa-ncp', 'lista', 'Horizont Európa nemzeti kapcsolattartók', NULL, 'A nemzeti kapcsolattartók (NCP-k) a program szerkezetét követve ingyenes tájékoztatást, pályázati tanácsadást és partnerkeresési segítséget adnak a magyar pályázóknak. Az ERC kapcsolattartó pontja az MTA-nál, a többi téma az NKFI Hivatalnál működik; közös elérhetőség: ncp@nkfih.gov.hu, +36 70 680 6421. A jogi és pénzügyi NCP csak e-mailben fogad megkeresést. A program leírása és a magyar részvétel tudnivalói a 9. kategória „Horizont Európa” kártyáján.', NULL, 4, '{"sorok":[{"nev":"I. pillér – Európai Kutatási Tanács (ERC)","url":"https://mta.hu/mta_erc","megjegyzes":"Magyar Tudományos Akadémia Titkársága"},{"nev":"I. pillér – Marie Skłodowska-Curie akciók (MSCA)","url":"https://nkfih.gov.hu/hivatalrol/nemzetkozi-kapcsolatok/horizont-europa/nemzeti-kapcsolattarto-pontok","megjegyzes":"NKFI Hivatal"},{"nev":"I. pillér – Kutatási infrastruktúrák","url":"https://nkfih.gov.hu/hivatalrol/nemzetkozi-kapcsolatok/horizont-europa/nemzeti-kapcsolattarto-pontok","megjegyzes":"NKFI Hivatal"},{"nev":"II. pillér, 1. klaszter: Egészségügy","url":"https://nkfih.gov.hu/hivatalrol/nemzetkozi-kapcsolatok/horizont-europa/nemzeti-kapcsolattarto-pontok","megjegyzes":"NKFI Hivatal; az Innovative Health Initiative (IHI) partnerség is"},{"nev":"II. pillér, 2. klaszter: Kultúra, kreativitás és befogadó társadalom","url":"https://nkfih.gov.hu/hivatalrol/nemzetkozi-kapcsolatok/horizont-europa/nemzeti-kapcsolattarto-pontok","megjegyzes":"NKFI Hivatal"},{"nev":"II. pillér, 3. klaszter: A társadalmat szolgáló polgári biztonság","url":"https://nkfih.gov.hu/hivatalrol/nemzetkozi-kapcsolatok/horizont-europa/nemzeti-kapcsolattarto-pontok","megjegyzes":"NKFI Hivatal"},{"nev":"II. pillér, 4. klaszter: Digitalizáció, ipar és világűr","url":"https://nkfih.gov.hu/hivatalrol/nemzetkozi-kapcsolatok/horizont-europa/nemzeti-kapcsolattarto-pontok","megjegyzes":"NKFI Hivatal"},{"nev":"II. pillér, 5. klaszter: Éghajlat, energia és mobilitás","url":"https://nkfih.gov.hu/hivatalrol/nemzetkozi-kapcsolatok/horizont-europa/nemzeti-kapcsolattarto-pontok","megjegyzes":"NKFI Hivatal; a Clean Hydrogen, a CCAM, az Europe’s Rail és a Clean Aviation partnerség is"},{"nev":"II. pillér, 6. klaszter: Élelmiszerek, biomassza alapú gazdaság, természeti erőforrások és környezet","url":"https://nkfih.gov.hu/hivatalrol/nemzetkozi-kapcsolatok/horizont-europa/nemzeti-kapcsolattarto-pontok","megjegyzes":"NKFI Hivatal; a Circular Bio-based Europe közös vállalkozás (CBE JU) is"},{"nev":"III. pillér – Európai Innovációs Tanács (EIC), európai innovációs ökoszisztémák (EIE), EIT","url":"https://nkfih.gov.hu/hivatalrol/nemzetkozi-kapcsolatok/horizont-europa/nemzeti-kapcsolattarto-pontok","megjegyzes":"NKFI Hivatal"},{"nev":"A részvétel szélesítése (Widening) és az Európai Kutatási Térség (ERA) megerősítése","url":"https://nkfih.gov.hu/hivatalrol/nemzetkozi-kapcsolatok/horizont-europa/nemzeti-kapcsolattarto-pontok","megjegyzes":"NKFI Hivatal"},{"nev":"Missziók és a New European Bauhaus kezdeményezés","url":"https://nkfih.gov.hu/hivatalrol/nemzetkozi-kapcsolatok/horizont-europa/nemzeti-kapcsolattarto-pontok","megjegyzes":"NKFI Hivatal; mind az öt misszió: rák, klímasemleges és intelligens városok, alkalmazkodás az éghajlatváltozáshoz, óceánok és vizek, egészséges talajok"},{"nev":"Társfinanszírozott programok: európai partnerségek és ERA-NET-ek","url":"https://nkfih.gov.hu/hivatalrol/nemzetkozi-kapcsolatok/horizont-europa/nemzeti-kapcsolattarto-pontok","megjegyzes":"NKFI Hivatal; köztük a Chips közös vállalkozás (Chips JU), az EUREKA és a Eurostars. A hazai társfinanszírozásról az NKFI Alap ügyfélszolgálata tájékoztat (nkfialap@nkfih.gov.hu)."},{"nev":"Jogi és pénzügyi NCP","url":"https://nkfih.gov.hu/hivatalrol/nemzetkozi-kapcsolatok/horizont-europa/nemzeti-kapcsolattarto-pontok","megjegyzes":"NKFI Hivatal; csak e-mailes megkeresés (ncp@nkfih.gov.hu). Hazai jogszabályt igénylő pénzügyi, adózási, munkajogi kérdésben nem tájékoztat, költségvetést nem ellenőriz."}],"linkek":[{"felirat":"A nemzeti kapcsolattartók oldala (NKFIH)","url":"https://nkfih.gov.hu/hivatalrol/nemzetkozi-kapcsolatok/horizont-europa/nemzeti-kapcsolattarto-pontok"},{"felirat":"Horizont Európa – az NKFIH magyar nyelvű oldala","url":"https://horizonteuropa.nkfih.gov.hu/"},{"felirat":"Partnerkeresés (NKFIH Horizont Európa portál)","url":"https://horizonteuropa.nkfih.gov.hu/hogyan-palyazzak/partnerkereses"}]}');
--> statement-breakpoint
INSERT INTO `tudastar_kartya` (`id`, `kategoria`, `slug`, `tipus`, `nev`, `rovidites`, `osszefoglalo`, `honlap`, `sorrend`, `tartalom`) VALUES ('8409c8f4-434c-00e0-a86b-ab2c9afc34da', 'finanszirozas', 'nemzetkozi-programok-hazai-felelosei', 'lista', 'Az EUREKA, a Eurostars, a COST és más programok hazai felelősei', NULL, 'A Horizont Európán kívüli nemzetközi KFI-programok magyar kapcsolódási pontjai, tömör címtárként; a programok leírását a 9. kategória kártyái adják. A legtöbb program hazai koordinátora és finanszírozója az NKFI Hivatal; a kormányközi TéT-egyezmények és az űrügyek a Tudományos és Technológiai Minisztériumhoz tartoznak.', NULL, 5, '{"sorok":[{"nev":"EUREKA","url":"https://nkfih.gov.hu/palyazoknak/nkfi-alap/eureka-programban-valo-magyar-reszvetel-tamogatasa-2025-122-eureka/palyazati-felhivas","megjegyzes":"NKFI Hivatal: hazai koordinátor és a magyar résztvevők támogatása (2025-1.2.2-EUREKA felhívás, beadás 2027. október 15-ig)."},{"nev":"Eurostars (innovatív kkv-k európai partnersége)","url":"https://horizonteuropa.nkfih.gov.hu/horizont-europa-program/partnersegek/partnerseg-attekintes","megjegyzes":"NKFI Hivatal: nemzeti kapcsolattartó; a magyar résztvevőket az NKFI Hivatal a partnerségi portfólióban évi 1 millió eurós kerettel támogatja (2026-os állapot)."},{"nev":"COST (European Cooperation in Science and Technology)","url":"https://www.cost.eu/about/members/hungary/","megjegyzes":"NKFI Hivatal: itt működik a COST nemzeti koordinátora; a COST-akciók témáit alulról szerveződve maguk a kutatók határozzák meg."},{"nev":"Európai partnerségek, ERA-NET Cofund, EJP Cofund","url":"https://horizonteuropa.nkfih.gov.hu/horizont-europa-program/partnersegek/partnerseg-attekintes","megjegyzes":"NKFI Hivatal: NCP-k és a nyertes magyar partnerek nemzeti finanszírozása (2026-ban 19 konstrukció, összesen 2,7 Mrd Ft)."},{"nev":"Digitális Kulcstechnológiák (KDT) / Chips közös vállalkozás","url":"https://nkfih.gov.hu/hivatalrol/nemzetkozi-kapcsolatok/horizont-europa/nemzeti-kapcsolattarto-pontok","megjegyzes":"NKFI Hivatal: NCP; a bekapcsolódást támogató hazai felhívás (2024-1.2.4-KDT) beadási határideje 2026. október 30-án lejárt."},{"nev":"Kétoldalú kormányközi TéT-együttműködések","url":"https://nkfih.gov.hu/palyazoknak/nkfi-alap/ketoldalu-tudomanyos-technologiai-egyuttmukodes-tamogatasa-2026-112-tet/palyazati-felhivas","megjegyzes":"TTM TéT-attasé hálózatot koordináló főosztálya (egyezmények, munkatervek, vegyes bizottságok); NKFI Hivatal (közös pályázatok; a 2026-1.2.2-TÉT beadása 2026. július 31-én lezárult)."},{"nev":"Svájci Finanszírozási Mechanizmus – kétoldalú kutatási együttműködések","url":"https://njt.jog.gov.hu/jogszabaly/2026-2-B0-9N","megjegyzes":"Programoperátor: NKFI Hivatal; a TTM TéT-főosztálya az NKFI Hivatallal együttműködve látja el a minisztériumi feladatokat."},{"nev":"Európai Űrügynökség (ESA) és uniós űrprogramok","url":"https://kormany.hu/kormanyzat/tudomanyos-es-technologiai-miniszterium","megjegyzes":"TTM Űrpolitikai Főosztály (ESA és Iparfejlesztési Osztály; EU Űrpolitikai és Nemzetközi Együttműködési Osztály)."}],"linkek":[]}');
--> statement-breakpoint
INSERT INTO `tudastar_kartya` (`id`, `kategoria`, `slug`, `tipus`, `nev`, `rovidites`, `osszefoglalo`, `honlap`, `sorrend`, `tartalom`) VALUES ('0d67f04a-3035-14f2-7353-15045f84762b', 'innovacios-szolgaltatasok', 'niu', 'intezmeny', 'Nemzeti Innovációs Ügynökség', 'NIÜ', 'Az innovációs ökoszisztéma szereplőivel folyamatos kapcsolatot tartó állami ügynökség: az NKFI Hivatal finanszírozói munkáját egészíti ki. Startupoknak, kkv-knak, hallgatóknak és kutatóknak kínál képzést, mentorálást, külpiaci és Horizont Európa-felkészítést, és működteti a hazai startup-ökoszisztéma portálját. Tulajdonosi joggyakorlója az NKFI Hivatal, szakmai felügyeletét a Tudományos és Technológiai Minisztérium látja el.', 'https://niu.hu/', 1, '{"profil":"A Nemzeti Innovációs Ügynökség Nonprofit Zrt. célja Magyarország innovációs képességének erősítése: támogatást nyújt az innovációs ökoszisztéma változó szükségleteire, kapcsolatot teremt a szereplők között, és terjeszti az innovációs kultúrát. Fő céljai:\n- az innovatív vállalkozói és kutatói utánpótlás erősítése;\n- az innovatív vállalatok és startupok hazai és külpiacra jutásának támogatása;\n- az innováció kultúrájának megteremtése és az ökoszisztéma nemzetközi láthatóságának növelése.\n\nAz NKFI Hivatal bemutatása szerint az ügynökség azért jött létre, hogy a finanszírozó hivatal munkáját az ökoszisztémával aktív kapcsolatot ápoló ügynökségként egészítse ki; segít az innovátoroknak eligazodni a támogató szervezetek és források között, és adatalapú információt ad az ökoszisztémáról.\n\nTulajdonosi joggyakorlója az NKFI Hivatal; a TTM SZMSZ-e szerint felette a szakmai felügyeletet a tudománypolitikai és innovációs államtitkár gyakorolja. 2026 októberében vezetőváltás történt: a végleges vezérigazgató kiválasztásáig megbízott vezérigazgató irányítja.","tevekenyseg":"Oktatás és utánpótlás:\n- Hungarian Startup University Program (HSUP) egyetemi hallgatóknak, HSUP Doctorate doktoranduszoknak;\n- Selye János Diáklabor-hálózat és MTMI Innovációs Műhely az általános és középiskolásoknak.\n\nStartupok és kkv-k:\n- XPAND külpiaci program és Enterprise Horizon Horizont Európa-felkészítés;\n- Innovációs Voucher Program, mentorálás, projektfejlesztési szolgáltatás, innovációs tréning, minősített innovációs tanácsadók adatbázisa.\n\nÖkoszisztéma és technológiatranszfer:\n- Területi Innovációs Platform (TIP) hálózat, startup-rendezvények támogatása;\n- az egyetemi Science Park és technológiatranszfer-cég (TTC) projektek szakmai támogatása és monitorozása;\n- Hungarian Startup Ecosystem portál (startup.niu.hu) startup-adatbázissal;\n- nemzetközi projektek (pl. BEAMING, DALIA, RInnoValleys, ClimaPannonia), az EIT Regional Innovation Booster-felhívás népszerűsítése.\n\nA honlap szerint az ügynökség programjaival eddig több mint 2000 vállalkozást és több mint 57 000 diákot ért el.","kapcsolat":{"email":"info@niu.hu","telefon":"","cim":"1077 Budapest, Kéthly Anna tér 1., 1. emelet"},"szakaszok":[],"programok":[{"nev":"XPAND Program","url":"https://niu.hu/service/xpand-program","leiras":"Startupok és kkv-k külpiacra lépésének támogatása: képzés, mentorálás, kapcsolatépítés, megjelenés nemzetközi vásárokon és üzleti utakon."},{"nev":"Enterprise Horizon","url":"https://niu.hu/service/enterprise-horizon","leiras":"Innovatív vállalkozások felkészítése a Horizont Európa-pályázatokra és a nemzetközi konzorciumépítésre."},{"nev":"Hungarian Startup University Program (HSUP)","url":"https://niu.hu/project/hungarian-startup-university-program","leiras":"Egyetemi startup- és innovációs kurzus mentorálással; a 2026/2027-es tanévben 33 hazai és 1 határon túli felsőoktatási intézményben."},{"nev":"HSUP Doctorate","url":"https://niu.hu/service/hsup-doctorate","leiras":"Doktoranduszok kutatási eredményeinek innovációvá, akár startuppá alakítása: képzés, mentorálás, ösztöndíj és projektfinanszírozás."},{"nev":"HSUP Growth Fund","url":"https://niu.hu/service/hsup-growth-fund","leiras":"HSUP-alumni alapította startupok vissza nem térítendő támogatása (10–20 MFt, 80 MFt keret) a befektetésre érett állapotig; a 2026-os pályázat 2026. január 9-én lezárult."},{"nev":"Startup-rendezvények támogatása (Rendezvénytámogatási program) 2026","url":"https://niu.hu/service/startup-rendezvenyek-tamogatasa-rendezvenytamogatasi-program-2026","leiras":"Hazai innovációs és startup-rendezvények támogatása (2026: 20 MFt keret, rendezvényenként legfeljebb 1, 3 vagy 5 MFt); a 2026-os beadás 2026. május 29-én lezárult."},{"nev":"Innovációs Voucher Program","url":"https://niu.hu/service/innovacios-voucher-program","leiras":"Startupok és kkv-k innovációs szolgáltatásokat vehetnek igénybe minősített szolgáltatóktól; a díjat a NIÜ közvetlenül a szolgáltatónak fizeti."},{"nev":"Science Park projekt","url":"https://niu.hu/project/science-park-projekt","leiras":"Tudományos és Innovációs Parkok szakmai koncepciójának támogatása és monitorozása hat egyetemen: Debreceni, Óbudai, Pannon, Semmelweis, Széchenyi István és Szegedi Tudományegyetem."},{"nev":"Technology Transfer Company (TTC) projekt","url":"https://niu.hu/project/technology-transfer-company-ttc-projekt","leiras":"Öt egyetem technológiatranszfer-cégének létrehozása és 2024–2026-os működése; a NIÜ szakmai támogatást ad és monitoroz."},{"nev":"Mentorálási szolgáltatás","url":"https://niu.hu/service/mentoralasi-szolgaltatas","leiras":"Innovatív vállalkozások KFI-projektjeinek díjmentes (csekély összegű támogatásnak minősülő) mentorálása a GINOP Plusz KFI-ökoszisztéma projektben."},{"nev":"Projektfejlesztési szolgáltatás","url":"https://niu.hu/service/projektfejlesztesi-szolgaltatas","leiras":"Vállalati KFI-projektjavaslatok tudományos-technológiai és üzleti szakértői vizsgálata, továbbfejlesztési javaslatokkal."},{"nev":"Minősített innovációs tanácsadók","url":"https://niu.hu/service/minositett-innovacios-tanacsadok","leiras":"Minősítési eljáráson átesett innovációs tanácsadó vállalkozások nyilvános adatbázisa (termelési, marketing-, logisztikai és szervezeti innováció)."},{"nev":"Területi Innovációs Platform (TIP)","url":"https://niu.hu/service/teruleti-innovacios-platform","leiras":"Az egyetemekre épülő regionális innovációs együttműködési hálózat; 2019-ben az NKFIH indította, 2024 óta a NIÜ működteti."},{"nev":"Innovációs tréning","url":"https://niu.hu/service/innovacios-trening","leiras":"Díjmentes, négymodulos online tréning vállalati munkavállalók innovációmenedzsment-ismereteinek fejlesztésére."}],"linkek":[{"felirat":"Szolgáltatások célcsoportonként","url":"https://niu.hu/services"},{"felirat":"Hungarian Startup Ecosystem portál","url":"https://startup.niu.hu/"},{"felirat":"A NIÜ bemutatása az NKFIH oldalán","url":"https://nkfih.gov.hu/palyazoknak/innovacios-okoszisztema/nemzeti-innovacios-ugynokseg/ugynokseg-bemutatasa"}]}');
--> statement-breakpoint
INSERT INTO `tudastar_kartya` (`id`, `kategoria`, `slug`, `tipus`, `nev`, `rovidites`, `osszefoglalo`, `honlap`, `sorrend`, `tartalom`) VALUES ('07114e6c-951e-2c6c-6233-14fec2315d4f', 'innovacios-szolgaltatasok', 'vallalkozasfejlesztesi-szervezetek', 'lista', 'Országos vállalkozásfejlesztési szervezetek', NULL, 'A vállalkozásfejlesztés kormányzati felelőse a Gazdasági és Energetikai Minisztérium (a mesterséges intelligenciával kapcsolatos vállalkozásfejlesztés a TTM-é). Mellette országos ügynökség és a kamarai rendszer kínál programokat a kkv-knak.', NULL, 2, '{"sorok":[{"nev":"Gazdasági és Energetikai Minisztérium (GEM)","url":"https://kormany.hu/kormanyzat/gazdasagi-es-energetikai-miniszterium","megjegyzes":"A vállalkozásfejlesztésért felelős tárca: kkv-szabályozás, beruházásösztönzés, állami hitel-, tőke- és garanciaprogramok."},{"nev":"Magyar Gazdaságfejlesztési Ügynökség (MGFÜ)","url":"https://mgfu.hu/","megjegyzes":"Közhasznú ügynökség a kkv-k versenyképességéért: vállalkozásfejlesztési programok, Modern Mintaüzem Program, ESG-tudás; info@mgfu.hu."},{"nev":"Magyar Kereskedelmi és Iparkamara (MKIK)","url":"https://mkik.hu/","megjegyzes":"Országos gazdasági kamara a területi kamarák hálózatával; vállalkozói programjai közt a Beszállítói Program és a Tőkeprogram."},{"nev":"Nemzeti Innovációs Ügynökség (NIÜ)","url":"https://niu.hu/","megjegyzes":"Innovációs szolgáltatások startupoknak és kkv-knak (voucher, mentorálás, XPAND); lásd a NIÜ kártyáját."}],"linkek":[]}');
--> statement-breakpoint
INSERT INTO `tudastar_kartya` (`id`, `kategoria`, `slug`, `tipus`, `nev`, `rovidites`, `osszefoglalo`, `honlap`, `sorrend`, `tartalom`) VALUES ('773006b0-a77b-0fad-01cc-eb858a15717c', 'innovacios-szolgaltatasok', 'inkubatorok-akceleratorok', 'lista', 'Inkubátorok és akcelerátorok', NULL, 'A hazai inkubátorok és akcelerátorok részletes listái más kategóriákban szerepelnek, ez a kártya oda vezet: a Startup Factory-program 2023-as felhívásán támogatott inkubátorokat a 7. kategória „Inkubációs és akcelerációs befektetők (Startup Factory)” kártyája, az egyetemi inkubátorokat az 5. kategória sorolja fel. A Startup Factory technológiai inkubátorai az NKFI Alap forrásából, állami–magán társbefektetési modellben fektetnek korai fázisú startupokba, és szakmai, üzleti támogatást adnak.', NULL, 3, '{"sorok":[{"nev":"Startup Factory inkubátorprogram (NKFI Alap)","url":"https://nkfih.gov.hu/english/nrdi-fund/startup-factory-2023-113-startup","megjegyzes":"A 2023-1.1.3-STARTUP felhíváson támogatott 12 inkubátor listája a 7. kategória „Inkubációs és akcelerációs befektetők (Startup Factory)” kártyáján; új kört a 2026. évi programstratégia tervez."},{"nev":"Egyetemi inkubátorok, kompetenciaközpontok és science parkok","url":"https://niu.hu/project/science-park-projekt","megjegyzes":"Az 5. kategória „Egyetemi inkubátorok, kompetenciaközpontok és science parkok” kártyája sorolja fel őket; hat egyetem Science Parkjának koncepcióját a NIÜ támogatja."},{"nev":"A Nemzeti Innovációs Ügynökség startupprogramjai","url":"https://niu.hu/services","megjegyzes":"Képzés, mentorálás és külpiaci felkészítés (HSUP, XPAND; az XPAND a nemzetközi akcelerátorprogramokba jutást is segíti); részletek a NIÜ kártyáján."}],"linkek":[]}');
--> statement-breakpoint
INSERT INTO `tudastar_kartya` (`id`, `kategoria`, `slug`, `tipus`, `nev`, `rovidites`, `osszefoglalo`, `honlap`, `sorrend`, `tartalom`) VALUES ('20b704e9-1a8d-4835-ec72-8a66c148526c', 'innovacios-szolgaltatasok', 'innovacios-klaszterek', 'lista', 'Klaszterek', NULL, 'Az ágazati klaszterek vállalatokat, egyetemeket és kamarákat fognak össze, ezért jó belépési pontok ágazati partnerkereséshez. A hazai akkreditált klaszterek 2023-as hivatalos kimutatását a 8. kategória „Akkreditált klaszterek” kártyája közli; ez a kártya a klaszterek kereséséhez és a hazai klaszterpolitikához vezet.', NULL, 4, '{"sorok":[{"nev":"European Cluster Collaboration Platform (ECCP)","url":"https://www.clustercollaboration.eu/","megjegyzes":"Az Európai Bizottság kezdeményezése: európai klaszterkereső és -térkép, partnerkeresés több mint 1500 klaszterszervezet között."},{"nev":"Klaszterfejlesztési stratégia 2023–2030","url":"https://cdn.kormany.hu/uploads/document/8/85/859/859655813b0908ec753dfb28e0365d96b5a3d5e0.pdf","megjegyzes":"A hazai klaszterpolitika 2023-ban kiadott kormányzati stratégiája; melléklete közli a 2023. január 1-jén akkreditált klasztereket."}],"linkek":[]}');
--> statement-breakpoint
INSERT INTO `tudastar_kartya` (`id`, `kategoria`, `slug`, `tipus`, `nev`, `rovidites`, `osszefoglalo`, `honlap`, `sorrend`, `tartalom`) VALUES ('73ac59f9-29f4-3b8e-6ca2-964b553f463e', 'innovacios-szolgaltatasok', 'startup-technologiai-szervezetek', 'lista', 'Startup- és technológiai szervezetek, vállalati és nyílt innovációs programok', NULL, 'A startup-ökoszisztéma és a technológiai ágazatok országos szervezetei, valamint olyan programok, amelyek a vállalati innovációt és az egyetem–vállalat együttműködést nyitják meg. A TTM a startup-ügyekben a kamarákkal, szakmai szövetségekkel, inkubátorokkal és akcelerátorokkal is kapcsolatot tart. A jelentős KFI-központtal rendelkező és nyílt innovációs programot működtető vállalatokat a 8. kategória sorolja fel.', NULL, 5, '{"sorok":[{"nev":"Hungarian Startup Ecosystem (NIÜ)","url":"https://startup.niu.hu/","megjegyzes":"A NIÜ angol nyelvű startup-ökoszisztéma portálja startup-adatbázissal, finanszírozási és jogi tudnivalókkal; külföldi partnereknek is."},{"nev":"Magyar Innovációs Szövetség (MISZ)","url":"https://innovacio.hu/","megjegyzes":"Országos innovációs szövetség; szolgáltatások nagyvállalatoknak, kkv-knak és startupoknak, Magyar Innovációs Nagydíj, ifjúsági innovációs versenyek."},{"nev":"IVSZ – Digitális Vállalkozások Szövetsége","url":"https://ivsz.hu/","megjegyzes":"Az infokommunikációs ágazat szövetsége; munkacsoportok többek között kvantumtechnológia, e-egészség, kiberbiztonság és vállalati digitalizáció témában."},{"nev":"Egyetemi technológiatranszfer-cégek (TTC-hálózat)","url":"https://niu.hu/project/technology-transfer-company-ttc-projekt","megjegyzes":"Egyetemi (és HUN-REN) tulajdonú TT-cégek; a NIÜ TTC-projektje (2024–2026) és az NKFIH 2026-1.1.2-TTC felhívása (6 Mrd Ft; a beadás 2026. április 16-án lezárult) fejleszti őket."},{"nev":"Tudományos és Innovációs Parkok (Science Park)","url":"https://niu.hu/project/science-park-projekt","megjegyzes":"Egyetemek, kutatóintézetek, high-tech cégek és startupok közös terei; hat egyetem Science Parkjának szakmai koncepcióját a NIÜ támogatja és monitorozza."},{"nev":"Modern Mintaüzem Program (MGFÜ)","url":"https://mgfu.hu/hu/page/modem4","megjegyzes":"Vállalati mintaüzemek nyitják meg kapuikat cégvezetőknek technológiaváltási és innovációs tapasztalatcserére; évente Modern Gyárak Éjszakája."}],"linkek":[]}');
--> statement-breakpoint
INSERT INTO `tudastar_kartya` (`id`, `kategoria`, `slug`, `tipus`, `nev`, `rovidites`, `osszefoglalo`, `honlap`, `sorrend`, `tartalom`) VALUES ('e094ba70-a6a8-76e8-4b9d-550efa83ece6', 'kutatohalozat', 'hun-ren', 'intezmeny', 'HUN-REN Magyar Kutatási Hálózat', 'HUN-REN', 'Magyarország meghatározó közfinanszírozott kutatóhálózata: 15 önálló jogi személyiségű kutatóintézmény és két gazdálkodó szervezet, több mint 5000 munkatárs, köztük mintegy 3400 kutató. A 2024. évi XCI. törvény alapján 2025-ben megújult hálózat a Magyar Tudományos Akadémia egykori kutatóintézeteit fogja egységes keretbe; irányításának átalakítása 2026-ban napirenden van. Szakmai együttműködésnél a szakterület szerinti intézet, hálózati szintű ügyekben a HUN-REN Központ a kapcsolat.', 'https://hun-ren.hu/', 1, '{"profil":"A HUN-REN jogállását a 2024 decemberében elfogadott HUN-REN-törvény (2024. évi XCI. törvény) rendezi: sajátos jogállású jogi személy, miniszteri felügyelet alatt nem áll; az állam nevében – például a finanszírozási megállapodásoknál – a tudománypolitika koordinációjáért felelős miniszter, 2026-ban a tudományos és technológiai miniszter jár el. Belső működését az alapító okirat és a szervezeti és működési szabályzat szabályozza. A megújult hálózat 2025-ben jött létre, és egységes nemzeti keretbe foglalta a Magyar Tudományos Akadémia nagy múltú kutatóintézeteit.\n\nA hálózathoz 15 kutatóintézmény tartozik – mindegyik önálló jogi személy –, valamint két gazdálkodó szervezet: a Bay Zoltán Alkalmazott Kutatási Közhasznú Nonprofit Kft. és a technológiatranszferért felelős Hunrentech Kft.\n\nIrányítás:\n- Irányító Testület: a legfőbb döntéshozó szerv; gyakorolja az alapítói jogokat, elfogadja a stratégiát, megválasztja az elnököt, jóváhagyja az üzleti tervet és a költségvetést, intézetet hoz létre, alakít át vagy szüntet meg.\n- Elnök: az intézetek vezetőit nemzetközi kiválasztás után, az Irányító Testület egyetértésével nevezi ki.\n- Felügyelőbizottság és Nemzetközi Tudományos Tanácsadó Testület.\n- HUN-REN Központ: a hálózat központi szervezete, többek közt a hálózati pályázatok kiírója.\n\nÁtalakulás 2026-ban: a hálózat elnöke és vezérigazgatója 2026 októberében távozott. Az Irányító Testület által választott új elnök megbízatása átmeneti: a HUN-REN-t szabályozó törvény tervezett módosításáig és a nyílt pályázati eljárás lezárásáig szól. A hálózat irányítása és teljesítményértékelése ezért változhat.","tevekenyseg":"Kutatás: a küldetésnyilatkozat szerint a kiemelt területek – a Neumann János Programmal összhangban – az egészséges élet, a digitális átmenet, az energia- és környezetbiztonság, valamint a biztonság és védelem.\n\nHasznosítás: a Hunrentech Kft. a hálózat technológiatranszfer-cége (szellemi tulajdon, termékfejlesztés, spin-off-menedzsment, ipari és befektetői kapcsolatok). A HUN-REN Központ iparjogvédelmi szolgáltatásokat (ötletbejelentés, újdonságkutatás, szabadalom, használati minta, növényfajta-oltalom, védjegy) és proof of concept pályázatokat kínál a kutatóknak.\n\nKutatástámogatás: a Támogatott Kutatócsoportok Programja egyetemeken és más kutatóhelyeken működő csoportokat finanszíroz; a HUN-REN Cloud és az adatrepozitórium a hazai kutatói közösség infrastruktúrája, az AI Szolgáltató Központ (AISZK) MI-eszközöket kínál.","kapcsolat":{"email":"media@hun-ren.hu","telefon":"+36 30 155 9978","cim":"1054 Budapest, Alkotmány utca 29."},"szakaszok":[{"cim":"Mire használhatja az attasé","szoveg":"- Szakmai partnert keres a külföldi intézmény: a „HUN-REN kutatóközpontok és -intézetek” listán szereplő intézet a közvetlen kapcsolat.\n- Ipari hasznosítás, licenc vagy spin-off: a Hunrentech Kft.\n- Nemzetközi együttműködés, intézményközi megállapodás: a HUN-REN Központ Nemzetközi Igazgatósága (nemzetkozikabinet@hun-ren.hu); hasznosítási ügyben az Innovációs Igazgatóság (innovacio@hun-ren.hu).\n- Hálózati szintű megállapodás, intézményi és sajtóügyek: a HUN-REN Központ.\n- Felhőalapú számítási kapacitás, MI-eszközök: a HUN-REN Cloud és az AISZK."},{"cim":"Kiemelt kutatási területek","szoveg":"A HUN-REN küldetésnyilatkozata – a Neumann János Programmal összhangban – négy témakört nevez meg kiemelt kutatási területként:\n\n- egészséges élet,\n- digitális átmenet,\n- energia- és környezetbiztonság,\n- biztonság és védelem."},{"cim":"Finanszírozás és teljesítménycélok","szoveg":"A HUN-REN és az állam 2025. december 15-én 25 éves keretmegállapodást és a 2026–2031-es időszakra közfeladat-finanszírozási szerződést kötött; a hat évre szóló keret 523 milliárd forint. A finanszírozás teljesítményelvű, 18 mutatóhoz (publikációk, nemzetközi együttműködés, diákok és doktoranduszok bevonása, szabadalmak, spin-offok) kötött.\n\nAz aláíráskor rögzített éves célok:\n- 140 szabadalom,\n- legalább 20 cég,\n- 10 milliárd forint külső bevétel,\n- 3500 középiskolás és 600 doktorandusz bevonása.\n\nA 2026 októberében hivatalba lépett elnök a tudományterületek sajátosságait figyelembe vevő új teljesítményértékelési rendszer közös kialakítását tűzte ki célul, a HUN-REN-törvény módosítása pedig tervezett: a fenti keretek és célszámok változhatnak."}],"programok":[{"nev":"Támogatott Kutatócsoportok Programja (TKCS)","url":"https://www.tki-office.hu/","leiras":"Egyetemeken és más kutatóhelyeken működő kutatócsoportok finanszírozása, elsősorban feltörekvő kutatóknak."},{"nev":"HUN-REN Cloud","url":"https://science-cloud.hu/","leiras":"Kutatási felhőszolgáltatás a hazai kutatói közösségnek, kiemelten MI-kutatáshoz; a SZTAKI és a Wigner üzemelteti."},{"nev":"HUN-REN Adatrepozitórium Platform","url":"https://hun-ren.hu/nyilt-tudomany/hun-ren-adatrepozitorium-107539","leiras":"Kutatási adatok tárolása és kezelése a FAIR-elvek szerint."},{"nev":"HUN-REN AISZK – AI Szolgáltató Központ","url":"https://ai4science.hun-ren.hu/","leiras":"Mesterséges intelligencia szolgáltató központ a magyar kutatásért."},{"nev":"Iparjogvédelem: ötletek és oltalmak","url":"https://hun-ren.hu/oltalmak","leiras":"Ötletbejelentés, újdonságkutatás, szabadalom, használati minta, növényfajta-oltalom és védjegy a kutatóknak."},{"nev":"Hunrentech Kft.","url":"https://hunrentech.hu/","leiras":"A hálózat technológiatranszfer-cége: szellemi tulajdon, piacra vitel, spin-off-menedzsment, befektetői kapcsolatok."}],"linkek":[{"felirat":"A kutatási hálózat intézményei","url":"https://hun-ren.hu/kutatasi-halozat"},{"felirat":"Pályázatkereső","url":"https://hun-ren.hu/palyazatok"},{"felirat":"Kutatóinknak","url":"https://hun-ren.hu/kutatoinknak"},{"felirat":"Küldetés és Neumann János Program","url":"https://hun-ren.hu/kuldetes"},{"felirat":"Irányító Testület","url":"https://hun-ren.hu/iranyito-testulet"},{"felirat":"Hosszú távú finanszírozási megállapodás (2025. december)","url":"https://hun-ren.hu/szervezeti_hirek/hun-ren-hosszu-tavu-megallapodas-jovo-kfsz-109815"}]}');
--> statement-breakpoint
INSERT INTO `tudastar_kartya` (`id`, `kategoria`, `slug`, `tipus`, `nev`, `rovidites`, `osszefoglalo`, `honlap`, `sorrend`, `tartalom`) VALUES ('ccc33c38-32d6-8222-d670-1c53c790b8dc', 'kutatohalozat', 'hun-ren-intezetek', 'lista', 'HUN-REN kutatóközpontok és -intézetek', NULL, 'A HUN-REN 15 kutatóintézménye és két gazdálkodó szervezete. Mindegyik intézmény önálló jogi személy saját vezetéssel és nemzetközi kapcsolatokkal; szakmai együttműködésnél közvetlenül az intézetet érdemes megkeresni.', NULL, 2, '{"sorok":[{"nev":"HUN-REN Agrártudományi Kutatóközpont","url":"https://atk.hun-ren.hu/hu/","megjegyzes":"Martonvásár; agrártudományok."},{"nev":"HUN-REN Állatorvostudományi Kutatóintézet","url":"https://vmri.hu/","megjegyzes":"Állatorvos-tudomány."},{"nev":"HUN-REN Atommagkutató Intézet (ATOMKI)","url":"https://atomki.hu/","megjegyzes":"Debrecen; atommagkutatás; az Űrkémiai Kutatóhálózat gazdája."},{"nev":"HUN-REN Balatoni Limnológiai Kutatóintézet","url":"https://www.blki.hun-ren.hu/","megjegyzes":"Tihany; limnológia, vízi ökoszisztémák (Balaton, Duna, Tisza)."},{"nev":"HUN-REN Csillagászati és Földtudományi Kutatóközpont (CSFK)","url":"https://csfk.hun-ren.hu/","megjegyzes":"Intézetei: Konkoly Thege Miklós Csillagászati Intézet, Földtani és Geokémiai Intézet, Földrajztudományi Intézet."},{"nev":"HUN-REN Energiatudományi Kutatóközpont","url":"https://www.ek.hun-ren.hu/","megjegyzes":"Energetika és nukleáris kutatás; szervezeti egysége a Budapesti Kutatóreaktor; a LOHC Misszióvezérelt NL (2026) nyertese."},{"nev":"HUN-REN Földfizikai és Űrtudományi Kutatóintézet","url":"https://epss.hun-ren.hu/","megjegyzes":"Sopron; földfizika és űrkutatás; a Magyar Nemzeti Szeizmológiai Hálózat gazdája."},{"nev":"HUN-REN Kísérleti Orvostudományi Kutatóintézet (KOKI)","url":"https://koki.hun-ren.hu/","megjegyzes":"Budapest; kísérleti orvostudomány; Mikroszkópos Központ."},{"nev":"HUN-REN Ökológiai Kutatóközpont","url":"https://ecolres.hun-ren.hu/","megjegyzes":"Szárazföldi és vízi ökoszisztémák kutatása az evolúcióbiológiától a döntéstámogatásig."},{"nev":"HUN-REN Rényi Alfréd Matematikai Kutatóintézet","url":"https://www.renyi.hu/","megjegyzes":"Budapest; matematika."},{"nev":"HUN-REN Számítástechnikai és Automatizálási Kutatóintézet (SZTAKI)","url":"https://sztaki.hun-ren.hu/","megjegyzes":"Budapest; informatika és automatizálás; két Misszióvezérelt NL (2026) nyertese; az első ciklusban a Mesterséges Intelligencia és az Autonóm Rendszerek NL konzorciumvezetője."},{"nev":"HUN-REN Szegedi Biológiai Kutatóközpont","url":"https://www.brc.hu/hu/","megjegyzes":"Szeged; élettudományok; két Misszióvezérelt NL (2026) nyertese; az első ciklusban a Biotechnológiai Nemzeti Laboratórium megvalósítója."},{"nev":"HUN-REN Támogatott Kutatócsoportok Irodája (TKI)","url":"https://www.tki-office.hu/","megjegyzes":"Több mint 100, főként egyetemeken működő támogatott kutatócsoport irodája; részletesen a „Támogatott kutatócsoportok” listán."},{"nev":"HUN-REN Természettudományi Kutatóközpont (TTK)","url":"https://www.ttk.hun-ren.hu/","megjegyzes":"Kémia, molekuláris élettudomány, kognitív idegtudomány; az első ciklusban a Nemzeti Gyógyszerkutatási és Fejlesztési Laboratórium konzorciumvezetője."},{"nev":"HUN-REN Wigner Fizikai Kutatóközpont","url":"https://wigner.hu/","megjegyzes":"Budapest; fizika; az első ciklusban a Kvantuminformatika Nemzeti Laboratórium konzorciumvezetője."},{"nev":"Bay Zoltán Alkalmazott Kutatási Közhasznú Nonprofit Kft.","url":"https://www.bayzoltan.hu/","megjegyzes":"A HUN-REN alkalmazott kutatási gazdálkodó szervezete; Budapest és több vidéki telephely."},{"nev":"Hunrentech Kft.","url":"https://hunrentech.hu/","megjegyzes":"A HUN-REN technológiatranszfer-cége."}],"linkek":[{"felirat":"A HUN-REN kutatási hálózata","url":"https://hun-ren.hu/kutatasi-halozat"}]}');
--> statement-breakpoint
INSERT INTO `tudastar_kartya` (`id`, `kategoria`, `slug`, `tipus`, `nev`, `rovidites`, `osszefoglalo`, `honlap`, `sorrend`, `tartalom`) VALUES ('833c7510-4758-6854-3fc1-e120f413814f', 'kutatohalozat', 'tamogatott-kutatocsoportok', 'lista', 'Támogatott kutatócsoportok', NULL, 'Egyetemeken és más kutatóhelyeken működő, külön programból finanszírozott kutatócsoportok. A két fő program a HUN-REN Támogatott Kutatócsoportok Programja és az MTA Lendület Program; a csoportok a befogadó intézményen keresztül is elérhetők.', NULL, 3, '{"sorok":[{"nev":"HUN-REN Támogatott Kutatócsoportok Irodája (TKI)","url":"https://www.tki-office.hu/","megjegyzes":"Több mint 100 kutatócsoport, főként a hazai egyetemeken, a tudomány minden területén."},{"nev":"A HUN-REN TKI kutatócsoportjainak listája","url":"https://www.tki-office.hu/a-hun-ren-tki-tamogatott-kutatocsoportjai/","megjegyzes":"101 csoport; önálló befogadóként a legtöbb a DE-n (20), az SZTE-n (15), az ELTE-n (14), a SE-n (11) és a BME-n (10)."},{"nev":"HUN-REN Támogatott Kutatócsoportok Programja (TKCS)","url":"https://hun-ren.hu/szervezeti_hirek/megujul-a-tamogatott-kutatocsoportok-program-106336","megjegyzes":"A HUN-REN Központ pályázata, elsősorban feltörekvő kutatóknak (PhD után legfeljebb 15 év); HUN-REN-intézetek is pályázhatnak."},{"nev":"MTA Lendület Program","url":"https://mta.hu/lendulet/lendulet-program-105403","megjegyzes":"Az Akadémia programja fiatal kutatók önálló kutatócsoportjaira; 2026-ban tizennégy új csoport alakul."},{"nev":"Az MTA Lendület-kutatócsoport hálózata","url":"https://mta.hu/lendulet/az-mta-lendulet-kutatocsoport-halozata-105402","megjegyzes":"Egyetemeken, valamint kutatóközpontokban és -intézetekben működő Lendület-csoportok."},{"nev":"MTA – aktuális pályázati kiírások","url":"https://mta.hu/aktualis-palyazati-kiirasok","megjegyzes":""}],"linkek":[]}');
--> statement-breakpoint
INSERT INTO `tudastar_kartya` (`id`, `kategoria`, `slug`, `tipus`, `nev`, `rovidites`, `osszefoglalo`, `honlap`, `sorrend`, `tartalom`) VALUES ('914658f3-e8e2-0887-9247-b0e36e31c7c7', 'kutatohalozat', 'nemzeti-laboratoriumok', 'lista', 'Nemzeti laboratóriumok', NULL, 'Az NKFIH által gondozott Nemzeti Laboratóriumok Program első ciklusában 25 labor működött négy tématerületen; projektjeik lezárulnak (a Mesterséges Intelligencia Nemzeti Laboratóriumé 2026 márciusában zárult). Erre és a Tématerületi Kiválósági Program eredményeire építve a Tudományos és Technológiai Minisztérium 2026. augusztus 27-én 14 Misszióvezérelt Nemzeti Laboratóriumot támogatott, összesen 20,92 milliárd forinttal, az egészség, az energia és a technológia fókuszterületen. A megjegyzés a nyertes intézményt és a fókuszterületet adja; az első ciklus laborjai a linkeken érhetők el.', NULL, 4, '{"sorok":[{"nev":"Misszióvezérelt Nemzeti Onkológiai Laboratórium","url":"","megjegyzes":"Országos Onkológiai Intézet · Egészség"},{"nev":"Misszióvezérelt Nemzeti Kardióvaszkuláris Laboratórium","url":"","megjegyzes":"Semmelweis Egyetem · Egészség"},{"nev":"Antibiotikum-rezisztencia és mikrobiális egészség Misszióvezérelt Nemzeti Laboratórium","url":"","megjegyzes":"HUN-REN Szegedi Biológiai Kutatóközpont · Egészség"},{"nev":"Szén-dioxid Hasznosítás Misszióvezérelt Nemzeti Laboratórium","url":"","megjegyzes":"Szegedi Tudományegyetem · Energia"},{"nev":"LOHC Misszióvezérelt Nemzeti Laboratórium","url":"","megjegyzes":"HUN-REN Energiatudományi Kutatóközpont · Energia"},{"nev":"Kaszkád Faanyaghasznosítási Misszióvezérelt Nemzeti Laboratórium (KaszkádFaLab)","url":"","megjegyzes":"Soproni Egyetem · Energia"},{"nev":"Egysejtszintű multiomikai atlasz és kutatási platform a precíziós orvoslás szolgálatában Misszióvezérelt Nemzeti Laboratórium","url":"","megjegyzes":"HUN-REN Szegedi Biológiai Kutatóközpont · Technológia"},{"nev":"Humanoid robotika: szenzorika, MI és skálázható gyártás ipari és rehabilitációs célokra – Misszióvezérelt Nemzeti Laboratórium","url":"","megjegyzes":"Pázmány Péter Katolikus Egyetem · Technológia"},{"nev":"Kooperatív és Robusztus Autonóm Mobil Rendszerek Misszióvezérelt Nemzeti Laboratórium","url":"","megjegyzes":"HUN-REN Számítástechnikai és Automatizálási Kutatóintézet · Technológia"},{"nev":"Misszióvezérelt Nemzeti Laboratórium – Ágens alapú mesterséges intelligencia az egészségügy és a gyártás területein","url":"","megjegyzes":"HUN-REN Számítástechnikai és Automatizálási Kutatóintézet · Technológia"},{"nev":"Űrtechnológiával a Rezilienciáért Misszióvezérelt Nemzeti Laboratórium","url":"","megjegyzes":"Budapesti Műszaki és Gazdaságtudományi Egyetem · Technológia"},{"nev":"A mesterséges intelligencia új alkalmazásai a biztonságban Misszióvezérelt Nemzeti Laboratórium (MIBIZ)","url":"","megjegyzes":"Budapesti Műszaki és Gazdaságtudományi Egyetem · Technológia"},{"nev":"Kármán Tódor Űrtudományi Misszióvezérelt Nemzeti Laboratórium","url":"","megjegyzes":"Eötvös Loránd Tudományegyetem · Technológia"},{"nev":"Misszióvezérelt Nemzeti Laboratórium: Versenyképes klímaadaptáció és stabilitás a növénytermesztésben AI-alapú támogatással","url":"","megjegyzes":"Magyar Agrár- és Élettudományi Egyetem · Technológia"}],"linkek":[{"felirat":"Misszióvezérelt Nemzeti Laboratóriumok – támogatott projektek (NKFIH, 2026)","url":"https://nkfih.gov.hu/palyazoknak/nkfi-alap/missziovezerelt-nemzeti-laboratoriumok-tovabbfejlesztese-2026-411-missziok"},{"felirat":"Az első ciklus 25 laborja (NKFIH)","url":"https://www.nemzetilaborok.nkfih.gov.hu/temateruletek"},{"felirat":"A Nemzeti Laboratóriumok honlapja (NKFIH)","url":"https://www.nemzetilaborok.nkfih.gov.hu/"}]}');
--> statement-breakpoint
INSERT INTO `tudastar_kartya` (`id`, `kategoria`, `slug`, `tipus`, `nev`, `rovidites`, `osszefoglalo`, `honlap`, `sorrend`, `tartalom`) VALUES ('f7a85385-71f1-89b3-601b-eb244af9002f', 'kutatohalozat', 'hazai-kutatasi-infrastrukturak', 'lista', 'Hazai kutatási infrastruktúrák', NULL, 'A hazai nagy kutatási infrastruktúrák válogatása és nyilvántartásaik. Az NKFIH minősítése szerint 2024-től 111 minősített kutatási infrastruktúra működik Magyarországon; itt a nem egyetemi tételek közül a külső felhasználók előtt is nyitott nagy berendezések és e-infrastruktúrák szerepelnek, az egyetemiek válogatását az „Egyetemek és technológiatranszfer” kategória adja. A nemzetközi infrastruktúrákban (CERN, ELI ERIC, EMBL stb.) való magyar részvételt a „Nemzetközi programok magyar kapcsolódási pontjai” kategória mutatja be.', NULL, 5, '{"sorok":[{"nev":"ELI ALPS (ELI-HU Nonprofit Kft.)","url":"https://www.eli-alps.hu/","megjegyzes":"Szeged; attoszekundumos lézeres kutatóintézet; felhasználói hozzáférés az ELI ERIC nyílt pályázatain."},{"nev":"Budapest Neutron Centrum (BNC)","url":"https://bnc.hu/","megjegyzes":"Neutronkutatás a KFKI-telephelyen, a HUN-REN Energiatudományi Kutatóközpont infrastruktúrája; nyalábidő évente több pályázati körben, nyílt hozzáférési (TNA) és CERIC-ERIC hívásokban is."},{"nev":"HUN-REN Cloud","url":"https://science-cloud.hu/","megjegyzes":"Kutatási felhő a hazai kutatói közösségnek; a HUN-REN SZTAKI és a Wigner üzemelteti; kapcsolódik az EOSC-hez."},{"nev":"HPC Kompetencia Központ (Komondor szuperszámítógép)","url":"https://ncc.dkf.hu/","megjegyzes":"A nemzeti HPC-infrastruktúra üzemeltetője 2025-től a Digitális Kormányzati Fejlesztés és Projektmenedzsment Kft.; gépidő projektigényléssel, szakértői bírálat után."},{"nev":"Nemzeti Kutatási Infrastruktúra Útiterv (NKFIH)","url":"https://nkfih.gov.hu/hivatalrol/strategia-alkotas/nemzeti-kutatasi-infrastruktura-utiterv","megjegyzes":"Az ESFRI mintájára készült nemzeti útiterv (2018) a hazai infrastruktúrák katalógusával."},{"nev":"Minősített kutatási infrastruktúrák 2023–2024 (NKFIH)","url":"https://nkfih.gov.hu/hivatalrol/hivatal-hirei/nemzeti-kutatasi-infrastruktura-2023-2024","megjegyzes":"111 minősített KI 2024-től; tématerületenkénti táblázatok kiváló, kiváló hálózat és ígéretes minősítéssel, a 2021-es TOP-listával együtt."}],"linkek":[]}');
--> statement-breakpoint
INSERT INTO `tudastar_kartya` (`id`, `kategoria`, `slug`, `tipus`, `nev`, `rovidites`, `osszefoglalo`, `honlap`, `sorrend`, `tartalom`) VALUES ('437b8e53-58a6-da83-0a2e-a2a40caff012', 'kutatohalozat', 'onallo-kutatohelyek', 'lista', 'Önálló állami és nonprofit kutatóhelyek', NULL, 'A HUN-REN-en kívüli kutatóhelyek válogatása: a 2025-ben az ELTE-hez került humán- és társadalomtudományi kutatóközpontok, a Magyar Tudományos Akadémia, valamint nemzeti laboratóriumot vezető vagy megvalósító, illetve minősített kutatási infrastruktúrát működtető állami és nonprofit intézmények. A lista nem teljes; az egyetemek a következő kategóriában szerepelnek.', NULL, 6, '{"sorok":[{"nev":"ELTE Humán Tudományok Kutatóközpontja (ELTE HTK)","url":"https://www.abtk.hu/","megjegyzes":"Bölcsészettudományok; 2025. augusztus 1. óta az ELTE-n, a korábbi HUN-REN-kutatóközpont jogutódjaként."},{"nev":"ELTE Közgazdaság- és Regionális Tudományi Kutatóközpont (ELTE KRTK)","url":"https://krtk.elte.hu/","megjegyzes":"Közgazdaság- és regionális tudomány; 2025. augusztus 1. óta az ELTE-n."},{"nev":"ELTE Nyelvtudományi Kutatóközpont (ELTE NYTK)","url":"https://nytud.hu/","megjegyzes":"Nyelvtudomány; 2025. augusztus 1. óta az ELTE-n."},{"nev":"ELTE Társadalomtudományi Kutatóközpont (ELTE TK)","url":"https://tk.elte.hu/","megjegyzes":"Társadalomtudományok; 2025. augusztus 1. óta az ELTE-n."},{"nev":"Magyar Tudományos Akadémia (MTA)","url":"https://mta.hu/","megjegyzes":"Köztestület; a Lendület Program és más akadémiai pályázatok kiírója, a kutatóhálózat jövőjéről folyó 2026-os egyeztetések szereplője."},{"nev":"HCEMM Nonprofit Kft.","url":"https://www.hcemm.eu/","megjegyzes":"Szeged; molekuláris orvostudományi kiválósági központ (alapítók: HUN-REN SZBK, Semmelweis Egyetem, SZTE); fejlett partnere az EMBL."},{"nev":"Országos Onkológiai Intézet","url":"https://onkol.hu/","megjegyzes":"A Misszióvezérelt Nemzeti Onkológiai Laboratórium (2026) nyertese; az első ciklusban a Nemzeti Tumorbiológiai Laboratórium megvalósítója."},{"nev":"Gottsegen György Országos Kardiovaszkuláris Intézet","url":"https://gokvi.hu/","megjegyzes":"Gottsegen Nemzeti Kardiovaszkuláris Regiszterek: kiváló kutatási infrastruktúra (NKFIH, 2024)."},{"nev":"Molekuláris- Ujjlenyomat Kutató Központ Nonprofit Kft.","url":"https://cmf.hu/","megjegyzes":"Az első ciklusban a Molekuláris- Ujjlenyomat Kutató Nemzeti Laboratórium megvalósítója a Szegedi Tudományegyetemmel."},{"nev":"Gabonakutató Nonprofit Közhasznú Kft.","url":"https://www.gabonakutato.hu/","megjegyzes":"Szántóföldi növények nemesítése: kiváló kutatási infrastruktúra (NKFIH, 2024)."},{"nev":"TECHTRA Technológiai Transzfer Intézet Közhasznú Nonprofit Zrt.","url":"https://techtra.hu/","megjegyzes":"A Széchenyi István Egyetem ökoszisztémájához tartozik; MI, autonóm rendszerek, védelmi és kettős felhasználású technológiák."}],"linkek":[{"felirat":"Az ELTE humán- és társadalomtudományi kutatóközpontjai","url":"https://www.elte.hu/human-es-tarsadalomtudomanyi-kutatokozpontok"}]}');
--> statement-breakpoint
INSERT INTO `tudastar_kartya` (`id`, `kategoria`, `slug`, `tipus`, `nev`, `rovidites`, `osszefoglalo`, `honlap`, `sorrend`, `tartalom`) VALUES ('ae1d5bdd-f3ec-d5cf-c479-86a5ec9c7153', 'egyetemek', 'kutatoegyetemek', 'lista', 'Kutatásintenzív egyetemek', NULL, 'A kutatásban és a hasznosításban legaktívabb hazai egyetemek, ellenőrizhető mutatókkal: a HUN-REN támogatott kutatócsoportjai (önálló befogadóként), a nemzeti laboratóriumokban betöltött szerep (az első ciklus laborjai és a 2026-ban támogatott misszióvezérelt laborok), a technológiatranszfer-cég és a kiváló minősítésű kutatási infrastruktúra. Hivatalos kutatóegyetemi rangsort a lista nem helyettesít.', NULL, 1, '{"sorok":[{"nev":"Debreceni Egyetem","url":"https://unideb.hu/","megjegyzes":"20 HUN-REN támogatott kutatócsoport (a legtöbb); UD Catapult TTC; a Science Park-projekt egyik egyeteme."},{"nev":"Szegedi Tudományegyetem","url":"https://u-szeged.hu/","megjegyzes":"15 HUN-REN kutatócsoport; az Egészségbiztonság NL vezetője, a Szén-dioxid Hasznosítás Misszióvezérelt NL (2026) nyertese; SZTE TTC Zrt.; Science Park-projekt."},{"nev":"Eötvös Loránd Tudományegyetem","url":"https://www.elte.hu/","megjegyzes":"14 HUN-REN kutatócsoport; a Digitális Örökség és a Társadalmi Innovációs NL vezetője, a Kármán Tódor Űrtudományi Misszióvezérelt NL (2026) nyertese; 2025 óta négy kutatóközpont."},{"nev":"Semmelweis Egyetem","url":"https://semmelweis.hu/","megjegyzes":"11 HUN-REN kutatócsoport; a Nemzeti Kardiovaszkuláris Laboratórium konzorciumvezetője és a Misszióvezérelt Nemzeti Kardióvaszkuláris Laboratórium (2026) nyertese; Semmelweis TTC."},{"nev":"Budapesti Műszaki és Gazdaságtudományi Egyetem","url":"https://www.bme.hu/","megjegyzes":"10 HUN-REN kutatócsoport; számos nemzeti laboratórium partnere, két Misszióvezérelt NL (űrtechnológia, MI a biztonságban, 2026) nyertese; BME InnoLab Zrt."},{"nev":"Pécsi Tudományegyetem","url":"https://pte.hu/hu","megjegyzes":"A Megújuló Energiák és a Transzlációs Idegtudományi NL vezetője, a Humán Reprodukciós és a Virológiai NL megvalósítója; PTE Inno-Capital."},{"nev":"Pannon Egyetem","url":"https://uni-pannon.hu/","megjegyzes":"Az Éghajlatváltozás Multidiszciplináris és a Víztudományi és Vízbiztonsági NL konzorciumvezetője; PE Innosquare TTC."},{"nev":"Állatorvostudományi Egyetem","url":"https://univet.hu/hu/","megjegyzes":"A fertőző állatbetegségekkel foglalkozó nemzeti laboratórium konzorciumvezetője; Vet-Inno TTC Kft."},{"nev":"Széchenyi István Egyetem","url":"https://uni.sze.hu/","megjegyzes":"Győri Tudományos és Innovációs Park; a Győri Innovációs Park kiváló kutatási infrastruktúra (NKFIH, 2024); a NIÜ TTC- és Science Park-projektjének egyeteme."},{"nev":"Miskolci Egyetem","url":"https://www.uni-miskolc.hu/","megjegyzes":"InnoME TTC Kft.; több nemzeti laboratórium konzorciumi partnere."},{"nev":"Óbudai Egyetem","url":"https://uni-obuda.hu/","megjegyzes":"Initium Venture Labs Zrt. (TTC); a Science Park-projekt egyik egyeteme."},{"nev":"Magyar Agrár- és Élettudományi Egyetem","url":"https://uni-mate.hu/","megjegyzes":"Agrár- és Élelmiszerbiztonsági Kutatási Infrastruktúra (kiváló KI-hálózat, 2024); agrár NL-ek partnere; klímaadaptációs Misszióvezérelt NL (2026) nyertese."},{"nev":"Pázmány Péter Katolikus Egyetem","url":"https://ppke.hu/","megjegyzes":"PPKE ITK Jedlik laboratóriumok: kiváló kutatási infrastruktúra (NKFIH, 2024); a humanoid robotikai Misszióvezérelt NL (2026) nyertese."}],"linkek":[{"felirat":"HUN-REN támogatott kutatócsoportok listája","url":"https://www.tki-office.hu/a-hun-ren-tki-tamogatott-kutatocsoportjai/"},{"felirat":"Misszióvezérelt Nemzeti Laboratóriumok – támogatott projektek (NKFIH, 2026)","url":"https://nkfih.gov.hu/palyazoknak/nkfi-alap/missziovezerelt-nemzeti-laboratoriumok-tovabbfejlesztese-2026-411-missziok"},{"felirat":"Nemzeti Laboratóriumok – az első ciklus laborjai","url":"https://www.nemzetilaborok.nkfih.gov.hu/temateruletek"}]}');
--> statement-breakpoint
INSERT INTO `tudastar_kartya` (`id`, `kategoria`, `slug`, `tipus`, `nev`, `rovidites`, `osszefoglalo`, `honlap`, `sorrend`, `tartalom`) VALUES ('442db971-c9e8-a417-07d7-924c91cde9ad', 'egyetemek', 'innovacios-igazgatosagok', 'lista', 'Innovációs igazgatóságok és technológiatranszfer-irodák', NULL, 'Az egyetemek belső innovációs és technológiatranszfer-egységei: szellemitulajdon-kezelés, ipari kapcsolatok, belső pályázatok és kutatói tanácsadás. Ahol az egyetemnek technológiatranszfer-cége is van, a piaci hasznosítást jellemzően az végzi, az igazgatóság pedig a kutatói oldalt támogatja.', NULL, 2, '{"sorok":[{"nev":"ELTE Innovációs Központ","url":"https://www.elte.hu/innovacio","megjegyzes":"Innováció, vállalati együttműködés és technológiatranszfer; innovacio@innovacio.elte.hu."},{"nev":"BME KFI – Felsőoktatási Innovációmenedzsment és Együttműködési Központ (BME KFI – FIEK)","url":"https://innovacio.bme.hu/","megjegyzes":"Egyetem–ipar együttműködés, projekt- és pályázatmenedzsment, innovációs támogatás; 2025-ben jött létre a Kutatási és Fejlesztési Igazgatóság."},{"nev":"DE Innovációs Ökoszisztéma Központ","url":"https://innovacio.unideb.hu/","megjegyzes":"Benne a Technológiatranszfer Központ: szellemitulajdon-védelem, licenc és spin-off-alapítás; innovacio@unideb.hu."},{"nev":"SZTE Innovációmenedzsment Egység","url":"https://u-szeged.hu/egyetemrol-141002/innovaciomenedzsment/innovaciomenedzsment","megjegyzes":"A Stratégiai és Fejlesztési Főigazgatóság alatt; technológia- és tudástranszfer szakcsoport, együttműködés az SZTE TTC Zrt.-vel."},{"nev":"PTE Innovációmenedzsment és Gazdaságkapcsolati Igazgatóság","url":"https://innovacio.pte.hu/hu","megjegyzes":"Technológiatranszfer és innovációmenedzsment, K+F-szolgáltatások, technológiai ajánlatok, laborkapacitás."},{"nev":"Semmelweis Egyetem – Tudományos és Innovációs Rektorhelyettesi és Üzletfejlesztési Központ (TÜK)","url":"https://semmelweis.hu/tudrh/","megjegyzes":"A Rektori Kabinet része; szellemitulajdon-ügyintézés; a hasznosításról az Egyetemi Innovációs Bizottság dönt, a hasznosítást a TTC végzi."}],"linkek":[]}');
--> statement-breakpoint
INSERT INTO `tudastar_kartya` (`id`, `kategoria`, `slug`, `tipus`, `nev`, `rovidites`, `osszefoglalo`, `honlap`, `sorrend`, `tartalom`) VALUES ('2d0b0ddb-95df-d721-507f-4b7b65e96751', 'egyetemek', 'technologiatranszfer-cegek', 'lista', 'Egyetemi technológiatranszfer-cégek (TTC)', NULL, 'Az egyetemek – és a HUN-REN – tulajdonában álló technológiatranszfer-cégek: szellemi tulajdon hasznosítása, licenc, proof of concept és spin-off-alapítás. A modell a Nemzeti Innovációs Ügynökség 2023-ban indított kísérleti TTC-projektjéből nőtt ki (DE, ÓE, SE, SZE, SZTE); a hálózat fejlesztésére az NKFI Alap 2026-ban 6 milliárd forintos pályázatot hirdetett a 100%-os egyetemi vagy HUN-REN-tulajdonú TTC-knek (2026-1.1.2-TTC; a beadás 2026. április 16-án lezárult). Külföldi ipari partner licenc- vagy együttműködési ügyben elsőként a TTC-t keresse.', NULL, 3, '{"sorok":[{"nev":"SZTE TTC Zrt.","url":"https://sztettc.hu/","megjegyzes":"Szegedi Tudományegyetem; IP-menedzsment és licenc, inkubáció, ipari K+F-együttműködés; info@sztettc.hu."},{"nev":"UD Catapult Nonprofit Kft.","url":"https://catapult.unideb.hu/","megjegyzes":"Debreceni Egyetem."},{"nev":"PTE Inno-Capital Kft.","url":"https://innovacio.pte.hu/innocapital","megjegyzes":"Pécsi Tudományegyetem (100%-os egyetemi tulajdon)."},{"nev":"PE Innosquare TTC","url":"https://innosquare.hu/","megjegyzes":"Pannon Egyetem, Veszprém; 2025 márciusa óta működik; IP-menedzsment, projektgenerálás, spin-off-támogatás."},{"nev":"Nyíregyházi Egyetem Technológia- és Tudástranszfer Kft.","url":"https://ttc.nye.hu/","megjegyzes":"Nyíregyházi Egyetem."},{"nev":"Vet-Inno TTC Kft.","url":"https://www.vetinnottc.com/","megjegyzes":"Állatorvostudományi Egyetem; 2025-ben jött létre; PoC-projektek, spin-off-kezdeményezések."},{"nev":"InnoME TTC Kft.","url":"https://ttc.uni-miskolc.hu/","megjegyzes":"Miskolci Egyetem (100%-os egyetemi tulajdon)."},{"nev":"TF-INNO TTC Kft.","url":"https://tf.hu/egyetem/szervezeti-felepites/tf-inno-ttc-kft","megjegyzes":"Magyar Testnevelési és Sporttudományi Egyetem; 2025-ben jött létre."},{"nev":"Semmelweis Technológia Transzfer Központ Zrt.","url":"https://www.semmelweisttc.com/","megjegyzes":"Semmelweis Egyetem; az egyetemi szellemi tulajdon kizárólagos hasznosítója, core facility szolgáltatások, PoC-program."},{"nev":"Ecotech Nonprofit Zrt.","url":"https://ecotech.hu/","megjegyzes":"Dunaújvárosi Egyetem."},{"nev":"MOME TTC","url":"https://mome.hu/en/tudastranszfer-es-innovaciomenedzsment","megjegyzes":"A Moholy-Nagy Művészeti Egyetem technológiatranszfer-szervezete."},{"nev":"BME InnoLab Zrt.","url":"https://innolab.bme.hu/","megjegyzes":"BME (100%-os egyetemi tulajdon); technológiatranszfer, PoC-program; 2026 óta EU-notifikált megfelelőségértékelés építési termékekre."},{"nev":"Initium Venture Labs Zrt.","url":"https://initium.uni-obuda.hu/","megjegyzes":"Óbudai Egyetem."},{"nev":"Uni Inno Zrt.","url":"https://uni-inno.sze.hu/","megjegyzes":"Széchenyi István Egyetem; a hasznosító vállalkozás 2024 óta TTC-modellben: szellemi tulajdon, licenc, spin-off, innovációs parkok."},{"nev":"Hunrentech Kft.","url":"https://hunrentech.hu/","megjegyzes":"A HUN-REN Magyar Kutatási Hálózat technológiatranszfer-cége."}],"linkek":[{"felirat":"NKFIH: TTC-hálózat fejlesztése (2026-1.1.2-TTC)","url":"https://nkfih.gov.hu/palyazoknak/nkfi-alap/technologia-transzfer-vallalatok-halozatanak-fejlesztese-2026-112-ttc"},{"felirat":"NIÜ: Technology Transfer Company (TTC) projekt","url":"https://niu.hu/project/technology-transfer-company-ttc-projekt"},{"felirat":"NIÜ: Bemutatkoznak a TTC-vezetők (sorozat, 1. rész)","url":"https://niu.hu/news/bemutatkoznak-a-ttc-vezetok-szegedi-ttc-zrt"}]}');
--> statement-breakpoint
INSERT INTO `tudastar_kartya` (`id`, `kategoria`, `slug`, `tipus`, `nev`, `rovidites`, `osszefoglalo`, `honlap`, `sorrend`, `tartalom`) VALUES ('a26ae28d-f668-4d06-44d7-38a8e82bf030', 'egyetemek', 'egyetemi-inkubatorok-science-parkok', 'lista', 'Egyetemi inkubátorok, kompetenciaközpontok és science parkok', NULL, 'Összevont lista, mert ezekről a típusokról kevés az egységes, hivatalos adat. A Science Park-projektet (a Neumann János Program része) a Nemzeti Innovációs Ügynökség szakmailag támogatja és monitorozza hat egyetemen; a kompetenciaközpontok egy része a 2017-ben indult Felsőoktatási és Ipari Együttműködési Központok (FIEK) programjából nőtt ki.', NULL, 4, '{"sorok":[{"nev":"Science Park projekt (Nemzeti Innovációs Ügynökség)","url":"https://niu.hu/project/science-park-projekt","megjegyzes":"2023-ban 500 millió Ft állami forrás hat egyetem (DE, ÓE, PE, SE, SZE, SZTE) koncepciójára; a NIÜ szakmailag támogatja és monitorozza."},{"nev":"Győri Tudományos és Innovációs Park (Széchenyi István Egyetem)","url":"https://sciencepark.sze.hu/a-projektrol","megjegyzes":"Járműipar, digitális technológiák, kreatívipar, élelmiszeripar, egészségtechnológia; startup-, inkubációs és spin-off-támogatás."},{"nev":"Science Park Szeged (SZTE)","url":"https://u-szeged.hu/sztemagazin/2020/tudomanyos-park-epul-eli","megjegyzes":"Közel 85 hektáros tudományos, technológiai és ipari park az ELI ALPS mellett (2020-as tervek)."},{"nev":"BME Z10 Innovációs és Inkubációs Központ","url":"","megjegyzes":"A BME KFI – FIEK létesítménye, 2020-ban nyílt."},{"nev":"DE ImpactLab és Makerspace","url":"https://innovacio.unideb.hu/mit-nyujt-az-impactlab","megjegyzes":"3D-technológiai műhely, prototípusgyártás, biomechanikai labor; hallgatói és kutatói ötletek mentorálása."},{"nev":"ELTE IK Innovációs Labor","url":"https://www.inf.elte.hu/innovacios-labor","megjegyzes":"Vállalkozói ötletek és startupprojektek támogatása az ELTE Informatikai Karán."},{"nev":"Felsőoktatási és Ipari Együttműködési Központok (FIEK)","url":"https://nkfih.gov.hu/hivatalrol/hivatal-hirei/hol-tartanak-fiek","megjegyzes":"NKFIH-program: 2017-ben öt uniós forrású központ (Győr, Kaposvár, Miskolc, Kecskemét, Debrecen) és három közép-magyarországi konzorcium (BME, ELTE, SZIE – ma MATE) indult (2018-as összefoglaló)."},{"nev":"BME FIEK Biztonságtudományi és Technológiai Kompetencia Központ","url":"https://kompetenciakozpont.bme.hu/","megjegyzes":""},{"nev":"BME Zéró Karbon Központ","url":"https://zkk.bme.hu/","megjegyzes":""}],"linkek":[]}');
--> statement-breakpoint
INSERT INTO `tudastar_kartya` (`id`, `kategoria`, `slug`, `tipus`, `nev`, `rovidites`, `osszefoglalo`, `honlap`, `sorrend`, `tartalom`) VALUES ('df3cbc1e-1669-5ab7-e05e-72087556d3ac', 'egyetemek', 'egyetemi-kutatasi-infrastrukturak', 'lista', 'Egyetemi kutatási infrastruktúrák', NULL, 'Egyetemi kutatási infrastruktúrák az NKFIH minősítéseiből: a 2023–2024-es felmérésben „kiváló” vagy „kiváló hálózat” minősítést kapott (2024) tételek, valamint válogatás a 2021-ben „kiváló” minősítést szerzett egyetemi zászlóshajókból. A teljes, tématerületenkénti lista az NKFIH oldalán érhető el; az igénybevétel feltételeiről a befogadó egyetem ad tájékoztatást.', NULL, 5, '{"sorok":[{"nev":"Egészségipari Multidiszciplináris Kutató Központ","url":"","megjegyzes":"Debreceni Egyetem · kiváló (2024)"},{"nev":"Molekuláris Orvostudományi Elektrofiziológiai Kutatási Infrastruktúra","url":"","megjegyzes":"Debreceni Egyetem · kiváló (2024)"},{"nev":"Ipari Biotechnológiai Kiváló Kutatási Infrastruktúra","url":"","megjegyzes":"Debreceni Egyetem · kiváló (2024)"},{"nev":"Vegyipari kutatás-fejlesztési kísérleti üzem","url":"","megjegyzes":"Debreceni Egyetem · kiváló (2024)"},{"nev":"I. Magyar Celluláris Képalkotó Euro-BioImaging Node, illetve II. Magyar Orvosi és Preklinikai Képalkotó Euro-BioImaging Node","url":"","megjegyzes":"Debreceni Egyetem · kiváló (2021)"},{"nev":"Szegedi Tudományegyetem Anyagtudományi Műszerközpont","url":"","megjegyzes":"Szegedi Tudományegyetem · kiváló (2021)"},{"nev":"ELTE TTK Központi Kutató és Ipari Kapcsolatok Centrum (KKIC)","url":"https://kkic.elte.hu/","megjegyzes":"Eötvös Loránd Tudományegyetem · kiváló (2024)"},{"nev":"Intelligens ipari és infokommunikációs infrastruktúra (4i)","url":"","megjegyzes":"Eötvös Loránd Tudományegyetem · kiváló (2024)"},{"nev":"MOoVIH – Mesoscale Organ(oid) Vizualizációs Kutatási Infrastruktúra Hálózat","url":"","megjegyzes":"Eötvös Loránd Tudományegyetem · kiváló hálózat (2024)"},{"nev":"Kutatási Infrastruktúra Hálózat a Nyílt Tudományért (KINYIT)","url":"","megjegyzes":"Eötvös Loránd Tudományegyetem · kiváló hálózat (2024)"},{"nev":"EtnoLab","url":"","megjegyzes":"ELTE Humán Tudományok Kutatóközpontja (az NKFIH-listán: ELTE Bölcsészettudományi Kutatóközpont) · kiváló hálózat (2024)"},{"nev":"Nagyfeszültségű Laboratórium","url":"","megjegyzes":"Budapesti Műszaki és Gazdaságtudományi Egyetem · kiváló (2024)"},{"nev":"Funkcionális anyagok és kémiai analízis kutatólaboratórium","url":"","megjegyzes":"Budapesti Műszaki és Gazdaságtudományi Egyetem · kiváló (2024)"},{"nev":"Gabonatudományi Infrastruktúra Hálózat","url":"","megjegyzes":"Budapesti Műszaki és Gazdaságtudományi Egyetem · kiváló hálózat (2024)"},{"nev":"BME-GPK-PE-MK Fenntartható energetika és katalízis labor","url":"","megjegyzes":"Budapesti Műszaki és Gazdaságtudományi Egyetem · kiváló hálózat (2024)"},{"nev":"Békésy György Biofizikai Kutatóközpont","url":"","megjegyzes":"Semmelweis Egyetem · kiváló (2024)"},{"nev":"Farmakológiai és Gyógyszerkutatás-fejlesztési Központ","url":"","megjegyzes":"Semmelweis Egyetem · kiváló hálózat (2024)"},{"nev":"BBMRI Magyar Csomópont","url":"","megjegyzes":"Semmelweis Egyetem · kiváló (2021)"},{"nev":"Humán Reprodukciós Nemzeti Laboratórium","url":"","megjegyzes":"Pécsi Tudományegyetem · kiváló (2024)"},{"nev":"Innovatív Orvosi Technológiák Központja (IOTEK)","url":"","megjegyzes":"Pécsi Tudományegyetem · kiváló (2024)"},{"nev":"Nemzeti Sporttudományi és Életmód Kutatási Infrastruktúra Hálózat","url":"","megjegyzes":"Pécsi Tudományegyetem · kiváló hálózat (2024)"},{"nev":"4-es Biológiai Biztonsági Szintű Virológiai Kutatási és Oktatási Központ","url":"","megjegyzes":"Pécsi Tudományegyetem · kiváló (2021)"},{"nev":"Hulladékgazdálkodási Kompetencia Központ","url":"","megjegyzes":"Pannon Egyetem · kiváló (2024)"},{"nev":"Emberközpontú digitalizációs megoldások Ipar 5.0 laboratórium","url":"","megjegyzes":"Pannon Egyetem · kiváló (2024)"},{"nev":"Víztudományi, Vízminőségi és Víziökológiai Kutatóhálózat","url":"","megjegyzes":"Pannon Egyetem · kiváló hálózat (2024)"},{"nev":"Széchenyi István Egyetem – Győri Innovációs Park","url":"","megjegyzes":"Széchenyi István Egyetem · kiváló (2024)"},{"nev":"Széchenyi István Egyetem Járműipari Kutatóközpont","url":"","megjegyzes":"Széchenyi István Egyetem · kiváló (2021)"},{"nev":"PPKE ITK Jedlik laboratóriumok","url":"","megjegyzes":"Pázmány Péter Katolikus Egyetem · kiváló (2024)"},{"nev":"Agrár- és Élelmiszerbiztonsági Kutatási Infrastruktúra","url":"","megjegyzes":"Magyar Agrár- és Élettudományi Egyetem · kiváló hálózat (2024)"},{"nev":"Állategészségügyi omikai, képalkotó és adattó infrastruktúra","url":"","megjegyzes":"Állatorvostudományi Egyetem · kiváló (2024)"},{"nev":"Erdészeti és Faipari Innovációs Központ","url":"","megjegyzes":"Soproni Egyetem · kiváló (2024)"},{"nev":"Szőlészeti, Környezetkutatási és Biotechnológiai Laboratóriumok","url":"","megjegyzes":"Eszterházy Károly Katolikus Egyetem · kiváló (2024)"},{"nev":"Innovatív Járművek és Anyagok Tanszék","url":"","megjegyzes":"Neumann János Egyetem · kiváló (2024)"}],"linkek":[{"felirat":"NKFIH: minősített kutatási infrastruktúrák 2023–2024 (a 2021-es listával)","url":"https://nkfih.gov.hu/hivatalrol/hivatal-hirei/nemzeti-kutatasi-infrastruktura-2023-2024"}]}');
