INSERT INTO `tudastar_kartya` (`id`, `kategoria`, `slug`, `tipus`, `nev`, `rovidites`, `osszefoglalo`, `honlap`, `sorrend`, `tartalom`) VALUES ('d68e9fbb-f85b-d7dd-43bb-63ee1ea7f56b', 'egyetemek', 'egyetemi-spin-off-portfoliok', 'lista', 'Egyetemi spin-off portfóliók és hasznosítható technológiák', NULL, 'Ahol az egyetem nyilvánosan közzéteszi spin-off cégeit, hasznosításra kínált szellemi alkotásait vagy proof of concept projektjeit. A portfóliók többsége a TTC-knél épül; a tényleges technológiai ajánlatokról az illetékes TTC vagy innovációs igazgatóság ad tájékoztatást.', NULL, 6, '{"sorok":[{"nev":"ELTE spin-off cégek","url":"https://www.elte.hu/innovacio/spinoff","megjegyzes":"14, az ELTE-hez kapcsolódó spin-off (2023-as összeállítás): informatika, biotechnológia, robotika, gyógyszerfejlesztés, adatelemzés."},{"nev":"ELTE – hasznosításba vehető szellemi alkotások","url":"https://www.elte.hu/innovacio/hasznositasba-veheto","megjegyzes":""},{"nev":"ELTE – hasznosított szellemi alkotások","url":"https://www.elte.hu/innovacio/hasznositott","megjegyzes":""},{"nev":"PTE – technológiai ajánlatok","url":"https://innovacio.pte.hu/index.php/hu/technologia-ajanlatok","megjegyzes":""},{"nev":"SZTE TTC – egyetemi projektek","url":"https://sztettc.hu/egyetemi-kozossegnek/projektek/","megjegyzes":"Több mint 20 aktív projekt."},{"nev":"Debreceni Egyetem – hasznosítás és spin-off-alapítás","url":"https://innovacio.unideb.hu/hasznositas-spin-alapitas","megjegyzes":"A DE Technológiatranszfer Központ hasznosítási folyamata: licenc vagy spin-off."},{"nev":"BME Competence Map","url":"https://competence.bme.hu/","megjegyzes":"A BME kutatási kompetenciáinak kereshető térképe."},{"nev":"BME InnoLab – proof of concept program","url":"https://www.bme.hu/hirek/251111/bme-innolab-zrt-technologia-transzfer-koncepcio","megjegyzes":"Az NKFIH PoC-támogatásából három év alatt 350 millió Ft; 2025 novemberében 20–25 jelölt projekt volt látókörben."},{"nev":"Semmelweis TTC – proof of concept program","url":"https://semmelweis.hu/hirek/2026/04/02/piackepes-otletek-egyetemi-laborbol-itt-a-poc-program/","megjegyzes":"A második forduló 2026 tavaszán: 60 millió Ft, projektenként 5–25 millió Ft, az NKFIH PoC-támogatásából."}],"linkek":[]}');
--> statement-breakpoint
INSERT INTO `tudastar_kartya` (`id`, `kategoria`, `slug`, `tipus`, `nev`, `rovidites`, `osszefoglalo`, `honlap`, `sorrend`, `tartalom`) VALUES ('897467f6-e050-76d9-9bd7-d5e9c8c37ae0', 'szellemi-tulajdon', 'sztnh', 'intezmeny', 'Szellemi Tulajdon Nemzeti Hivatala', 'SZTNH', 'A szellemi tulajdon védelméért felelős kormányzati főhivatal: szabadalmi, használatiminta-, védjegy-, formatervezésiminta- és más iparjogvédelmi eljárásokat folytat, és szerzői jogi feladatokat is ellát. A külföldi partner és a hazai kutatóhely számára az oltalomszerzés, az újdonságkutatás és a szellemitulajdon-tanácsadás hazai kapuja.', 'https://sztnh.gov.hu/', 1, '{"profil":"Az SZTNH 130 éve foglalkozik a szellemi alkotások védelmével; a köznyelv régi nevén Szabadalmi Hivatalként is emlegeti. A szabadalmi törvény (1995. évi XXXIII. törvény) szerint a szellemi tulajdon védelméért felelős kormányzati főhivatal. Elnökét a miniszterelnök nevezi ki, három helyettesét az elnök javaslatára a felügyeletet ellátó miniszter; felügyeletét az igazságügyi miniszter látja el (90/2026. (V. 13.) Korm. rendelet 1. melléklet). Működését saját bevételeiből fedezi, azokkal önállóan gazdálkodik.\n\nFeladat- és hatásköre (Szt. 115/G. §):\n- iparjogvédelmi hatósági vizsgálatok és eljárások;\n- a szerzői és a szerzői joghoz kapcsolódó jogokkal összefüggő egyes feladatok;\n- állami dokumentációs és információs tevékenység a szellemi tulajdon területén;\n- részvétel a szellemi tulajdont szabályozó jogszabályok előkészítésében;\n- a szellemi tulajdon védelmére irányuló kormányzati stratégia kidolgozása és érvényesítése;\n- a nemzetközi és európai együttműködés szakmai feladatai;\n- a korai fázisú vállalkozásokat támogató adóalap-kedvezményhez kapcsolódó nyilvántartás.","tevekenyseg":"Oltalmi formák: szabadalom (nemzeti, európai és nemzetközi PCT-bejelentés, szabadalmi gyorsítósáv – PPH –, kiegészítő oltalmi tanúsítvány – SPC –, topográfiaoltalom), használati minta, védjegy, formatervezési minta, földrajzi árujelző, növényfajta-oltalom; szerzői jogi feladatok.\n\nSzolgáltatások: újdonságkutatás, szabadalmazhatósági vélemény, jogérvényességi, szabadalomtisztasági és témakutatás, szabadalomképességi értékelés; iparjogvédelmi adatbázisok (E-kutatás); IP Scan – ingyenes szellemitulajdon-tanácsadás kkv-knak és egyéni vállalkozóknak; képzések, szakkönyvtár, tudásbázis.\n\nElektronikus ügyintézés: az IPFORM rendszeren keresztül.","kapcsolat":{"email":"sztnh@hipo.gov.hu","telefon":"+36 1 312 4400","cim":"1081 Budapest, II. János Pál pápa tér 7. (levélcím: 1438 Budapest, Pf. 415.)"},"szakaszok":[{"cim":"Ügyfélszolgálat","szoveg":"Cím: 1054 Budapest, Akadémia u. 21.\n\n- Telefon: +36 1 474 5861, zöld szám: +36 80 345 678\n- E-mail: sztnh@hipo.gov.hu\n- Személyes ügyfélfogadás: kedd–csütörtök 9–14 óra\n- Telefonos ügyfélszolgálat: hétfő–csütörtök 9–17, péntek 9–14 óra"},{"cim":"Mire használhatja az attasé","szoveg":"- Külföldi partner magyarországi oltalomszerzése vagy oltalmi helyzetének felmérése: az SZTNH ügyfélszolgálata és az E-kutatás adatbázis.\n- Közös fejlesztés előtti újdonság- vagy szabadalomtisztasági (FTO) kutatás: az SZTNH szabadalmi kutatási szolgáltatásai.\n- Magyar kkv vagy startup szellemitulajdon-stratégiája: az IP Scan ingyenes tanácsadás.\n- Nemzetközi bejelentés magyar kutatóhelytől: a PCT-bejelentés és a szabadalmi gyorsítósáv (PPH) tájékoztatói."}],"programok":[{"nev":"IP Scan","url":"https://sztnh.gov.hu/kezdooldal/szolgaltatasok/ipscan","leiras":"Ingyenes szellemitulajdon-tanácsadás kkv-knak és egyéni vállalkozóknak: interjú, írásos elemzés, utókonzultáció."},{"nev":"Szabadalmi kutatási szolgáltatások","url":"https://sztnh.gov.hu/szabadalmi-szolgaltatasok","leiras":"Újdonságkutatás, szabadalmazhatósági vélemény, jogérvényességi, szabadalomtisztasági és témakutatás."},{"nev":"Nemzetközi bejelentés (PCT)","url":"https://sztnh.gov.hu/kezdooldal/szolgaltatasok/szabadalom/nemzetkozi-bejelentes-_pct_","leiras":"A nemzetközi (PCT) szabadalmi bejelentés tudnivalói."},{"nev":"Szabadalmi gyorsítósáv (PPH)","url":"https://sztnh.gov.hu/kezdooldal/szolgaltatasok/szabadalom/szabadalmi-gyorsitosav-_pph_","leiras":"A szabadalmi gyorsítósáv (Patent Prosecution Highway) tudnivalói."},{"nev":"Iparjogvédelmi adatbázisok (E-kutatás)","url":"https://sztnh.gov.hu/kezdooldal/szolgaltatasok/iparjogvedelmi-adatbazisok/E-kutatas","leiras":"Az SZTNH iparjogvédelmi adatbázisainak keresője."},{"nev":"Képzések","url":"https://sztnh.gov.hu/kezdooldal/szolgaltatasok/kepzes","leiras":"Szellemitulajdon-védelmi képzések."}],"linkek":[{"felirat":"Rólunk – feladatok, jogállás","url":"https://sztnh.gov.hu/kezdooldal/rolunk"},{"felirat":"Kapcsolat és ügyfélszolgálat","url":"https://sztnh.gov.hu/kezdooldal/kapcsolat"},{"felirat":"Szabadalom","url":"https://sztnh.gov.hu/kezdooldal/szolgaltatasok/szabadalom"},{"felirat":"Védjegy","url":"https://sztnh.gov.hu/kezdooldal/szolgaltatasok/vedjegy"},{"felirat":"Formatervezési minta","url":"https://sztnh.gov.hu/kezdooldal/szolgaltatasok/design"},{"felirat":"Elektronikus ügyintézés (IPFORM)","url":"https://ugyintezes.sztnh.gov.hu/ipform/"},{"felirat":"Angol nyelvű oldal","url":"https://sztnh.gov.hu/en/home"}]}');
--> statement-breakpoint
INSERT INTO `tudastar_kartya` (`id`, `kategoria`, `slug`, `tipus`, `nev`, `rovidites`, `osszefoglalo`, `honlap`, `sorrend`, `tartalom`) VALUES ('49266017-f5f8-d097-e2ab-c2bf33e17d1c', 'szellemi-tulajdon', 'szabvanyositas', 'lista', 'Szabványosítási szervezetek', NULL, 'A nemzeti szabványosítás közfeladatait kizárólagos jogkörrel a Magyar Szabványügyi Testület látja el, és ő képviseli Magyarországot a nemzetközi (ISO, IEC) és az európai (CEN, CENELEC, ETSI) szabványügyi munkában. Kutatási eredmény szabványba viteléhez vagy szabványosítási partnerkereséshez az MSZT műszaki bizottságai a belépési pont.', NULL, 2, '{"sorok":[{"nev":"Magyar Szabványügyi Testület (MSZT)","url":"https://www.mszt.hu/hu-hu/","megjegyzes":"A nemzeti szabványosításról szóló 1995. évi XXVIII. törvény szerinti köztestület; nemzeti, európai és nemzetközi szabványok közzététele."},{"nev":"MSZT – műszaki bizottságok","url":"https://www.mszt.hu/hu-hu/szabvanyositas/muszaki-bizottsagok","megjegyzes":"A nemzeti szabványosítási munka fórumai; csatlakozni az MSZT ügyintézési felületén lehet."},{"nev":"MSZT – szabvány-webáruház","url":"https://ugyintezes.mszt.hu/webaruhaz/szabvany-lista","megjegyzes":"Nemzeti szabványok vásárlása."},{"nev":"MSZT – Online Szabványtár","url":"https://szabvanykonyvtar.mszt.hu/","megjegyzes":"Online hozzáférés a magyar szabványgyűjteményhez."},{"nev":"CEN és CENELEC","url":"https://www.cencenelec.eu/","megjegyzes":"Európai szabványügyi szervezetek; munkájukban Magyarországot az MSZT képviseli."},{"nev":"ETSI – Európai Távközlési Szabványügyi Intézet","url":"https://www.etsi.org/","megjegyzes":"Európai távközlési szabványosítás; munkájában Magyarországot az MSZT képviseli."}],"linkek":[]}');
--> statement-breakpoint
INSERT INTO `tudastar_kartya` (`id`, `kategoria`, `slug`, `tipus`, `nev`, `rovidites`, `osszefoglalo`, `honlap`, `sorrend`, `tartalom`) VALUES ('9875b6c7-e59a-9c79-8996-1cce1c78b0b3', 'szellemi-tulajdon', 'akkreditacio-megfelelosegertekeles', 'lista', 'Akkreditációs és megfelelőségértékelési szervezetek', NULL, 'Az akkreditációt Magyarországon a Nemzeti Akkreditáló Hatóság végzi, amely az Európai Akkreditációs Együttműködés (EA) kölcsönös elismerési megállapodásának (MLA) aláírója. A termékek uniós megfelelőségértékelésére kijelölt (notifikált) szervezeteket az Európai Bizottság NANDO-adatbázisa tartja nyilván, magyar szervezetekkel együtt.', NULL, 3, '{"sorok":[{"nev":"Nemzeti Akkreditáló Hatóság (NAH)","url":"https://www.nah.gov.hu/","megjegyzes":"Nemzeti akkreditáló szerv, EA MLA-aláíró (kalibrálás, vizsgálat, tanúsítás, ellenőrzés stb.); az uniós MI-rendelet szerinti bejelentő hatóság; irányítója a gazdasági és energetikai miniszter."},{"nev":"Az EA tagjai és MLA-aláírói","url":"https://european-accreditation.org/ea-members/directory-of-ea-members-and-mla-signatories/","megjegyzes":"Az Európai Akkreditációs Együttműködés tagjegyzéke az elismert akkreditálási területekkel."},{"nev":"NANDO – notifikált szervezetek adatbázisa (Európai Bizottság)","url":"https://ec.europa.eu/growth/tools-databases/nando","megjegyzes":"A tagállamok által kijelölt megfelelőségértékelő szervezetek azonosítószámmal és feladatkörrel."},{"nev":"Notifikált szervezetek – tájékoztató (Európai Bizottság)","url":"https://single-market-economy.ec.europa.eu/single-market/goods/building-blocks/notified-bodies_en","megjegyzes":"Mi a notifikált szervezet, és mikor kell harmadik fél általi megfelelőségértékelés."},{"nev":"MSZT – tanúsítási szolgáltatások","url":"https://www.mszt.hu/hu-hu/tanusitas/tanusitasi-szolgaltatasok","megjegyzes":"A Magyar Szabványügyi Testület tanúsító tevékenysége."},{"nev":"BME InnoLab Zrt. – megfelelőségértékelés","url":"https://epito.bme.hu/hirek/Megfelelosegertekelesi_uzletag_elindult_a_BME_InnoLab_uj_szolgaltatasa","megjegyzes":"EU-notifikált terméktanúsító (NB 3233) és műszaki értékelő szervezet (TAB 3229) építési termékekre, 2026 ősze óta."},{"nev":"SZTFH – kiberbiztonsági felügyelet és tanúsítások","url":"https://sztfh.hu/tevekenysegek/kiberbiztonsagi-tanusitasok/kiberbiztonsagi-felugyelet/","megjegyzes":"A Szabályozott Tevékenységek Felügyeleti Hatósága kiberbiztonsági felügyeleti, tanúsítási és kiberreziliencia (CRA) feladatai."}],"linkek":[]}');
--> statement-breakpoint
INSERT INTO `tudastar_kartya` (`id`, `kategoria`, `slug`, `tipus`, `nev`, `rovidites`, `osszefoglalo`, `honlap`, `sorrend`, `tartalom`) VALUES ('33842253-3bdd-e07b-53bc-e49a1b7c5a63', 'szellemi-tulajdon', 'agazati-hatosagok', 'lista', 'Ágazati hatóságok', NULL, 'Az innovatív termékek és szolgáltatások piacra lépését engedélyező vagy felügyelő hazai hatóságok válogatása. Engedélyezési kérdésben a külföldi partnert közvetlenül az illetékes hatósághoz érdemes irányítani; a 2026-os kormányzati átalakítás után egyes hatáskörök változhattak.', NULL, 4, '{"sorok":[{"nev":"Nemzeti Népegészségügyi és Gyógyszerészeti Központ (NNGYK) – gyógyszerészet","url":"https://ogyei.gov.hu/","megjegyzes":"Gyógyszer, orvostechnikai eszköz, orvostudományi kutatások, géntechnológia, étrend-kiegészítők."},{"nev":"NNGYK – népegészségügy","url":"https://nngyk.gov.hu/hu/","megjegyzes":"Járványügy, sugáregészségügy, kémiai biztonság, közegészségügyi hatósági ügyek."},{"nev":"Nemzeti Élelmiszerlánc-biztonsági Hivatal (Nébih)","url":"https://portal.nebih.gov.hu/","megjegyzes":"Élelmiszerlánc-biztonság; az első ciklusban az Agrártechnológiai Nemzeti Laboratórium konzorciumvezetője."},{"nev":"Országos Atomenergia Hivatal (OAH)","url":"https://www.haea.hu/","megjegyzes":"Nukleáris létesítmények és radioaktív anyagok biztonsági és védettségi felügyelete, engedélyezés."},{"nev":"Nemzeti Média- és Hírközlési Hatóság (NMHH)","url":"https://nmhh.hu/","megjegyzes":"Média- és hírközlési hatóság."},{"nev":"Nemzeti Adatvédelmi és Információszabadság Hatóság (NAIH)","url":"https://naih.hu/","megjegyzes":"Adatvédelmi hatóság."},{"nev":"Szabályozott Tevékenységek Felügyeleti Hatósága (SZTFH)","url":"https://sztfh.hu/","megjegyzes":"Többek közt kiberbiztonsági felügyelet, bányászati és földtani tevékenység, ESG hatósági feladatok."},{"nev":"Magyar Nemzeti Bank (MNB)","url":"https://www.mnb.hu/web/fooldal","megjegyzes":"Pénzügyi szektor; az uniós MI-rendelet szerinti piacfelügyelet a pénzügyi szolgáltatásokban; Innovation Hub és tesztkörnyezet."},{"nev":"Gazdasági Versenyhivatal (GVH)","url":"https://www.gvh.hu/","megjegyzes":"Versenyhatóság."}],"linkek":[]}');
--> statement-breakpoint
INSERT INTO `tudastar_kartya` (`id`, `kategoria`, `slug`, `tipus`, `nev`, `rovidites`, `osszefoglalo`, `honlap`, `sorrend`, `tartalom`) VALUES ('0856a77e-24fc-513b-c8b2-0eebeef7941f', 'szellemi-tulajdon', 'szabalyozoi-tesztkornyezetek', 'lista', 'Szabályozói tesztkörnyezetek', NULL, 'Szabályozói tesztkörnyezet (regulatory sandbox): felügyelt keretben, korlátozott ideig, egyes előírások alóli mentességgel kipróbálható innováció. A pénzügyi szektorban az MNB működtet ilyet; az uniós MI-rendelet hazai végrehajtásáról szóló törvény szerint 2026. augusztus 2-tól az MI piacfelügyeleti hatóság – MI-ügyekben a tudományos és technológiai miniszter – működtet MI-tesztkörnyezetet.', NULL, 5, '{"sorok":[{"nev":"MNB Regulatory Sandbox","url":"https://www.mnb.hu/innovation-hub/regulatory-sandbox","megjegyzes":"Pénzügyi innováció tesztelése valós ügyfelekkel, korlátozott ideig, egyes szabályozói előírások alóli ideiglenes felmentéssel; innovationhub@mnb.hu."},{"nev":"MNB Innovation Hub","url":"https://www.mnb.hu/innovation-hub","megjegyzes":"A pénzügyi innovátorok közvetlen kapcsolata a felügyelettel szabályozási kérdésekben."},{"nev":"MI szabályozói tesztkörnyezet – 2025. évi LXXV. törvény","url":"https://njt.jog.gov.hu/jogszabaly/2025-75-00-00","megjegyzes":"Az uniós MI-rendelet hazai végrehajtása: a tesztkörnyezetet 2026. augusztus 2-tól az MI piacfelügyeleti hatóság – MI-ügyekben a tudományos és technológiai miniszter – működteti."},{"nev":"344/2025. (X. 31.) Korm. rendelet – MI-hatóságok kijelölése","url":"https://njt.jog.gov.hu/jogszabaly/2025-344-20-22","megjegyzes":"Bejelentő hatóság: NAH; MI piacfelügyeleti hatóság és egyedüli kapcsolattartó pont: a vállalkozásfejlesztésért felelős miniszter, MI-ügyekben a tudományos és technológiai miniszter."}],"linkek":[]}');
--> statement-breakpoint
INSERT INTO `tudastar_kartya` (`id`, `kategoria`, `slug`, `tipus`, `nev`, `rovidites`, `osszefoglalo`, `honlap`, `sorrend`, `tartalom`) VALUES ('67bf1b46-34b1-5094-122f-3689edc786db', 'szellemi-tulajdon', 'kutatasbiztonsag', 'lista', 'Kutatásbiztonsági és technológiabiztonsági kapcsolattartók', NULL, 'Kutatásbiztonság: a kritikus tudás és technológia nem kívánt átadásának, a rosszindulatú külföldi befolyásnak és az etikai, integritási sértéseknek a kezelése (az EU Tanácsának 2024. május 23-i ajánlása). Kijelölt nemzeti kutatásbiztonsági kapcsolattartót a hivatalos források nem neveznek meg; a lista az uniós kereteket és a technológiabiztonságban illetékes hazai szerveket sorolja.', NULL, 6, '{"sorok":[{"nev":"NKFIH – Kutatásbiztonság","url":"https://nkfih.gov.hu/hivatalrol/nemzetkozi-kapcsolatok/kutatasbiztonsag","megjegyzes":"Az NKFIH tájékoztató oldala: a kutatásbiztonsági és az Európai Kutatási Térségről szóló tanácsi ajánlás, Research Security Monitor."},{"nev":"Tanácsi ajánlás a kutatásbiztonság erősítéséről (C/2024/3510)","url":"https://nkfih.gov.hu/hivatalrol/nemzetkozi-kapcsolatok/kutatasbiztonsag/kutatasbiztonsagrol-szolo-tanacsi-ajanlas","megjegyzes":"Nemzeti szakpolitikák, finanszírozói biztosítékok és kutatóhelyi kockázatkezelés."},{"nev":"Európai Bizottság – gazdasági és kutatásbiztonság","url":"https://research-and-innovation.ec.europa.eu/strategy/strategy-research-and-innovation/europe-world/international-cooperation/strategic-autonomy-and-european-economic-and-research-security_en","megjegyzes":"Research Security Monitor, a külföldi beavatkozás elleni eszköztár, kockázatértékelési segédlet; készül az uniós szakértői központ."},{"nev":"BFKH – Exportellenőrzési Osztály","url":"https://kormanyhivatalok.hu/kormanyhivatalok/budapest/megye/szervezet/kereskedelmi-haditechnikai-exportellenorzesi-es","megjegyzes":"Kettős felhasználású termékek export-, transzfer-, tranzit- és brókerengedélyei; exportcontrol@bfkh.gov.hu."},{"nev":"Országos Atomenergia Hivatal (OAH)","url":"https://www.haea.hu/web/v3/OAHPortal.nsf/web?OpenAgent=&menu=02&submenu=2_0","megjegyzes":"Szakhatóság a nukleáris és a nukleáris kettős felhasználású termékek exportjának és importjának engedélyezésében."},{"nev":"Nemzeti Kiberbiztonsági Intézet (NBSZ NKI)","url":"https://nki.gov.hu/","megjegyzes":"A Nemzetbiztonsági Szakszolgálat intézete: incidensbejelentés, riasztások, sérülékenységi figyelmeztetések."},{"nev":"Alkotmányvédelmi Hivatal (AH)","url":"https://www.ah.gov.hu/","megjegyzes":"Nemzetbiztonsági szolgálat (polgári elhárítás); iparbiztonsági és nemzetbiztonsági ellenőrzés."}],"linkek":[]}');
--> statement-breakpoint
INSERT INTO `tudastar_kartya` (`id`, `kategoria`, `slug`, `tipus`, `nev`, `rovidites`, `osszefoglalo`, `honlap`, `sorrend`, `tartalom`) VALUES ('16d2c2e7-a2d6-cd49-4f1c-e130bf4db4df', 'befektetok', 'allami-finanszirozok', 'lista', 'Állami és állami hátterű finanszírozók', NULL, 'Az állami fejlesztési bank csoportja (MFB Csoport) és az NKFI Alap tőkeprogramjai állami forrásból fektetnek be korai fázisú innovatív cégekbe. Az MFB Csoporthoz tartozó Hiventures 2026 februárjában mintegy 17 milliárd forintos új kockázati tőkealapot indított; az NKFI Alap 2026. évi programstratégiája a vissza nem térítendő támogatások mellett állami társfinanszírozású kockázati tőkealapokat is tervez.', 'https://www.mfb.hu/', 1, '{"sorok":[{"nev":"MFB Magyar Fejlesztési Bank Zrt.","url":"https://www.mfb.hu/","megjegyzes":"Állami fejlesztési bank; csoportjához tartozik a Hiventures, az MFB Invest és a Garantiqa Hitelgarancia. Hitelprogramjai az MFB Pontokon érhetők el."},{"nev":"MFB Invest Zrt.","url":"https://www.mfb.hu/mfb-csoport/mfb-invest-zrt-s13","megjegyzes":"2006 óta; legalább 500 millió Ft tőkeigényű ügyletekben, főként kisebbségi tulajdonosként fektet be, 4–7 éves kilépéssel. A Hiventures 100%-os tulajdonosa."},{"nev":"Hiventures Zrt.","url":"https://hiventures.hu/","megjegyzes":"Az MFB Csoport kockázatitőke-alapkezelője, 120+ aktív portfóliócéggel; 2026 februárjától kb. 17 Mrd Ft-os, uniós (GINOP Plusz) forrású alap korai fázisú startupoknak."},{"nev":"EXIM Invest Befektetési és Vagyonkezelő Zrt.","url":"https://eximinvest.hu/","megjegyzes":"Honlapja szerint nemzetközileg is versenyképes magyar társaságok fejlődését célzó tőkealapokból fektet be; az EXIM tőkealapjai ügyében az EXIM is hozzá irányít. A HVCA tagja."},{"nev":"Korai fázisú kutatás-fejlesztési kockázati tőkeprogram (GINOP Plusz-2.5.1-25)","url":"https://nkfih.gov.hu/palyazoknak/szechenyi-terv-plusz/korai-fazisu-kutatas-fejlesztesi-kockazati-tokeprogram-ginop-plusz-251-25/palyazati-felhivas","megjegyzes":"Meghirdetve 2025. december 11.; 18,12 Mrd Ft, két alap (kevésbé fejlett régiók, Budapest); a befektetések az állami alapkezelő kijelölése után indulnak, elsősorban TRL 6 fölött."},{"nev":"SEED társbefektetési alap (NKFI Alap)","url":"https://nkfih.gov.hu/hivatalrol/kfi-szakpolitika/programstrategia-2026","megjegyzes":"A 2026. évi programstratégiában (2025. november) tervezett 10 Mrd Ft-os tőkeprogram: matching fund szerkezetben, korai fázisú mikro- és kisvállalkozásoknak; az ügyletet a piaci befektető hozza."},{"nev":"Startup Factory (NKFI Alap)","url":"https://nkfih.gov.hu/hivatalrol/kfi-szakpolitika/programstrategia-2026","megjegyzes":"Állami–magán társbefektetési modellben működő technológiai inkubátorok programja; a 2026. évi programstratégia szerint újraindul, tervezett kerete 6 Mrd Ft. A 2023-as 12 inkubátor külön kártyán."}],"linkek":[{"felirat":"Az NKFI Alap 2026. évi programstratégiája","url":"https://nkfih.gov.hu/hivatalrol/kfi-szakpolitika/programstrategia-2026"},{"felirat":"Hiventures: új korai fázisú alap (2026. február)","url":"https://hiventures.hu/uj-korai-fazisu-befektetesi-alapot-indit-a-hiventures/"}]}');
--> statement-breakpoint
INSERT INTO `tudastar_kartya` (`id`, `kategoria`, `slug`, `tipus`, `nev`, `rovidites`, `osszefoglalo`, `honlap`, `sorrend`, `tartalom`) VALUES ('ab8d6f86-c9ee-2dad-1970-f7364d4a79ee', 'befektetok', 'kockazatitoke-alapok', 'lista', 'Kockázatitőke-alapkezelők', NULL, 'A hazai kockázati- és magántőke-iparág szakmai szervezete a Magyar Kockázati- és Magántőke Egyesület (HVCA), mintegy 70 taggal; taglistája és a magyar befektetések listája a honlapján érhető el. Az alábbi alapkezelők a HVCA tagjai; a lista válogatás a technológiai és növekedési befektetőkből, a leírások a saját honlapjuk közlései.', 'https://www.hvca.hu/', 2, '{"sorok":[{"nev":"Magyar Kockázati- és Magántőke Egyesület (HVCA)","url":"https://www.hvca.hu/","megjegyzes":"Közel 35 éve a hazai kockázati- és magántőke-iparág szakmai platformja, mintegy 70 taggal (befektetők, jogi, tanácsadói és pénzügyi szolgáltatók)."},{"nev":"Day One Capital","url":"https://dayonecapital.com/","megjegyzes":"Közép-kelet-európai alapítók technológiai cégeibe fektet be; budapesti iroda."},{"nev":"PortfoLion Capital Partners","url":"https://www.portfolion.com/","megjegyzes":"Többfázisú befektető Közép-Kelet-Európában: kockázati tőke (pre-seed–seed, 0,5–3 M EUR), növekedési tőke és magántőke."},{"nev":"Platina Capital Kockázati Tőkealap-kezelő Zrt.","url":"https://platinacapital.hu/","megjegyzes":"Korai, növekedési és érett szakaszú, elsősorban digitális innovatív cégekbe fektet be; korábbi neve Nukleus Kockázati Tőkealap-kezelő Zrt."},{"nev":"Impact Ventures Zrt.","url":"https://impactventures.hu/","megjegyzes":"Hatásbefektető: a pénzügyi eredmény mellett mérhető társadalmi vagy környezeti hatást célzó vállalkozásokba fektet be."},{"nev":"FundWise Zrt.","url":"https://fundwise.hu/","megjegyzes":"2008-ban alakult független kockázatitőke-alapkezelő; kb. 27 Mrd Ft kezelt vagyon, a régió kis- és középvállalataiba fektet be."},{"nev":"Széchenyi Alapok Zrt.","url":"https://szta.hu/","megjegyzes":"2011 óta; több mint 155 Mrd Ft tőkekeret, főként kkv- és nagyvállalati befektetések. Tulajdonosa a Rudolf Kalman Óbudai Egyetemért Alapítvány."}],"linkek":[{"felirat":"A HVCA tagjai","url":"https://www.hvca.hu/hu/tagok"}]}');
--> statement-breakpoint
INSERT INTO `tudastar_kartya` (`id`, `kategoria`, `slug`, `tipus`, `nev`, `rovidites`, `osszefoglalo`, `honlap`, `sorrend`, `tartalom`) VALUES ('2ccdab90-0e1c-012a-9f9e-919aa11e1a7b', 'befektetok', 'uzleti-angyalok', 'lista', 'Üzleti angyal hálózatok', NULL, 'Az angyalbefektetőket, inkubátorokat és korai fázisú alapokat tömörítő HunBAN egyesület pitch-eseményekkel, online bemutatkozásokkal és előszűrt startupokkal köti össze az alapítókat, a befektetőket és a mentorokat. Az NKFI Alap 2026. évi programstratégiája üzleti angyaloknak szóló garanciaprogramot is tervez.', 'https://hunban.eu/', 3, '{"sorok":[{"nev":"HunBAN – Hungarian Business Angel Network","url":"https://hunban.eu/","megjegyzes":"Alapítókat, befektetőket és mentorokat összekötő hálózat: pitch-események, 60 perces online bemutatkozások, előszűrt startupok; budapesti iroda."},{"nev":"Üzleti Angyal Garancia Program (NKFI Alap)","url":"https://nkfih.gov.hu/hivatalrol/kfi-szakpolitika/programstrategia-2026","megjegyzes":"Garanciatámogatás a nagy növekedési potenciálú, innovatív startupokba kockázati tőkével befektető üzleti angyaloknak; a 2026. évi programstratégiában tervezett keret 0,5 Mrd Ft."}],"linkek":[]}');
--> statement-breakpoint
INSERT INTO `tudastar_kartya` (`id`, `kategoria`, `slug`, `tipus`, `nev`, `rovidites`, `osszefoglalo`, `honlap`, `sorrend`, `tartalom`) VALUES ('522cb121-28a8-1974-fd58-75ddf6ef9719', 'befektetok', 'bankok-garanciaintezmenyek', 'lista', 'Banki innovációfinanszírozás: fejlesztési bankok és garanciaintézmények', NULL, 'A hitel- és garanciaoldali vállalati finanszírozás állami és állami hátterű szereplői. A konkrét hitel- és tőkeprogramok, köztük a GINOP Plusz pénzügyi eszközei, gyakran változnak, ezért az aktuális konstrukciókat mindig a kezelő honlapján vagy a palyazat.gov.hu-n érdemes ellenőrizni.', NULL, 4, '{"sorok":[{"nev":"MFB Magyar Fejlesztési Bank Zrt. – MFB Pontok","url":"https://www.mfb.hu/","megjegyzes":"Az állami fejlesztési bank hitelprogramjai a partnerbankok MFB Pont hálózatán keresztül igényelhetők."},{"nev":"EXIM Magyarország","url":"https://exim.hu/","megjegyzes":"Beruházási, forgóeszköz- és zöld hitel, garancia és exporthitel-biztosítás kkv-knak és nagyvállalatoknak, a belföldi és az exporttevékenységhez."},{"nev":"Garantiqa Hitelgarancia Zrt.","url":"https://garantiqa.hu/","megjegyzes":"1992 óta kezességet vállal kkv-k hiteléhez, garanciájához, lízing- és faktoringügyleteihez; az MFB Csoport tagja."},{"nev":"KAVOSZ – Széchenyi Kártya Program","url":"https://www.kavosz.hu/","megjegyzes":"Kkv-hitelek: folyószámla-, likviditási és beruházási hitel, mikrohitel, lízing, agrár konstrukciók."},{"nev":"Pályázati portál (palyazat.gov.hu)","url":"https://www.palyazat.gov.hu/","megjegyzes":"Az uniós és hazai fejlesztési programok, köztük a GINOP Plusz hitel- és tőkeprogramjainak hivatalos közleményei."}],"linkek":[]}');
--> statement-breakpoint
INSERT INTO `tudastar_kartya` (`id`, `kategoria`, `slug`, `tipus`, `nev`, `rovidites`, `osszefoglalo`, `honlap`, `sorrend`, `tartalom`) VALUES ('f0d920a8-771a-d625-cd76-33cad44aa33c', 'befektetok', 'inkubacios-vallalati-befektetok', 'lista', 'Inkubációs és akcelerációs befektetők (Startup Factory); vállalati kockázati tőke', NULL, 'Az NKFI Alap Startup Factory programjában állami–magán társbefektetési modellben működő technológiai inkubátorok fektetnek be korai fázisú startupokba, és szakmai, üzleti tudást is adnak. A lista a 2023-as felhívás 12 támogatott inkubátora (NKFIH: 2023. december 7-i döntés 11, december 18-i döntés további 1 projekt; összesen mintegy 5,75 Mrd Ft) a projekt címével, helyszínével és a támogatással. Önálló hazai vállalati kockázatitőke-programot (CVC) hivatalos forrásból nem azonosítottunk; a nagyvállalati nyílt innovációs programokat a 8. kategória sorolja fel.', NULL, 5, '{"sorok":[{"nev":"Lunar Program Zrt.","url":"","megjegyzes":"Lunar Program – Startup Factory Inkubációs Program; Budapest; 246,5 M Ft támogatás."},{"nev":"White Unicorn Befektetési és Tanácsadó Kft.","url":"https://www.whiteunicorn.hu/","megjegyzes":"Inkubátorház főként egészségügyi és IT fókusszal (finanszírozás, matchmaking, szakmai inkubáció); Budapest; 250 M Ft."},{"nev":"Nesprit Ventures Zrt.","url":"https://nesprit.vc/","megjegyzes":"Inkubációs program; Budapest; kb. 250 M Ft."},{"nev":"Virgo Ventures Technológiai Inkubátor Kft.","url":"","megjegyzes":"Startup Factory Program II. (2024–2026); Budapest; 450 M Ft."},{"nev":"Első Közép-Európai Hardver Akcelerátor Kft.","url":"","megjegyzes":"Hardveres innovációs ökoszisztéma kialakítása; Bonyhád; 450 M Ft."},{"nev":"STRT Invest Kft.","url":"","megjegyzes":"STRT innovációs inkubátor; Budapest; 450 M Ft."},{"nev":"BNL Start Partners Kft.","url":"","megjegyzes":"Inkubátorprogram kezdő ötletgazdáknak és haladó innovatív vállalkozóknak; Miskolc, Egyetemváros; 450 M Ft."},{"nev":"OXO Labs Üzletviteli és Tanácsadó Kft.","url":"","megjegyzes":"Oxo Labs Startup Factory; Budapest; 450 M Ft."},{"nev":"Startup Campus Inkubator Zrt.","url":"https://www.startupcampus.hu/","megjegyzes":"Startup Campus – Ötlettől a nemzetközi piacig! 2.0; Debrecen; 450 M Ft."},{"nev":"GUKA Energetikai Zrt.","url":"","megjegyzes":"Startup Factory program az informatikai és zöld innovációk szolgálatában; Békéscsaba; kb. 900 M Ft."},{"nev":"Creative Accelerator Kft.","url":"https://creativeaccelerator.hu/","megjegyzes":"Élettudományi fókuszú inkubátorprogram; Szeged; kb. 900 M Ft."},{"nev":"Védelmi Innovációs Kutatóintézet Nonprofit Zrt.","url":"","megjegyzes":"VIRTUS – védelmi innovációs venture studio; Budapest; 500 M Ft (2023. december 18-i döntés)."}],"linkek":[{"felirat":"Startup Factory 2023: támogatott projektek (NKFIH)","url":"https://nkfih.gov.hu/english/nrdi-fund/funded-projects-2023-113-startup"},{"felirat":"Az NKFI Alap 2026. évi programstratégiája","url":"https://nkfih.gov.hu/hivatalrol/kfi-szakpolitika/programstrategia-2026"}]}');
--> statement-breakpoint
INSERT INTO `tudastar_kartya` (`id`, `kategoria`, `slug`, `tipus`, `nev`, `rovidites`, `osszefoglalo`, `honlap`, `sorrend`, `tartalom`) VALUES ('a17cc980-fab6-cff9-85a0-76c0a510410b', 'befektetok', 'deep-tech-finanszirozok', 'lista', 'Deep tech finanszírozók', NULL, 'A tudományos és mérnöki áttörésekre épülő technológiák finanszírozására 2026 márciusában külön állami tőkeprogramot hirdettek meg: a GINOP Plusz Technológiaspecifikus Kockázati Tőkeprogramja a kiválasztandó alapkezelőkön (pénzügyi közvetítőkön) keresztül fektet be. Európai szinten az Európai Innovációs Tanács (EIC) saját meghatározása szerint az egyik legnagyobb deep tech befektető; a magyar pályázóknak az NKFI Hivatal nemzeti kapcsolattartója ad tanácsot.', NULL, 6, '{"sorok":[{"nev":"Technológiaspecifikus Kockázati Tőkeprogram (GINOP Plusz-2.5.2-26)","url":"https://nkfih.gov.hu/english/szechenyi-plan-plus/technology-specific-venture-capital-programme-ginop-plusz-252-26","megjegyzes":"Meghirdetve 2026. március 25.; 55,12 Mrd Ft; a kiválasztandó alapkezelőkön át vállalkozásonként 200–2000 M Ft-os tőkebefektetés deep tech kkv-kba, elsősorban TRL 6 fölött."},{"nev":"Hiventures – a 2026-os korai fázisú alap","url":"https://hiventures.hu/uj-korai-fazisu-befektetesi-alapot-indit-a-hiventures/","megjegyzes":"A mintegy 17 Mrd Ft-os alap kiemelten a mesterséges intelligencia, a deeptech és az egészségügyi fejlesztések startupjait célozza."},{"nev":"Európai Innovációs Tanács (EIC)","url":"https://eic.ec.europa.eu/index_en","megjegyzes":"Pathfinder, Transition, Accelerator, STEP Scale Up és az EIC Fund tőkebefektetései; magyar nemzeti kapcsolattartó: NKFI Hivatal."}],"linkek":[{"felirat":"GINOP Plusz-2.5.2-26 közlemény (palyazat.gov.hu)","url":"https://www.palyazat.gov.hu/kozlemenyek/megjelent-a-technologiaspecifikus-kockazati-tokeprogram-cimu-ginop-plusz-2-5-2-26-kodszamu-felhivas"}]}');
--> statement-breakpoint
INSERT INTO `tudastar_kartya` (`id`, `kategoria`, `slug`, `tipus`, `nev`, `rovidites`, `osszefoglalo`, `honlap`, `sorrend`, `tartalom`) VALUES ('77c40529-e6b6-ed58-a263-05a51ff458ae', 'befektetok', 'egyetemi-poc-alapok', 'lista', 'Egyetemi és proof-of-concept alapok', NULL, 'Az egyetemi és kutatóintézeti eredmények hasznosítását célzó tőke- és támogatási programok. A proof-of-concept szakaszt támogató Life Sciences Catalyst felhívások (2025), valamint a technológiatranszfer-cégek (TTC) és a kórházi inkubátorok 2026-os felhívásai lezárultak; az NKFI Alap 2026. évi programstratégiája élettudományi egyetemi kockázatitőke-alapot is tervez. Egyetemi hátterű kockázatitőke-társaságként működik az Óbuda Uni Venture Capital.', NULL, 7, '{"sorok":[{"nev":"Life Sciences Catalyst Venture Capital Fund (NKFI Alap)","url":"https://nkfih.gov.hu/hivatalrol/kfi-szakpolitika/programstrategia-2026","megjegyzes":"Tervezett, 20 Mrd Ft; co-investment struktúrában fektetne TRL 4 feletti élettudományi startupokba és spin-offokba, főként az egyetemi TTC-k portfóliójából."},{"nev":"Life Sciences Catalyst Program I–II. (NKFI Alap)","url":"https://nkfih.gov.hu/palyazoknak/nkfi-alap/life-sciences-catalyst-program-celponttol-a-koncepcio-bizonyitasaig-2025-113-life-sciences-1/palyazati-felhivas","megjegyzes":"Két felhívás (2025-1.1.3 és 2025-1.1.4-LIFE SCIENCES), beadás 2025. november 28-ig (lezárult); 7,4 és 5,3 Mrd Ft: a célponttól a koncepció bizonyításáig, onnan a klinikai vizsgálatokig."},{"nev":"Technológiatranszfer-cégek (TTC) hálózatának fejlesztése (2026-1.1.2-TTC)","url":"https://nkfih.gov.hu/palyazoknak/nkfi-alap/technologia-transzfer-vallalatok-halozatanak-fejlesztese-2026-112-ttc/palyazati-felhivas","megjegyzes":"Meghirdetve 2026. március 18., beadás április 16-ig (lezárult); 6 Mrd Ft: új TTC-k megalapozása, a működők szintlépése és csomóponti TTC-k kialakítása."},{"nev":"MEDTECH Kórházi Inkubátor Program (2026-1.1.1-MEDTECH)","url":"https://nkfih.gov.hu/palyazoknak/nkfi-alap/medtech-korhazi-inkubator-program-2026-111-medtech/palyazati-felhivas","megjegyzes":"Meghirdetve 2026. február 12., beadás március 31-ig (lezárult); 2 Mrd Ft: kórházi megoldások inkubálása a prototípusig vagy a piacra vitelig."},{"nev":"Óbuda Uni Venture Capital Zrt.","url":"https://szta.hu/rolunk/","megjegyzes":"2023-ban alapította a Széchenyi Alapok, az Óbudai Egyetem és közös tulajdonosuk; rajta keresztül startupok is a befektetési célpontok közé kerültek."}],"linkek":[{"felirat":"Az NKFI Alap 2026. évi programstratégiája","url":"https://nkfih.gov.hu/hivatalrol/kfi-szakpolitika/programstrategia-2026"},{"felirat":"Life Sciences Catalyst Program II. – felhívás (NKFIH)","url":"https://nkfih.gov.hu/palyazoknak/nkfi-alap/life-sciences-catalyst-program-koncepcio-bizonyitasatol-a-klinikai-vizsgalatokig-2025-114-life-sciences-2/palyazati-felhivas"}]}');
--> statement-breakpoint
INSERT INTO `tudastar_kartya` (`id`, `kategoria`, `slug`, `tipus`, `nev`, `rovidites`, `osszefoglalo`, `honlap`, `sorrend`, `tartalom`) VALUES ('f6bc8ee6-7fbb-a93a-5413-6b09851eeada', 'vallalatok', 'innovativ-nagyvallalatok', 'lista', 'Innovatív nagyvállalatok és KFI-központok (10 kiemelt vállalat)', NULL, 'A rangsor forrása az EU Industrial R&D Investment Scoreboard 2025 (JRC, 2025. december; 2024-es üzleti év): a világ 2000 és az EU 800 legnagyobb ipari K+F-befektetője között magyar székhelyű vállalatként egyedül a Richter Gedeon szerepel. A WIPO magyar országprofilja szerint a 2022–2024-es PCT-bejelentések élén is a Richter áll, a vállalatok közül utána az Aimotive. A további nyolc vállalat nem rangsorolt: betűrendes válogatás a Magyarországon jelentős K+F-tevékenységet folytató nagyvállalatokból, saját közléseik alapján.', NULL, 1, '{"sorok":[{"nev":"Richter Gedeon Nyrt.","url":"https://www.gedeonrichter.com/hu-hu","megjegyzes":"Scoreboard 2025: a világon 823., az EU-ban 144.; K+F-ráfordítás 241,3 M EUR (2024). Saját közlése szerint 1200 főt meghaladó kutató-fejlesztő bázis."},{"nev":"Aimotive","url":"https://aimotive.com/","megjegyzes":"WIPO: a Richter után a legtöbb PCT-bejelentést tevő magyar vállalat (2022–2024). Automatizált vezetési szoftverek, szimulációs eszközök, autóipari NPU."},{"nev":"Audi Hungaria – Műszaki Fejlesztés (Győr)","url":"https://audi.hu/hu/portfolio/muszaki-fejlesztes.html","megjegyzes":"Csaknem 25 éve műszaki fejlesztés a motor- és járműgyártás mellett, az Audi és a Volkswagen Konszern számára; 2025 novemberében teljesítményelektronikával bővült."},{"nev":"Bosch – Budapesti Fejlesztési Központ (Robert Bosch Kft.)","url":"https://www.bosch.hu/vallalatunk/a-bosch-magyarorszagon/budapest-robert-bosch-kft/","megjegyzes":"2005-ben alakult; több mint 3100 munkavállalójával az autóipari mérnökök számát tekintve Magyarország Németország után a Bosch második legnagyobb európai fejlesztési helyszíne."},{"nev":"Egis Gyógyszergyár Zrt.","url":"https://hu.egis.health/cegismerteto","megjegyzes":"A Servier Csoport tagja; a 2024/2025-ös üzleti évben csaknem 23 Mrd Ft K+F, kutatás-fejlesztési központ mindhárom magyarországi telephelyén."},{"nev":"Ericsson Magyarország","url":"https://www.ericsson.com/hu/about-us/company-facts/ericsson-worldwide/hungary","megjegyzes":"Saját közlése szerint az egyik legnagyobb távközlési és informatikai kutató- és szoftverfejlesztő cég; a globális termékfejlesztés kulcshelyszíne."},{"nev":"evosoft (Siemens)","url":"https://www.evosoft.hu/","megjegyzes":"A Siemens 100%-os tulajdona, a Siemens Foundational Technologies Development szervezet része; szoftverfejlesztés."},{"nev":"Knorr-Bremse (Budapest)","url":"https://rail.knorr-bremse.com/en/hu/about-us/knorr-bremse-in-hungary/","megjegyzes":"A vasúti divízió budapesti telephelye (1995 óta, 1800+ fő) a vasúti fékrendszerek legnagyobb gyártó- és fejlesztőhelye; a haszonjármű-divíziónak is van magyarországi K+F-központja."},{"nev":"MOL-csoport","url":"https://molgroup.info/hu/uzleteink/downstream/kutatas-es-fejlesztes","megjegyzes":"Downstream K+F (2020 óta Mosonyi György Termékfejlesztési Központ, poliol-fejlesztés) és csoportszintű Open Innovation Hub."},{"nev":"Nokia (Budapest)","url":"https://www.nokia.com/careers/our-locations/hungary/","megjegyzes":"Több mint 1000 fős távközlési K+F-központ; a Bell Labs egyik helyszíne, 5G-fejlesztés."}],"linkek":[{"felirat":"The 2025 EU Industrial R&D Investment Scoreboard (JRC)","url":"https://publications.jrc.ec.europa.eu/repository/handle/JRC144638"},{"felirat":"WIPO: Magyarország szellemitulajdon-statisztikai profilja (PDF)","url":"https://www.wipo.int/edocs/statistics-country-profile/en/hu.pdf"}]}');
--> statement-breakpoint
INSERT INTO `tudastar_kartya` (`id`, `kategoria`, `slug`, `tipus`, `nev`, `rovidites`, `osszefoglalo`, `honlap`, `sorrend`, `tartalom`) VALUES ('ab8d706f-dc59-d857-40a5-d33255ae12d7', 'vallalatok', 'innovativ-kkv-startupok', 'lista', 'Kiemelt innovatív kkv-k, startupok és nyílt innovációs programok', NULL, 'A kiválasztás forrása a Magyar Innovációs Nagydíj: a Magyar Innovációs Szövetség 2026. március 18-án adta át a 2025-ös innovációs teljesítményeket elismerő Nagydíjat és kilenc további díjat (91 pályázatból; a pályázók 68%-a kkv, 16%-a startup). A díjazottak után egy EIT által kiemelt startup és a nyílt innovációs programok következnek; a startup- és technológiai szervezeteket és az egyetem–vállalat együttműködési programokat a 3. kategória „Startup- és technológiai szervezetek, vállalati és nyílt innovációs programok” kártyája gyűjti.', NULL, 2, '{"sorok":[{"nev":"Kravtex-Kühne Csoport (Credobus)","url":"","megjegyzes":"Magyar Innovációs Nagydíj 2025: ultrakönnyű városi-elővárosi buszcsalád (dízel Econell Next, elektromos Electronell); Mosonmagyaróvár, Győr."},{"nev":"Webwise Hungary Kft.","url":"","megjegyzes":"MKIK KKV Innovációs Díj 2025: a Syncee kereskedelmi rendszer, amely a magyar cégek exportpiacra lépését segíti."},{"nev":"Omixon Biocomputing Kft.","url":"","megjegyzes":"Ipari Innovációs Díj 2025: NanoTYPE és NanoTYPE HLA 11 Plus transzplantációs genetikai tesztek."},{"nev":"PCB Design Kft. és CAD-Terv Mérnöki Kft.","url":"","megjegyzes":"Informatikai Innovációs Díj 2025: QM kvantumvezérlő hardverplatform."},{"nev":"Hevesgép Kft.","url":"","megjegyzes":"Agrár Innovációs Díj 2025: új generációs rendfelszedő család megnövelt teljesítményű silókombájnokhoz."},{"nev":"CoreComm SI Kft.","url":"","megjegyzes":"Energetikai Innovációs Díj 2025: tetőcserépbe integrált napelemes rendszer."},{"nev":"Virgin Oil Press Kft.","url":"","megjegyzes":"Környezetvédelmi Innovációs Díj 2025: vegyszermentes, hulladék nélküli élelmiszeripari értékmentés."},{"nev":"Pro Patria Electronics Kft.","url":"","megjegyzes":"SZTNH Iparjogvédelmi Innovációs Díj 2025: PASR-17c Pointer passzív radar."},{"nev":"eChemicles Zrt.","url":"","megjegyzes":"NKFIH DeepTech Díj 2025: zöld vegyi anyagokat előállító CO₂-elektrolizáló rendszer."},{"nev":"Kodesage Zrt.","url":"","megjegyzes":"MISZ Startup Innovációs Díj 2025: generatív mesterséges intelligenciával támogatott nagyvállalati szoftverfejlesztési automatizáció."},{"nev":"Turbine AI","url":"","megjegyzes":"Az EIT 2025. decemberi közleményének példája: gépi tanulásos szimulációval jelzi előre a rákos sejtek kezelésre adott válaszát; EIT Health Gold Track."},{"nev":"MOL-csoport – Open Innovation Hub","url":"https://molgroup.info/hu/uzleteink/innovativ-uzletagak-es-szolgaltatasok/open-innovation-hub-2","megjegyzes":"Nyílt innováció: inkubátorházakkal, kockázatitőke-alapokkal, egyetemekkel, kutatóintézetekkel és induló vállalkozásokkal keres partnerséget."}],"linkek":[{"felirat":"XXXIV. Magyar Innovációs Nagydíj – díjazottak","url":"https://innovacio.hu/magyar-innovacios-nagydij/xxxiv-innovacios-nagydij/"}]}');
--> statement-breakpoint
INSERT INTO `tudastar_kartya` (`id`, `kategoria`, `slug`, `tipus`, `nev`, `rovidites`, `osszefoglalo`, `honlap`, `sorrend`, `tartalom`) VALUES ('2ae0c5c2-1c25-17c8-9ee2-af508afc91cb', 'vallalatok', 'agazati-szovetsegek', 'lista', 'Ágazati és vállalkozói szövetségek', NULL, 'Az innovációban érintett iparági és vállalkozói érdekképviseletek: egy szektor hazai szereplőinek megismeréséhez és a szakmai rendezvényekhez ezek a kapcsolatfelvétel első pontjai. A kockázatitőke-iparág szervezete (HVCA) a 7. kategóriában szerepel.', NULL, 3, '{"sorok":[{"nev":"Magyar Innovációs Szövetség (MISZ)","url":"https://innovacio.hu/","megjegyzes":"A Magyar Innovációs Nagydíj gazdája (először 1993-ban hirdették meg); nagyvállalati, kkv- és startup-szolgáltatások. 1116 Budapest, Fehérvári út 108–112."},{"nev":"IVSZ – Digitális Vállalkozások Szövetsége","url":"https://ivsz.hu/","megjegyzes":"Az informatikai, távközlési és digitalizálódó ágazatok szereplőinek közös szakmai és érdekképviseleti platformja, szakmai munkacsoportokkal."},{"nev":"Munkaadók és Gyáriparosok Országos Szövetsége (MGYOSZ)","url":"https://www.mgyosz.hu/","megjegyzes":"Saját közlése szerint az ország legnagyobb munkaadói érdekképviselete; a BusinessEurope tagja."},{"nev":"Vállalkozók és Munkáltatók Országos Szövetsége (VOSZ)","url":"https://www.vosz.hu/hu","megjegyzes":"Vállalkozói érdekképviselet, finanszírozási és szakmai tanácsadás (ESG, energetika, digitalizáció), vállalkozói rendezvények."},{"nev":"Innovatív Gyógyszergyártók Egyesülete (AIPM)","url":"https://aipm.hu/","megjegyzes":"1992-ben alapították; 26 kutatás-fejlesztés-orientált gyógyszeripari vállalatot tömörít Magyarországon."},{"nev":"Magyar Elektrotechnikai Egyesület (MEE)","url":"https://www.mee.hu/","megjegyzes":"Villamosipari szakmai egyesület: oktatás, kiadványok, rendezvények, szakértői munkák koordinálása."},{"nev":"Startup Hungary","url":"https://www.startuphungary.io/","megjegyzes":"A hazai startup-közösséget összefogó szervezet: válogatott tartalmak, kutatások és rendezvények."}],"linkek":[]}');
--> statement-breakpoint
INSERT INTO `tudastar_kartya` (`id`, `kategoria`, `slug`, `tipus`, `nev`, `rovidites`, `osszefoglalo`, `honlap`, `sorrend`, `tartalom`) VALUES ('21d1d418-c1d8-d518-5d36-736ff7fc0bdb', 'vallalatok', 'kamarak', 'lista', 'Kamarák és kétoldalú üzleti kamarák', NULL, 'A gazdasági kamarák a hazai vállalatok széles körét érik el; a területi kereskedelmi és iparkamarák közül több az Enterprise Europe Network magyar partnere (lásd a 9. kategóriát). A kétoldalú üzleti kamarák a külföldi és a magyar vállalatok közötti kapcsolatépítés első címei.', NULL, 4, '{"sorok":[{"nev":"Magyar Kereskedelmi és Iparkamara (MKIK)","url":"https://mkik.hu/","megjegyzes":"Területi kamarák hálózata; külgazdasági tagozatok (pl. ASEAN, Afrika, Közel-Kelet és Észak-Afrika, ICC Magyar Tagozat, kétoldalú tagozatok). KKV Innovációs Díj (2025)."},{"nev":"Budapesti Kereskedelmi és Iparkamara (BKIK)","url":"https://bkik.hu/","megjegyzes":"A fővárosi vállalkozások kamarája; szakmai fórumok és vállalkozói rendezvények."},{"nev":"Nemzeti Agrárgazdasági Kamara (NAK)","url":"https://www.nak.hu/","megjegyzes":"Az agrár- és élelmiszer-gazdaság kamarája; agrárszakmai és élelmiszer-biztonsági programok."},{"nev":"Magyar Mérnöki Kamara (MMK)","url":"https://www.mmk.hu/","megjegyzes":"A mérnökök szakmai kamarája; jogosultsági és beszámoló vizsgák."},{"nev":"AmCham Hungary","url":"https://www.amcham.hu/","megjegyzes":"Saját közlése szerint Közép-Kelet-Európa egyik legnagyobb amerikai kereskedelmi kamarája; amerikai, nemzetközi és hazai vállalatok érdekképviselete."},{"nev":"Német-Magyar Ipari és Kereskedelmi Kamara (AHK Ungarn)","url":"https://www.ahkungarn.hu/hu","megjegyzes":"Német–magyar üzleti fórumok; témái között a magyar kkv-k bekapcsolása a globális ellátási láncokba és a digitalizáció."},{"nev":"CCI France Hongrie","url":"https://www.ccifrance-hongrie.org/","megjegyzes":"Budapesti székhelyű francia–magyar kamara; kétkultúrájú csapattal segíti a francia vállalatok magyarországi projektjeit (export, import, cégalapítás)."},{"nev":"British Chamber of Commerce in Hungary (BCCH)","url":"https://bcch.com/","megjegyzes":"Brit–magyar üzleti kamara; 2026-ban ünnepli magyarországi működésének 35. évét."},{"nev":"Swisscham Hungary","url":"https://swisscham.hu/","megjegyzes":"A svájci és magyar vállalatok gazdasági és kereskedelmi együttműködését segítő kamara: üzleti információ, partnerkeresés, rendezvények."}],"linkek":[]}');
--> statement-breakpoint
INSERT INTO `tudastar_kartya` (`id`, `kategoria`, `slug`, `tipus`, `nev`, `rovidites`, `osszefoglalo`, `honlap`, `sorrend`, `tartalom`) VALUES ('e674c745-12b2-9fc7-2698-c6a024799dc7', 'vallalatok', 'akkreditalt-klaszterek', 'lista', 'Akkreditált klaszterek', NULL, 'A Klaszterfejlesztési stratégia 2023–2030 szerint a Miniszterelnökség nyilvántartásában 2023. január 1-jén 26 akkreditált klaszter szerepelt, összesen 1028 taggal; a legtöbb az IKT-, a gépipari és az egészségipari ágazatban működik. A lista ezt a kimutatást közli székhellyel, ágazattal és – ahol ellenőrizhető volt – a klaszter honlapjával; az akkreditációk mai állapotát a klaszternél érdemes ellenőrizni.', NULL, 5, '{"sorok":[{"nev":"Alliance Informatikai és Innovációs Klaszter","url":"","megjegyzes":"Budapest · IKT"},{"nev":"ArchEnerg Nemzetközi Megújuló Energetikai és Építőipari Innovációs Klaszter","url":"https://www.archenerg.eu/","megjegyzes":"Szeged · környezet és energia"},{"nev":"Biotechnológiai Innovációs Bázis Klaszter","url":"","megjegyzes":"Pécs · egészségipar"},{"nev":"Dél-Dunántúli Gépipari Klaszter","url":"","megjegyzes":"Pécs · gépipar"},{"nev":"Észak-magyarországi Autóipari Klaszter (NOHAC)","url":"https://nohac.hu/","megjegyzes":"Miskolc · gépipar"},{"nev":"Észak-Magyarországi Informatikai Klaszter","url":"","megjegyzes":"Miskolc · IKT"},{"nev":"Hírös Beszállítói Klaszter","url":"","megjegyzes":"Kecskemét · gépipar"},{"nev":"iFood Élelmiszer Klaszter","url":"","megjegyzes":"Kaposvár · élelmiszeripar"},{"nev":"Információmenedzsment Innovációs Klaszter","url":"","megjegyzes":"Pécs · IKT"},{"nev":"Infostrada Klaszter","url":"","megjegyzes":"Pécs · IKT"},{"nev":"Innoskart IKT Klaszter","url":"","megjegyzes":"Székesfehérvár · IKT"},{"nev":"Magyar Medikai Gyártók és Szolgáltatók Klaszter","url":"","megjegyzes":"Budapest · egészségipar"},{"nev":"MIRBEST Közép-európai Gasztroinnovációs Klaszter","url":"","megjegyzes":"Biatorbágy · élelmiszeripar"},{"nev":"Magyar Sport- és Életmódfejlesztő Klaszter","url":"","megjegyzes":"Debrecen · egészségipar"},{"nev":"Omnipack Első Magyar Csomagolástechnikai Klaszter","url":"","megjegyzes":"Budapest · csomagolás"},{"nev":"ÖKOPolisz Klaszter","url":"","megjegyzes":"Veszprém · környezet és energia"},{"nev":"Pannon Fa- és Bútoripari Klaszter","url":"","megjegyzes":"Sopron · fa- és bútoripar"},{"nev":"Pharmapolis Debrecen Innovatív Gyógyszeripari Klaszter","url":"https://pharmapolis.unideb.hu/","megjegyzes":"Debrecen · egészségipar"},{"nev":"Pharmapolis Innovatív Élelmiszeripari Klaszter","url":"","megjegyzes":"Debrecen · élelmiszeripar"},{"nev":"Professio Fémipari és Szakképzési Klaszter","url":"","megjegyzes":"Győr · gépipar"},{"nev":"Rendszertudományi Innovációs Klaszter","url":"","megjegyzes":"Balatonfüred · IKT"},{"nev":"Sárrét Metál Klaszter","url":"","megjegyzes":"Szeghalom · gépipar"},{"nev":"Szilícium Mező Regionális Informatikai Klaszter","url":"","megjegyzes":"Debrecen · IKT"},{"nev":"Szoftveripari Innovációs Pólus Klaszter","url":"","megjegyzes":"Szeged · IKT"},{"nev":"Termál-Egészségipari Klaszter","url":"","megjegyzes":"Debrecen · egészségipar"},{"nev":"Víz- és Környezetgazdálkodási Klaszter","url":"","megjegyzes":"Szécsény · környezet és energia"}],"linkek":[{"felirat":"Klaszterfejlesztési stratégia 2023–2030 (PDF)","url":"https://cdn.kormany.hu/uploads/document/8/85/859/859655813b0908ec753dfb28e0365d96b5a3d5e0.pdf"}]}');
--> statement-breakpoint
INSERT INTO `tudastar_kartya` (`id`, `kategoria`, `slug`, `tipus`, `nev`, `rovidites`, `osszefoglalo`, `honlap`, `sorrend`, `tartalom`) VALUES ('6ba21b9e-0798-3341-198d-3da88cd5f7a7', 'nemzetkozi-programok', 'horizont-europa', 'intezmeny', 'Horizont Európa – magyar nemzeti kapcsolattartó pont (NKFIH)', 'HE NCP', 'Az EU 2021–2027 közötti, 95,5 milliárd eurós kutatási és innovációs keretprogramjának magyar kapcsolódási pontja az NKFI Hivatal Horizont Európa nemzeti kapcsolattartó (NCP) csapata: ingyenes tájékoztatást, pályázati tanácsadást és partnerkeresési segítséget ad. Az Európai Kutatási Tanács (ERC) nemzeti kapcsolattartói a Magyar Tudományos Akadémián dolgoznak. 2026. október 14. óta a modellváltó egyetemek is ismét kedvezményezettek és konzorciumvezetők lehetnek.', 'https://horizonteuropa.nkfih.gov.hu/', 1, '{"profil":"A Horizont Európa négy fő részből áll: Kiváló tudomány (Európai Kutatási Tanács, Marie Skłodowska-Curie akciók, kutatási infrastruktúrák); Globális kihívások és európai ipari versenyképesség (hat tematikus klaszter, missziók, Közös Kutatóközpont); Innovatív Európa (Európai Innovációs Tanács, európai innovációs ökoszisztémák, EIT); valamint a részvétel szélesítése és az Európai Kutatási Térség megerősítése.\n\nMagyarországon a nemzeti kapcsolattartók hálózatát az NKFI Hivatal működteti. A magyar pályázókat külön portál, heti Horizont Európa hírlevél és a HorizontPéntek10 webinársorozat tájékoztatja; a külföldi partner ugyanitt találja a magyar pályázók értékajánlatait és a témánkénti kapcsolattartókat.","tevekenyseg":"- információterjesztés: információs napok, tájékoztatók az aktuális felhívásokról és újdonságokról\n- pályázati tanácsadás: telefonos, e-mailes és személyes konzultáció, tréningek, workshopok\n- közreműködés a projektpartnerek keresésében: a hazai pályázók értékajánlatainak (value offer) körözése a nemzetközi NCP-hálózatokban és a heti hírlevélben\n- jogi és pénzügyi NCP (csak e-mailes megkeresésre)\n- tájékoztatás a társfinanszírozott programok (európai partnerségek, ERA-NET-ek) nemzetközi felhívásairól","kapcsolat":{"email":"ncp@nkfih.gov.hu","telefon":"+36 70 680 6421","cim":"1077 Budapest, Kéthly Anna tér 1."},"szakaszok":[{"cim":"A korlátozás megszűnése (2026. október)","szoveg":"Az EU Általános Ügyek Tanácsa 2026. október 13-án lezárta a Magyarország elleni feltételességi eljárást. Ezzel a 2022 decemberében hatályba lépett (EU) 2022/2506 tanácsi végrehajtási határozat 2026. október 14-én hatályát vesztette: a közérdekű vagyonkezelő alapítványok és az általuk fenntartott intézmények – köztük a modellváltó egyetemek – ismét kedvezményezettként és konzorciumvezetőként is részt vehetnek a közvetlen uniós finanszírozású programokban, így a Horizont Európában és az Erasmus+-ban.\n\nFutó projektben a konzorcium kérheti a támogatási szerződés módosítását: a magyar szervezet visszamenőleges hatály nélkül, a megszüntető határozat hatálybalépésétől válhat kedvezményezetté; a maximális uniós támogatás nem nő, költségeit a meglévő keret átcsoportosításából kell fedezni.\n\nAki 2026. október 14. előtt társult partnerként pályázott, továbbra is a Kormányzati Önerő Alapból igényelhet támogatást; a Tudományos és Technológiai Minisztérium tervei szerint a konstrukció 2027-ben is elérhető lesz."},{"cim":"Kormányzati Önerő Alap","szoveg":"Az (EU) 2022/2506 tanácsi végrehajtási határozat hatálya alá tartozott intézményeknek pótolja az uniós támogatást: a nyertes Horizont Európa-, Erasmus+- vagy más uniós KFI- és oktatási projektben tervezett költség 100%-áig nyújt támogatást, egyösszegű előleggel. A 2026-os felhívásra (2026-1.2.1-KÖA) 2026. október 30-ig lehetett kérelmet benyújtani (lezárult); új felhívás csak a 2027. évi központi költségvetési törvény és az NKFI Alap 2027. évi programstratégiájának elfogadása után jelenhet meg."},{"cim":"Európai partnerségek és ERA-NET-ek","szoveg":"A közös finanszírozású európai partnerségek felhívásai nemzetközi pályázatok, de a nyertes magyar résztvevőket az NKFI Hivatal finanszírozza (HE_PARTNERSÉG és ERA_NET hazai felhívások, szakmai értékelés nélkül, csak formai és jogosultsági ellenőrzéssel; a 2024-ben meghirdetett két felhívás beadása 2026. október 30-án lezárult). 2026-ban 19 konstrukcióban összesen 2,7 milliárd forint jut a magyar pályázók konzorciumi részvételére; 2021 óta 68 magyar intézmény csaknem 6,8 milliárd forint támogatást kapott. A partnerségek listája külön kártyán."},{"cim":"Partnerkeresés","szoveg":"Az NCP-csapat segít tömör értékajánlatot (value offer) összeállítani, és körözi azt a nemzetközi NCP-hálózatokban; a beérkező partnerkereső igényeket a heti hírlevél is közli. A II. pillér személyes partnerkereső rendezvényeire való kiutazást a WIDERA Travel Grants pályázat fejenként 1000 euróval támogatja (beadás 2027. január 31-ig)."},{"cim":"Nemzeti kapcsolattartók","szoveg":"Általános elérhetőség: ncp@nkfih.gov.hu, +36 70 680 6421; a jogi és pénzügyi NCP csak e-mailben fogad megkeresést. Az Európai Kutatási Tanács (ERC) nemzeti kapcsolattartói a Magyar Tudományos Akadémián dolgoznak, a többi téma kapcsolattartói az NKFI Hivatalban.\n\nA témánkénti nemzeti kapcsolattartókat a 2. kategória „Horizont Európa nemzeti kapcsolattartók” listája sorolja fel."}],"programok":[{"nev":"HU-rizont Nemzetközi Kiválósági Kutatási Együttműködési Program","url":"https://nkfih.gov.hu/hurizont","leiras":"Magyar vezetésű nemzetközi kutatási projektek vezető külföldi egyetemekkel; 2024-ben 30 projekt, összesen 11,8 Mrd Ft támogatás. A 2026-os felhívás (2026-4.1.2-HU-RIZONT, 8 Mrd Ft) beadása május 29-én lezárult."},{"nev":"Kormányzati Önerő Alap (2026-1.2.1-KÖA)","url":"https://horizonteuropa.nkfih.gov.hu/aktualis-felhivasok/kormanyzati-onero-alap","leiras":"Uniós projekttámogatást pótló hazai forrás a korlátozás alá tartozott intézményeknek, a tervezett költség 100%-áig; a 2026-os beadás október 30-án lezárult."},{"nev":"HorizontPéntek10 webinársorozat","url":"https://horizonteuropa.nkfih.gov.hu/tajekoztato-anyagok/horizontpentek10","leiras":"Az NCP-csapat heti tájékoztató rendezvénysorozata az aktuális felhívásokról."}],"linkek":[{"felirat":"A nemzeti kapcsolattartók oldala (NKFIH)","url":"https://nkfih.gov.hu/hivatalrol/nemzetkozi-kapcsolatok/horizont-europa/nemzeti-kapcsolattarto-pontok"},{"felirat":"Magyar szereplők részvétele (2026. október)","url":"https://horizonteuropa.nkfih.gov.hu/magyar-szereplok-reszvetele"},{"felirat":"Partnerkeresés","url":"https://horizonteuropa.nkfih.gov.hu/hogyan-palyazzak/partnerkereses"},{"felirat":"Horizon Europe (Európai Bizottság)","url":"https://research-and-innovation.ec.europa.eu/funding/funding-opportunities/funding-programmes-and-open-calls/horizon-europe_en"}]}');
--> statement-breakpoint
INSERT INTO `tudastar_kartya` (`id`, `kategoria`, `slug`, `tipus`, `nev`, `rovidites`, `osszefoglalo`, `honlap`, `sorrend`, `tartalom`) VALUES ('9afe842f-94a5-d7a1-a1f2-b93b74b0e4e5', 'nemzetkozi-programok', 'eit', 'intezmeny', 'Európai Innovációs és Technológiai Intézet', 'EIT', 'Az EU innovációs testülete, a Horizont Európa „Innovatív Európa” pillérének része, amelynek fő irodája Budapesten van. Tíz tudás- és innovációs közösséget (KIC) támogat, amelyek vezető vállalatokat, kutatóhelyeket és egyetemeket kapcsolnak össze; magyar nemzeti kapcsolattartója az NKFI Hivatal Horizont Európa NCP-csapata.', 'https://www.eit.europa.eu/', 2, '{"profil":"Az EIT 2010 óta működik Magyarországon; brüsszeli összekötő irodája az uniós intézményekkel és a kutatási-innovációs szereplőkkel tartja a kapcsolatot. Az általa támogatott közösségek vállalkozói képzést, üzletiinkubációs és -gyorsítási szolgáltatásokat, valamint innovációvezérelt kutatási projekteket kínálnak.\n\nMagyarország jogosult az EIT Regionális Innovációs Programjára (RIS), amely a régiók közötti innovációs különbségek csökkentését szolgálja, és Magyarországon is EIT Community hub ad egyablakos hozzáférést a közösségek lehetőségeihez.","tevekenyseg":"- vállalkozói oktatás\n- üzletiinkubáció és -gyorsítás (business creation)\n- innovációvezérelt kutatás\n- EIT-díjak (EIT Awards)\n- Regionális Innovációs Program (RIS) és a helyi hubok hálózata","kapcsolat":{"email":"","telefon":"+36 1 481 9300","cim":"1117 Budapest, Neumann János utca, Infopark 1, E épület"},"szakaszok":[{"cim":"Magyar kapcsolódás","szoveg":"- 2025. december 2-án az EIT és az akkori Kulturális és Innovációs Minisztérium megújította 2019-es együttműködési megállapodását; eszerint Magyarország 2026-tól csatlakozik az EIT Regional Innovation Booster kísérleti programjához, amely mérsékelt és szerény innovátor országok startupjait és scale-upjait támogatja.\n- Az EIT közlése szerint 2021 és 2024 között 183 magyar startup kapott EIT-támogatást, és legalább 24 millió euró befektetést vonzott.\n- Budapesten 2021 szeptembere óta EIT Community Hub működik az Infoparkban (az induláskor az EIT Health, az EIT Climate-KIC, az EIT RawMaterials és az EIT Urban Mobility részvételével, az EIT Health koordinálásával).\n- Hazai tanácsadás: az NKFI Hivatal Horizont Európa NCP-csapata (III. pillér: EIC, európai innovációs ökoszisztémák, EIT)."}],"programok":[{"nev":"Climate KIC","url":"https://www.eit.europa.eu/our-communities/eit-climate-kic","leiras":"Éghajlatváltozás (korábban EIT Climate-KIC)."},{"nev":"28DIGITAL","url":"https://www.eit.europa.eu/our-communities/28digital","leiras":"Digitalizáció (korábban EIT Digital)."},{"nev":"InnoEnergy","url":"https://www.eit.europa.eu/our-communities/eit-innoenergy","leiras":"Fenntartható energia (korábban EIT InnoEnergy)."},{"nev":"EIT Health","url":"https://www.eit.europa.eu/our-communities/eit-health","leiras":"Egészségügyi innováció."},{"nev":"EIT RawMaterials","url":"https://www.eit.europa.eu/our-communities/eit-rawmaterials","leiras":"Nyersanyagok."},{"nev":"EIT Food","url":"https://www.eit.europa.eu/our-communities/eit-food","leiras":"Az élelmiszer jövője."},{"nev":"EIT Manufacturing","url":"https://www.eit.europa.eu/our-communities/eit-manufacturing","leiras":"Hozzáadott értéket teremtő feldolgozóipar."},{"nev":"EIT Urban Mobility","url":"https://www.eit.europa.eu/our-communities/eit-urban-mobility","leiras":"Városi mobilitás."},{"nev":"EIT Culture & Creativity","url":"https://www.eit.europa.eu/eit-community/eit-culture-creativity","leiras":"Kulturális és kreatív ágazatok."},{"nev":"EIT Water","url":"https://www.eit.europa.eu/our-communities/eit-water","leiras":"Víz-reziliencia."},{"nev":"EIT Regionális Innovációs Program (RIS)","url":"https://www.eit.europa.eu/activities/eit-regional-innovation-scheme-ris-closing-innovation-divide-europe","leiras":"2014 óta a regionális innovációs különbségek csökkentésének fő eszköze; Magyarország jogosult, helyi hubokkal."}],"linkek":[{"felirat":"Kapcsolat (EIT)","url":"https://www.eit.europa.eu/about-us/contact-us"},{"felirat":"Magyarország és a Regional Innovation Booster (2025. december, PDF)","url":"https://www.eit.europa.eu/sites/default/files/2025-12/Hungary%20MoU%20Signature_PR_0.pdf"},{"felirat":"EIT at a glance","url":"https://www.eit.europa.eu/about-us/eit-glance"}]}');
--> statement-breakpoint
INSERT INTO `tudastar_kartya` (`id`, `kategoria`, `slug`, `tipus`, `nev`, `rovidites`, `osszefoglalo`, `honlap`, `sorrend`, `tartalom`) VALUES ('ec9254cf-e3fb-25f5-e954-ec05db6551dc', 'nemzetkozi-programok', 'eic-eureka-eurostars', 'lista', 'Vállalati innovációs programok: EIC, EUREKA, Eurostars', NULL, 'A piacközeli, vállalati K+F-et támogató európai programok magyar kapcsolódási pontjai. Az EIC-hez a Horizont Európa NCP-csapata ad tanácsot; az EUREKA és a Eurostars hazai koordinációja és a nyertes magyar résztvevők hazai támogatása az NKFI Hivatalnál van. A hazai társfinanszírozó felhívásokat a 2. kategória is sorolja.', NULL, 3, '{"sorok":[{"nev":"Európai Innovációs Tanács (EIC)","url":"https://eic.ec.europa.eu/index_en","megjegyzes":"Horizont Európa III. pillér: Pathfinder, Transition, Accelerator, STEP Scale Up és az EIC Fund tőkebefektetései. Magyar NCP: NKFI Hivatal."},{"nev":"EUREKA","url":"https://nkfih.gov.hu/hivatalrol/nemzetkozi-szervezetek/szakmai-egyuttmukodesek/europai-piacorientalt","megjegyzes":"1985-ben indult, témakötöttség nélküli, piacorientált K+F-együttműködés, Magyarország 1992 óta tag; hazai koordinátor: NKFI Hivatal."},{"nev":"Eurostars","url":"https://horizonteuropa.nkfih.gov.hu/horizont-europa-program/partnersegek/partnerseg-attekintes","megjegyzes":"Az EUREKA-tagállamok és a Bizottság közös programja K+F-et végző kkv-k nemzetközi projektjeire; hazai finanszírozó az NKFIH (2026: évi 1 M EUR)."},{"nev":"EUREKA hálózati projektek – hazai támogatás (2025-1.2.2-EUREKA)","url":"https://nkfih.gov.hu/palyazoknak/nkfi-alap/eureka-programban-valo-magyar-reszvetel-tamogatasa-2025-122-eureka/palyazati-felhivas","megjegyzes":"Legalább két EUREKA-ország független résztvevőivel induló, 2–3 éves piacközeli projektek magyar résztvevőinek: 20–70 M Ft, beadás 2027. október 15-ig."}],"linkek":[{"felirat":"Horizont Európa NCP-k (NKFIH)","url":"https://nkfih.gov.hu/hivatalrol/nemzetkozi-kapcsolatok/horizont-europa/nemzeti-kapcsolattarto-pontok"}]}');
--> statement-breakpoint
INSERT INTO `tudastar_kartya` (`id`, `kategoria`, `slug`, `tipus`, `nev`, `rovidites`, `osszefoglalo`, `honlap`, `sorrend`, `tartalom`) VALUES ('3b561fcb-ff3c-46e0-aaf8-a7b8b8642737', 'nemzetkozi-programok', 'europai-halozatok', 'lista', 'Európai hálózatok: COST, EURAXESS, Enterprise Europe Network', NULL, 'Kutatói és vállalati hálózatok magyar pontjai. A COST nemzeti koordinátora az NKFI Hivatalban dolgozik; az EURAXESS Hungary nemzeti koordinátora a portál szerint 2008 óta a Bay Zoltán Alkalmazott Kutatási Közhasznú Nonprofit Kft., 14 EURAXESS-központtal; az Enterprise Europe Network magyar helyi kapcsolattartói a HEPA, területi kereskedelmi és iparkamarák és vállalkozásfejlesztési alapítványok.', NULL, 4, '{"sorok":[{"nev":"COST – Európai Tudományos és Technológiai Együttműködés","url":"https://www.cost.eu/about/members/hungary/","megjegyzes":"Alulról szerveződő kutatói hálózatok (COST-akciók); Magyarország 1991 óta tag. A COST nemzeti koordinátora az NKFI Hivatalban dolgozik."},{"nev":"Csatlakozás COST-akcióhoz","url":"https://nkfih.gov.hu/hivatalrol/nemzetkozi-szervezetek/szakmai-egyuttmukodesek/europai-egyuttmukodes","megjegyzes":"Az akcióvezetővel (Action Chair) való egyeztetés után a csatlakozási nyilatkozatot a COST nemzeti koordinátornak kell megküldeni."},{"nev":"EURAXESS Hungary","url":"https://www.euraxess.hu/","megjegyzes":"Ingyenes információ és személyes segítség a Magyarországra érkező kutatóknak és családjuknak: állások, vízum, letelepedés."},{"nev":"EURAXESS Hungary-hálózat","url":"https://www.euraxess.hu/hungary/hungary-network","megjegyzes":"Nemzeti koordinátor (Bridgehead): Bay Zoltán Alkalmazott Kutatási Közhasznú Nonprofit Kft.; 14 EURAXESS-központ egyetemeken és más intézményekben; euraxess@bayzoltan.hu."},{"nev":"EEN – HEPA Magyar Exportfejlesztési Ügynökség (Budapest)","url":"","megjegyzes":"1027 Budapest, Kacsa u. 15–23.; eeninfo@hepa.hu"},{"nev":"EEN – HEPA Magyar Exportfejlesztési Ügynökség (Eger)","url":"","megjegyzes":"3300 Eger, Klapka György u. 9.; eeneger@hepa.hu"},{"nev":"EEN – Hajdú-Bihar Vármegyei Kereskedelmi és Iparkamara (Debrecen)","url":"","megjegyzes":"4025 Debrecen, Vörösmarty u. 13–15.; hbkik@hbkik.hu"},{"nev":"EEN – Győr-Moson-Sopron Vármegyei Kereskedelmi és Iparkamara (Győr)","url":"","megjegyzes":"9021 Győr, Szent István u. 10/a; een@gymsmkik.hu"},{"nev":"EEN – PRIMOM Alapítvány (Nyíregyháza)","url":"","megjegyzes":"Szabolcs-Szatmár-Bereg vármegyei vállalkozásélénkítő alapítvány; 4400 Nyíregyháza, Luther u. 16.; een@primom.hu"},{"nev":"EEN – Pécs-Baranyai Kereskedelmi és Iparkamara (Pécs)","url":"","megjegyzes":"7625 Pécs, Majorossy Imre u. 36.; een@pbkik.hu"},{"nev":"EEN – Csongrád-Csanád Vármegyei Kereskedelmi és Iparkamara (Szeged)","url":"","megjegyzes":"6721 Szeged, Párizsi krt. 8–12.; eenszeged@cskik.hu"},{"nev":"EEN – Fejér Vármegyei Kereskedelmi és Iparkamara (Székesfehérvár)","url":"","megjegyzes":"8000 Székesfehérvár, Hosszúsétatér 4–6.; fmkik@fmkik.hu"},{"nev":"EEN – Zala Megyei Vállalkozásfejlesztési Alapítvány (Zalaegerszeg)","url":"","megjegyzes":"8900 Zalaegerszeg, Köztársaság útja 17.; een@zmva.hu"}],"linkek":[{"felirat":"Enterprise Europe Network: helyi kapcsolattartók Magyarországon","url":"https://een.ec.europa.eu/local-contact-points/hu"}]}');
--> statement-breakpoint
INSERT INTO `tudastar_kartya` (`id`, `kategoria`, `slug`, `tipus`, `nev`, `rovidites`, `osszefoglalo`, `honlap`, `sorrend`, `tartalom`) VALUES ('d819480a-1874-3565-eb1d-18bf7063f3c6', 'nemzetkozi-programok', 'ketoldalu-tet', 'lista', 'Kétoldalú TéT-megállapodások és -pályázatok', NULL, 'Az NKFIH kimutatása szerint Magyarországnak 36 kormányközi és 10 intézményközi tudományos és technológiai (TéT) együttműködési megállapodása van. A kormányközi egyezmények és a kétoldalú munkatervek előkészítése, végrehajtása, valamint a vegyes bizottsági képviselet a Tudományos és Technológiai Minisztérium TéT-attasé hálózatot koordináló főosztályának feladata; a közös pályázatokat az NKFI Hivatal írja ki. A lista az NKFIH 2018-as állapotú kimutatása (zárójelben a megállapodás éve), elöl a 2026-os felhívással.', NULL, 5, '{"sorok":[{"nev":"Kétoldalú TéT-pályázat 2026 (2026-1.2.2-TÉT)","url":"https://nkfih.gov.hu/palyazoknak/nkfi-alap/ketoldalu-tudomanyos-technologiai-egyuttmukodes-tamogatasa-2026-112-tet","megjegyzes":"Meghirdetve 2026. július 3., beadás július 31-ig (lezárult): közös pályázat a kínai (120 M Ft) és a francia (30 M Ft) relációban, kutatói mobilitás és szakembercsere támogatására."},{"nev":"Argentína","url":"","megjegyzes":"Kormányközi megállapodás (1999)"},{"nev":"Ausztria","url":"","megjegyzes":"Kormányközi megállapodás (1969)"},{"nev":"Brazília","url":"","megjegyzes":"Kormányközi megállapodás (1986)"},{"nev":"Csehország","url":"","megjegyzes":"Kormányközi megállapodás (2001)"},{"nev":"Chile","url":"","megjegyzes":"Kormányközi megállapodás (2005)"},{"nev":"Dél-afrikai Köztársaság","url":"","megjegyzes":"Kormányközi megállapodás (1997)"},{"nev":"Egyiptom","url":"","megjegyzes":"Kormányközi megállapodás (1996)"},{"nev":"Finnország","url":"","megjegyzes":"Kormányközi megállapodás (1993)"},{"nev":"Flandria (Belgium)","url":"","megjegyzes":"Kormányközi megállapodás (1994)"},{"nev":"Franciaország","url":"","megjegyzes":"Kormányközi megállapodás (1966)"},{"nev":"Görögország","url":"","megjegyzes":"Kormányközi megállapodás (1979)"},{"nev":"Horvátország","url":"","megjegyzes":"Kormányközi megállapodás (2002)"},{"nev":"India","url":"","megjegyzes":"Kormányközi megállapodás (1992)"},{"nev":"Izrael","url":"","megjegyzes":"Kormányközi megállapodás (1991)"},{"nev":"Japán","url":"","megjegyzes":"Kormányközi megállapodás (1979)"},{"nev":"Kína","url":"","megjegyzes":"Kormányközi megállapodás (2002)"},{"nev":"Koreai Köztársaság","url":"","megjegyzes":"Kormányközi megállapodás (1989); intézményközi megállapodások is (2014)"},{"nev":"Lengyelország","url":"","megjegyzes":"Kormányközi megállapodás (1996)"},{"nev":"Malajzia","url":"","megjegyzes":"Kormányközi megállapodás (1997)"},{"nev":"Mexikó","url":"","megjegyzes":"Kormányközi megállapodás (1992)"},{"nev":"Montenegró","url":"","megjegyzes":"Kormányközi megállapodás (2012)"},{"nev":"Nagy-Britannia","url":"","megjegyzes":"Kormányközi megállapodás (1987)"},{"nev":"Németország","url":"","megjegyzes":"Kormányközi megállapodás (1987)"},{"nev":"Olaszország","url":"","megjegyzes":"Kormányközi megállapodás (2006)"},{"nev":"Orosz Föderáció","url":"","megjegyzes":"Kormányközi megállapodás (1993)"},{"nev":"Portugália","url":"","megjegyzes":"Kormányközi megállapodás (1977)"},{"nev":"Románia","url":"","megjegyzes":"Kormányközi megállapodás (1999)"},{"nev":"Spanyolország","url":"","megjegyzes":"Kormányközi megállapodás (1979)"},{"nev":"Szerbia","url":"","megjegyzes":"Kormányközi megállapodás (2004)"},{"nev":"Szlovákia","url":"","megjegyzes":"Kormányközi megállapodás (2002)"},{"nev":"Szlovénia","url":"","megjegyzes":"Kormányközi megállapodás (1994)"},{"nev":"Thaiföld","url":"","megjegyzes":"Kormányközi megállapodás (1999)"},{"nev":"Törökország","url":"","megjegyzes":"Kormányközi megállapodás (1989)"},{"nev":"Ukrajna","url":"","megjegyzes":"Kormányközi megállapodás (1995)"},{"nev":"USA","url":"","megjegyzes":"Kormányközi megállapodás (2010)"},{"nev":"Vietnam","url":"","megjegyzes":"Kormányközi megállapodás (2005)"},{"nev":"Intézményközi megállapodások","url":"","megjegyzes":"Azerbajdzsán, Ecuador, Fehéroroszország, Irán, Kazahsztán, Koreai Köztársaság, Kuvait, Marokkó, Szaúd-Arábia, Vallónia (Belgium)."}],"linkek":[{"felirat":"Szerződéses országok (NKFIH)","url":"https://nkfih.gov.hu/hivatalrol/ketoldalu-kapcsolatok/szerzodeses-orszagok"},{"felirat":"Kétoldalú TéT-kapcsolatok (NKFIH)","url":"https://nkfih.gov.hu/hivatalrol/ketoldalu-kapcsolatok/ketoldalu-tudomanyos"}]}');
--> statement-breakpoint
INSERT INTO `tudastar_kartya` (`id`, `kategoria`, `slug`, `tipus`, `nev`, `rovidites`, `osszefoglalo`, `honlap`, `sorrend`, `tartalom`) VALUES ('7c4d6eda-3eda-5c27-d1a0-9cb80dab4292', 'nemzetkozi-programok', 'kutatasi-infrastrukturak', 'lista', 'Nemzetközi kutatási infrastruktúrák – magyar tagságok', NULL, 'Magyarország nemzetközi kutatási infrastruktúrákban való tagságát az NKFI Hivatal finanszírozza; 2025-ben a tagdíjak összesen mintegy 16,3 milliárd forintot tettek ki. A tagság a hazai kutatóknak hozzáférést, a cégeknek beszállítói lehetőséget ad; az ELI ERIC-ben Magyarország fogadó országként vesz részt. A belépési évek az NKFIH kimutatásából valók, az ESA-tagság az ESA közléséből.', NULL, 6, '{"sorok":[{"nev":"CERN – Európai Részecskefizikai Laboratórium","url":"","megjegyzes":"Tag 1992 óta; magyar részvétel az LHC ALICE és CMS kísérletében is."},{"nev":"ELI ERIC – Extrém Fényforrás/Szuperlézer Infrastruktúra","url":"","megjegyzes":"2010 óta; Magyarország fogadó országként vesz részt."},{"nev":"ESS ERIC – Európai Neutronkutató Központ (European Spallation Source)","url":"","megjegyzes":"2014 óta; a tagdíj 70%-a megrendelésként hazai beszállítókhoz jut vissza."},{"nev":"European XFEL – Európai Röntgen-Szabadelektron Lézer","url":"","megjegyzes":"2009 óta."},{"nev":"ESRF – Európai Szinkrotronsugárzási Intézet","url":"","megjegyzes":"2017 óta; a tagság szünetel (2025-ben nem volt tagdíj)."},{"nev":"CERIC ERIC – Közép-európai Kutatási Infrastruktúra-konzorcium","url":"","megjegyzes":"2016 óta; szinkrotron-, neutronnyalábos és mikroszkópos vizsgálatok."},{"nev":"EuPRAXIA – Európai Plazmakutatási Gyorsító","url":"","megjegyzes":"2021 óta; megvalósítás alatt álló, elosztott plazmagyorsító-infrastruktúra."},{"nev":"ITER – Nemzetközi Termonukleáris Kísérleti Reaktor","url":"","megjegyzes":"2007 óta, az EU/EURATOM-tagság révén."},{"nev":"ICOS ERIC – Integrált Szénmegfigyelő Rendszer","url":"","megjegyzes":"2022 óta; éghajlat- és légkörkutatás."},{"nev":"EMBL – Európai Molekuláris Biológiai Laboratórium","url":"","megjegyzes":"2017 óta."},{"nev":"ELIXIR – Európai Élettudományi Bioinformatikai Infrastruktúra","url":"","megjegyzes":"2017 óta; biológiai adatforrások létrehozása, fejlesztése és elérése."},{"nev":"EuBI ERIC – Euro-BioImaging","url":"","megjegyzes":"2016 óta; biológiai és orvosbiológiai képalkotó technológiák."},{"nev":"BBMRI ERIC – Biobankolási és Biomolekuláris Kutatási Infrastruktúra","url":"","megjegyzes":"2021 óta."},{"nev":"ICGEB – Nemzetközi Génsebészeti és Biotechnológiai Központ","url":"","megjegyzes":"1987 óta; évente pályázható kutatási támogatás (CRP) és PhD-, posztdoktori ösztöndíjak."},{"nev":"CESSDA ERIC – Európai Társadalomtudományi Adatarchívum Konzorcium","url":"","megjegyzes":"2017 óta."},{"nev":"CLARIN ERIC – Közös Nyelvtechnológiai Infrastruktúra","url":"","megjegyzes":"2016 óta."},{"nev":"E-RIHS – Európai Örökségtudományi Kutatási Infrastruktúra","url":"","megjegyzes":"2016 óta."},{"nev":"ESS ERIC – Európai Társadalmi Felmérés (European Social Survey)","url":"","megjegyzes":"2016 óta."},{"nev":"SHARE ERIC – Egészség, öregedés és nyugdíjazás felmérése Európában","url":"","megjegyzes":"2017 óta."},{"nev":"GUIDE – Felnövekvés a Digitális Európában (EuroCohort)","url":"","megjegyzes":"2021 óta."},{"nev":"ESA – Európai Űrügynökség","url":"https://www.esa.int/About_Us/Corporate_news/Hungary_becomes_ESA_s_22nd_Member_State","megjegyzes":"Magyarország 2015. november 4-én lett a 22. tagállam. Kormányzati képviselet: Tudományos és Technológiai Minisztérium (közreműködik az Űrpolitikai Főosztály)."}],"linkek":[{"felirat":"Nemzetközi kutatási infrastruktúrák: tagdíjak és haszon (NKFIH)","url":"https://nkfih.gov.hu/hivatalrol/nemzetkozi-szervezetek/kutatasi-infrastrukturak/nemzetkozi-kutatasi-infrastrukturak-attekintese"}]}');
--> statement-breakpoint
INSERT INTO `tudastar_kartya` (`id`, `kategoria`, `slug`, `tipus`, `nev`, `rovidites`, `osszefoglalo`, `honlap`, `sorrend`, `tartalom`) VALUES ('e674a49e-e9d4-62a7-11a0-0bca0e4a1717', 'nemzetkozi-programok', 'eu-partnersegek', 'lista', 'Európai partnerségek magyar finanszírozással', NULL, 'A közös finanszírozású európai partnerségek nemzetközi felhívásain nyertes magyar résztvevőket az NKFI Hivatal finanszírozza; az NKFIH szerint 2026-ban 19 konstrukcióban összesen 2,7 milliárd forint áll rendelkezésre. A közös finanszírozású partnerségek felhívásai a saját honlapjukon jelennek meg, nem a Funding & Tenders portálon. A lista az NKFIH táblázata: indulási év és éves magyar keret.', NULL, 7, '{"sorok":[{"nev":"Agriculture of Data (AgData)","url":"","megjegyzes":"2025 · 140 000 EUR/év · az európai mezőgazdaság digitális átalakulása"},{"nev":"Agroecology","url":"","megjegyzes":"2024 · 140 000 EUR/év · fenntartható, társadalmi innovációra építő mezőgazdasági termelés"},{"nev":"Biodiversa+","url":"","megjegyzes":"2021 · 250 000 EUR/év · biológiai sokféleség és ökoszisztémák"},{"nev":"Brain Health","url":"","megjegyzes":"2026 · 1 000 000 EUR/év · agykutatás, neurodegeneratív betegségek"},{"nev":"Clean Energy Transition Partnership (CETP)","url":"","megjegyzes":"2022 · 1 165 000 EUR/év · tiszta energiára való átállás"},{"nev":"Chips Joint Undertaking (Chips JU)","url":"","megjegyzes":"2023 · 2 300 000 EUR/év · európai félvezetőipar"},{"nev":"Driving Urban Transitions (DUT)","url":"","megjegyzes":"2022 · 1 000 000 EUR/év · fenntartható városfejlesztés"},{"nev":"ERA4Health","url":"","megjegyzes":"2022 · 100 000 EUR/év · preklinikai és klinikai orvosbiológiai kutatás"},{"nev":"European Rare Diseases Research Alliance (ERDERA)","url":"","megjegyzes":"2024 · 300 000 EUR/év · ritka betegségek"},{"nev":"Eurostars","url":"","megjegyzes":"2021 · 1 000 000 EUR/év · innovatív kkv-k által vezetett K+F-projektek"},{"nev":"EUREKA","url":"","megjegyzes":"2021 · 1 000 000 EUR/év · alulról építkező, piacorientált projektek"},{"nev":"Forests and Forestry for a Sustainable Future","url":"","megjegyzes":"2026 · 300 000 EUR/év · erdőalapú ágazatok"},{"nev":"M.ERA-NET","url":"","megjegyzes":"2021 · 300 000 EUR/év · anyag- és akkumulátor-technológiák"},{"nev":"Pandemic Preparedness (BE READY NOW)","url":"","megjegyzes":"2026 · 500 000 EUR/év · felkészülés a világjárványokra"},{"nev":"One-Health Antimicrobial Resistance (OH AMR)","url":"","megjegyzes":"2025 · 300 000 EUR/év · antimikrobiális rezisztencia"},{"nev":"European Partnership for Personalised Medicine (EP PerMed)","url":"","megjegyzes":"2023 · 500 000 EUR/év · személyre szabott orvoslás"},{"nev":"QuantERA III","url":"","megjegyzes":"2025 · 450 000 EUR/év · kvantumtechnológiai kutatás"},{"nev":"TRANSCAN","url":"","megjegyzes":"2026 · 300 000 EUR/év · rákkutatás"},{"nev":"Raw Materials for the Green and Digital Transition","url":"","megjegyzes":"2026 · 500 000 EUR/év · nem energetikai és nem mezőgazdasági nyersanyagok"},{"nev":"Water4All","url":"","megjegyzes":"2023 · 330 000 EUR/év · vízbiztonság"}],"linkek":[{"felirat":"Európai partnerségek – gyakorlati útmutató (NKFIH)","url":"https://horizonteuropa.nkfih.gov.hu/horizont-europa-program/partnersegek/partnerseg-attekintes"},{"felirat":"Partnerségi NCP-k (NKFIH)","url":"https://nkfih.gov.hu/hivatalrol/nemzetkozi-kapcsolatok/horizont-europa/nemzeti-kapcsolattarto-pontok"}]}');
