INSERT INTO `tudastar_kartya` (`id`, `kategoria`, `slug`, `tipus`, `nev`, `rovidites`, `osszefoglalo`, `honlap`, `sorrend`, `tartalom`) VALUES ('b531d474-b59c-0f1b-26a6-b39c160ff896', 'nemzetkozi-programok', 'widening', 'lista', 'Widening: a részvétel szélesítése és a kiválóság terjesztése', NULL, 'Magyarország a Horizont Európa widening-országai közé tartozik (WIDERA munkaprogram 2026–2027): magyar intézmények koordinálhatnak Teaming, Twinning, ERA Chairs, Excellence Hubs és más widening-projekteket, amelyek a kevésbé fejlett kutatási teljesítményű országok kapacitásait erősítik. Hazai tanácsadás: az NKFI Hivatal Widening NCP-je; a magyar vezetésű nemzetközi kutatást a hazai HU-rizont program is támogatja.', NULL, 8, '{"sorok":[{"nev":"Teaming for Excellence","url":"","megjegyzes":"Új vagy megújuló kiválósági központok widening-országokban, vezető külföldi intézményekkel kötött stratégiai partnerségben."},{"nev":"Twinning","url":"","megjegyzes":"Widening-országbeli koordinátor kutatóintézmény hálózatépítése uniós élvonalbeli partnerekkel, legalább két országból."},{"nev":"ERA Chairs","url":"","megjegyzes":"Kiemelkedő kutató vonzása widening-országbeli egyetemre vagy kutatóközpontba, saját, integrált kutatócsoporttal."},{"nev":"Excellence Hubs","url":"","megjegyzes":"Regionális innovációs ökoszisztémák erősítése az akadémia, a vállalatok, a kormányzat és a civil szféra összekapcsolásával."},{"nev":"Hop-on Facility","url":"","megjegyzes":"Widening-országbeli kutatóintézmények csatlakozása már futó II. pilléres és EIC Pathfinder projektekhez."},{"nev":"ERA Talents","url":"","megjegyzes":"Ágazatok közötti tehetségmobilitás és akadémia–vállalat együttműködés, widening-országbeli súlyponttal."},{"nev":"European Excellence Initiative","url":"","megjegyzes":"Egyetemek kiválóságának és földrajzilag befogadó együttműködésének erősítése felsőoktatási szövetségekben."},{"nev":"Pathways to Synergies","url":"","megjegyzes":"Regionális programok korábbi kedvezményezettjeinek felkészítése határokon átnyúló együttműködésre és Horizont Európa-pályázásra."},{"nev":"COST","url":"","megjegyzes":"A widening-programrész része is: kutatói hálózatok széles tématerületen (magyar koordinátor az NKFIH-ban)."},{"nev":"HU-rizont (hazai program)","url":"https://nkfih.gov.hu/hurizont","megjegyzes":"Magyar kutatók vezette nemzetközi kutatási projektek; felkészít a keretprogramok konzorciumvezetésére."}],"linkek":[{"felirat":"Widening participation and spreading excellence (Európai Bizottság)","url":"https://research-and-innovation.ec.europa.eu/funding/funding-opportunities/funding-programmes-and-open-calls/horizon-europe/widening-participation-and-spreading-excellence_en"},{"felirat":"WIDERA munkaprogram 2026–2027 (PDF)","url":"https://ec.europa.eu/info/funding-tenders/opportunities/docs/2021-2027/horizon/wp-call/2026-2027/wp-11-widening-participation-and-strengthening-the-european-research-area_horizon-2026-2027_en.pdf"},{"felirat":"Widening NCP (NKFIH)","url":"https://nkfih.gov.hu/hivatalrol/nemzetkozi-kapcsolatok/horizont-europa/nemzeti-kapcsolattarto-pontok"}]}');
